(window.GIM_TS=window.GIM_TS||{})["Megillah.0"]={"from":0,"a":[["\u0003מגילה נקראת\u0004 באחד מן הימים הללו: \u0003באחד עשר, בשנים עשר, בשלשה עשר, בארבעה עשר, בחמשה עשר\u0004 שבחודש אדר, \u0003לא פחות,\u0004 כלומר, לא לפני ימים אלה, \u0003ולא יותר,\u0004 לא לאחר ימים אלה. ומפרשים כיצד מזדמן שקוראים בכל אחד מן הימים הללו. כלל הוא כי \u0003כרכין המוקפין חומה מימות יהושע בן נון\u0004 קוראים \u0003בחמשה עשר\u0004 באדר, \u0003כפרים ועיירות גדולות\u0004 שאינן מוקפות חומה מימות יהושע — \u0003קורין\u0004 (קוראים) \u0003בארבעה עשר, אלא ש\u0004תיקנו כי \u0003הכפרים מקדימין ליום הכניסה,\u0004 לימי שני וחמישי שבהם היו בני הכפרים מתכנסים ובאים העירה לבית הדין, לקריאת התורה ולשאר צרכיהם.","ומעתה מפרש \u0003כיצד\u0004 מזדמן שיקראו בכל אחד מן הימים שנמנו; \u0003חל להיות ארבעה עשר\u0004 באדר \u0003ב\u0004יום \u0003שני\u0004 בשבוע — \u0003כפרים ועיירות גדולות קורין בו ביום, ומוקפות חומה\u0004 קוראות \u0003למחר.\u0004 הרי קריאה בארבעה עשר ובחמישה עשר. \u0003חל להיות\u0004 ארבעה עשר \u0003ב\u0004יום \u0003שלישי או ב\u0004יום \u0003רביעי\u0004 בשבוע — \u0003כפרים מקדימין ליום הכניסה\u0004 (יום שני) והם קוראים איפוא בשלושה עשר או בשנים עשר \u0003ועיירות גדולות קורין בו ביום, ומוקפות חומה\u0004 כדינן \u0003למחר.\u0004","\u0003חל להיות\u0004 ארבעה עשר \u0003ב\u0004יום \u0003חמישי\u0004 בשבוע — \u0003כפרים ועיירות גדולות קורין בו ביום ומוקפות חומה\u0004 קוראות \u0003למחר. חל להיות\u0004 ארבעה עשר ב\u0003ערב שבת — כפרים מקדימין ליום הכניסה\u0004 יום חמישי \u0003ועיירות גדולות ומוקפות חומה קורין בו ביום,\u0004 שאף המוקפות חומה אינן קוראות בשבת.","\u0003חל\u0004 ארבעה עשר \u0003להיות בשבת\u0004 — \u0003כפרים ועיירות גדולות מקדימין וקורין ליום הכניסה\u0004 יום חמישי (ואז קוראים בשנים עשר באדר) \u0003ומוקפות חומה\u0004 קוראות כדרכן \u0003למחר\u0004 ביום ראשון. \u0003חל להיות אחר השבת\u0004 (יום ראשון) — \u0003כפרים מקדימין ליום הכניסה\u0004, הוא יום חמישי, ונמצאו קוראים באחד עשר באדר \u0003ועיירות גדולות קורין בו ביום, ומוקפות חומה\u0004 קוראות \u0003למחר.\u0004","שנינו במשנה שה\u0003מגילה נקראת באחד עשר\u0004 באדר. ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 דין זה? על השאלה הזאת תוהים: \u0003מנלן\u0004 \u0005[מנין לנו]?!\u0006 מה מקום לשאלה זו? הלא הטעם הוא \u0003כדבעינן למימר לקמן\u0004 \u0005[כפי שאנחנו צריכים לומר לפנינו,\u0006 להלן\u0005]:\u0006 ה\u0003חכמים הקילו על הכפרים להיות מקדימין\u0004 וקוראים \u0003ליום הכניסה, כדי ש\u0004יהיו פנויים דיים ו\u0003יספקו מים ומזון לאחיהם שבכרכים\u0004 ביום הפורים, ואם כן טעמו של הדבר הוא משום תקנת חכמים.","ומסבירים: \u0003אנן הכי קאמרינן\u0004 \u0005[אנחנו כך אמרנו],\u0006 כלומר, זה הוא תוכן השאלה: \u0003מכדי\u0004 \u0005[הלא]\u0006 את קריאת הימים הללו \u0003כולהו\u0004 \u0005[כולם]\u0006 \u0003אנשי כנסת הגדולה תקנינהו\u0004 \u0005[תיקנום]\u0006 כאשר קבעו את חג הפורים עצמו, \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר ש\u0003אנשי כנסת גדולה\u0004 רק \u0003ארבעה עשר וחמשה עשר תקון\u0004 \u0005[תיקנו]\u0006 האם \u0003אתו רבנן ועקרי תקנתא דתקינו\u0004 \u0005[יבואו חכמים ויעקרו תקנה שתיקנו]\u0006 \u0003אנשי כנסת הגדולה? והתנן\u0004 \u0005[והרי\u0006 \u0005שנינו\u0006 במשנה\u0005]\u0006 כלל: \u0003אין בית דין יכול לבטל דברי בית דין חבירו אלא אם כן גדול ממנו בחכמה ובמנין\u0004 הדיינים, ובודאי לא היה בית דין גדול בישראל מבית דינם של אנשי כנסת הגדולה.","\u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שעלינו לומר כי הימים הללו \u0003כולהו\u0004 \u0005[כולם]\u0006 \u0003אנשי כנסת גדולה תקינו\u0004 \u0005[תיקנו\u0006 אותם\u0005]\u0006 ולכן יש לשאול: \u0003היכא רמיזא\u0004 \u0005[היכן רמוז\u0006 הדבר\u0005]?\u0006 שהרי במגילה, שהיא תקנת אנשי כנסת הגדולה, נאמר רק ארבעה עשר וחמישה עשר ולא יותר.","\u0003אמר רב שמן בר אבא אמר ר' יוחנן:\u0004 דבר זה נלמד ממה ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לקים את ימי הפרים האלה בזמניהם\"\u0004 (אסתר ט, לא), שמן המלה \"זמניהם\" משמע כי \u0003זמנים הרבה תקנו להם,\u0004 ולא שני ימים בלבד.","ושואלים: הלא \u0003האי מיבעיא ליה לגופיה\u0004 \u0005[\u0006פסוק \u0005זה נצרך לגופו],\u0006 לומר שאכן יקיימו את ימי הפורים בזמנים שקבעו להם! ודוחים: \u0003אם כן לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 רק \u0003\"\u0004לקיים דברי הפורים האלה ב\u0003זמן\", מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"זמניהם\"\u0004 בלשון רבים — \u0003זמנים טובא\u0004 \u0005[הרבה].\u0006","ושואלים: \u0003ואכתי מיבעי ליה\u0004 \u0005[ועדיין נצרך\u0006 לומר \u0005לו\u0006 בלשון רבים\u0005]\u0006 ללמדנו ש\u0003זמנו של זה\u0004 עיר מוקפת חומה \u0003לא כזמנו של זה\u0004 שאינה מוקפת, שיש הבדל בזמני חג הפורים במקומות שונים ולכן היה צורך לומר בלשון רבים. ומסבירים: \u0003אם כן,\u0004 אם לזה בלבד היתה הכוונה, \u0003לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 רק \u0003\"זמנם\u0004 \u0005\",\u0006 \u0003מאי\u0004 \u0005[מה לשון]\u0006 \u0003\"זמניהם\"\u0004 שהיא לשון־ריבוי כפולה \u0003— שמעת מינה כולהו\u0004 \u0005[שומע אתה ממנה את כולם],\u0006 שאף שבמקרא כתובים שני ימים בלבד, נרמז כאן שיש מקום להוסיף עוד זמנים אחרים.","ומקשים מצד אחר: אם כן \u0003אימא\u0004 [אמור] כי הכוונה היא לומר שיש \u0003זמנים טובא\u0004 [הרבה], והכוונה להוסיף ימים רבים לפני פורים, כגון אפילו בתשיעי ובעשירי, ומשיבים: מה שנאמר \u0003\"זמניהם\"\u0004 שהוא לשון ריבוי כפולה, הרי זה \u0003דומיא\u0004 \u0005[\u0006ב\u0005דומה]\u0006 ללשון \u0003\"זמנם\", מה\u0004 אילו היה כתוב \u0003\"זמנם\"\u0004 הרי זה \u0003תרי\u0004 \u0005[שני\u0006 ימים\u0005]\u0006 — ארבעה עשר וחמישה עשר המפורשים בכתוב, \u0003אף \"זמניהם\"\u0004 שיש בו ריבוי נוסף הוא \u0003תרי\u0004 \u0005[שנים]\u0006 נוספים ולא יותר.","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 ששני ימים נוספים אלה הם הימים \u0003תריסר ותליסר\u0004 \u0005[שנים עשר ושלושה עשר],\u0006 וכיצד יודעים אנו על יום אחד עשר? ומשיבים: כאן יש לתרץ \u0003כדאמר\u0004 \u0005[כפי שאמר]\u0006 להלן \u0003רב שמואל בר יצחק:\u0004 יום \u0003שלשה עשר\u0004 באדר \u0003זמן קהילה\u0004 (התקהלות, כינוס) \u0003לכל היא,\u0004 שהרי בשלושה עשר באדר נקהלו היהודים ונלחמו באויביהם ועיקרו של הנס היה באותו יום \u0003ולא צריך לרבויי\u0004 \u0005[לרבותו]\u0006 ולומר שיום זה ראוי לקריאה, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לענייננו, כיון ש\u0003שלשה עשר זמן קהילה לכל היא ולא צריך לרבויי\u0004 \u0005[לרבותו]\u0006 באופן מיוחד לקרוא בו.","ומקשים עוד: \u0003ואימא\u0004 \u0005[ואמור]\u0006 ששני הימים הנוספים הם \u0003שיתסר ושיבסר\u0004 \u0005[שישה עשר ושבעה עשר]!\u0006 ודוחים: הלא במגילה \u0003\"ולא יעבור\" כתיב\u0004 \u0005[נאמר]\u0006 (אסתר ט, כז), ללמד שאין מעבירים = מאחרים את חגיגת נס ימי הפורים לזמן מאוחר יותר. כל זה היה בירור טעם אחד בשם ר' יוחנן.","\u0003ור' שמואל בר נחמני אמר\u0004 רמז אחר יש לדבר: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"כימים אשר נחו בהם היהודים\"\u0004 (אסתר ט, כב), ונדייק: \u0003\"ימים\"\u0004 הרי שני הימים האמורים, \u0003\"כימים\" —\u0004 משמע שמוסיפים על הימים שנחו בהם עוד שני ימים, ומכאן יש \u0003לרבות\u0004 יום \u0003אחד עשר ושנים עשר.\u0004","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שבא הדבר לרבות יום \u0003תריסר ותליסר\u0004 \u0005[שנים עשר ושלושה עשר]!\u0006 על כך \u0003אמר רב שמואל בר יצחק:\u0004 יום \u0003שלשה עשר זמן קהילה\u0004 (התקהלות, כינוס) \u0003לכל היא, ולא צריך לרבויי\u0004 \u0005[לרבותו].\u0006 ומקשים: \u0003ואימא\u0004 \u0005[ואמור\u0006 אם כן\u0005]\u0006 שיהיו ימים נוספים אלה \u0003שיתסר ושיבסר\u0004 \u0005[שישה עשר ושבעה עשר]\u0006 באדר! ודוחים: \u0003\"ולא יעבור\" כתיב\u0004 \u0005[נאמר].\u0006","כיון שנאמרו שני רמזים לאותו ענין, שואלים: \u0003ר' שמואל בר נחמני מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר\u0004 את הראיה \u0003מ\u0004לשון הכתוב \u0003\"בזמניהם\"?\u0004 ומשיבים: דיוק־לשון זה שלומדים ממנו כפילות, שיש ריבוי אחר ריבוי בשינוי של \u0003\"זמן\" \"זמנם\" \"זמניהם\" לא משמע ליה\u0004 \u0005[נשמע,\u0006 נראה, \u0005לו]\u0006 ולדעתו יש כאן ריבוי רגיל של שני ימים בלבד.","ושואלים מצד שני: \u0003ורב שמן בר אבא מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר\u0004 ראיה כמו ר' שמואל בר נחמני \u0003מ\"כימים\"?\u0004 ומשיבים: \u0003אמר לך\u0004 \u0005[היה יכול לומר לך]:\u0006 הפ סוק \u0003ההוא לדורות הוא דכתיב\u0004 \u0005[שנאמר],\u0006 ומשמעו: כפי שנחו היהודים באותם ימים בעבר כן ינוחו ויעשו בהם שמחה לדורות.","על עיקרי ההלכה שבמשנה \u0003אמר רבה בר בר חנה אמר ר' יוחנן:\u0004 משנתנו \u0003זו — דברי ר' עקיבא סתימתאה\u0004 \u0005[הסותם],\u0006 כלומר, ר' עקיבא הידוע שדבריו הם המקור ל\"סתם משנה\" כמעט בכל מקום, שרוב המשניות שנאמרו סתם בלא שם אומרן הן כשיטתו או כשיטת תלמידיו \u0003דדריש\u0004 \u0005[ש\u0006הוא \u0005דורש]\u0006 את שינויי הלשון \u0003\"זמן\" \"זמנם\" \"זמניהם\", אבל חכמים אומרים: אין קורין אותה אלא בזמנה\u0004 בארבעה עשר ובחמישה עשר באדר.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]:\u0006 \u0003אמר ר' יהודה: אימתי\u0004 אמרו הלכה זו שקוראים מאחד עשר עד חמישה עשר — \u0003בזמן שהשנים כתיקנן וישראל שרויין על אדמתן\u0004 בשלווה, אז אפשר להוסיף ולקרוא ימים אחדים קודם ארבעה עשר, \u0003אבל בזמן הזה הואיל ומסתכלין בה\u0004 שעל פי זמן קריאת המגילה מחשבים אימתי יחול חג הפסח — \u0003אין קורין אותה אלא בזמנה,\u0004 כדי שלא תיגרם טעות בקביעת מועד חלות הפסח בשל השינוי ביום קריאת המגילה.","ומעתה נברר: \u0003ר' יהודה אליבא דמאן\u0004 \u0005[על פי\u0006 שיטת \u0005מי]\u0006 אמר מה שאמר? \u0003אילימא אליבא\u0004 \u0005[אם תאמר על פי\u0006 שיטתו\u0005]\u0006 של \u0003ר' עקיבא —\u0004 הרי לדעת ר' עקיבא, שהיא הדעה הסתמית שבמשנתנו — \u0003אפילו בזמן הזה איתא להאי תקנתא\u0004 \u0005[ישנה לאותה תקנה],\u0006 שהרי ר' עקיבא בזמן הזה הוא שהיה ועל אותו זמן אמר במשנה שמקדימים לקרוא את המגילה ולא פירש שהוא רק בזמן שישראל שרויים בשלווה,","\u0003אלא לאו אליבא דרבנן\u0004 \u0005[האם לא\u0006 שיטתו היא \u0005על פי שיטת חכמים]\u0006 שהיו לפניו וחולקים אמנם על דבריו, \u0003ו\u0004אם כן נמצא כי לדבריהם \u0003בזמן שהשנים כתיקנן וישראל שרויין על אדמתן — מיהא קרינן\u0004 \u0005[על כל פנים קוראים]\u0006 גם לפני ארבעה עשר ולא נחלקו חכמים אלא בשנים שאינן כתיקונן, והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על דברי \u0003ר' יוחנן!\u0004 ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא ונדחו דבריו.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ענין זה בלשון שונה במקצת: \u0003אמר רבה בר בר חנה אמר ר' יוחנן:\u0004 משנתנו \u0003זו\u0004 היא \u0003דברי ר' עקיבא סתימתאה\u0004 \u0005[הסותם],\u0006 \u0003אבל חכמים אמרו: בזמן הזה,\u0004 שקיימות בעיות בהודעת קביעת החדשים למקומות מרוחקים, \u0003הואיל ומסתכלין בה\u0004 ויודעים שהפסח חל בדיוק חודש ימים לאחר הפורים — \u0003אין קורין אותה אלא בזמנה,\u0004 כדי שלא יבואו לידי מכשול.","ועל כך מעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 כדברי ר' יוחנן, \u0003אמר ר' יהודה: אימתי\u0004 נאמרו דברי המשנה — \u0003בזמן שהשנים כתיקנן וישראל שרויין על אדמתן\u0004 ולא קיימות בעיות בהעברת ידיעות אף למקומות מרוחקים וזמן קביעת החודש יוודע לכל, \u0003אבל בזמן הזה, הואיל ומסתכלין בה — אין קורין אותה אלא בזמנה,\u0004 ולפי זה, ר' יוחנן אמר ופירש את הדברים כפי שהברייתא מוסרת בשם רבי יהודה.","ובאותו ענין, מוסיפים ואומרים: \u0003רב אשי קשיא ליה\u0004 \u0005[\u0006היה \u0005קשה לו]\u0006 משיטת \u0003ר' יהודה\u0004 כאן על שיטת \u0003ר' יהודה\u0004 עצמו במקום אחר,"],["\u0003ומוקים לה\u0004 \u0005[ומעמיד אותה]\u0006 את ה\u0003ברייתא\u0004 שנביא מיד, \u0003כ\u0004שיטת \u0003ר' יוסי בר יהודה\u0004 ועל ידי כך אין עוד סתירה.","וזו היתה הקושיה: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יהודה\u0004 כי \u0003בזמן הזה הואיל ומסתכלין בה, אין קורין אותה אלא בזמנה? ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממקור אחר, \u0003אמר ר' יהודה: אימתי\u0004 אמרו שימי הפורים הם מאחד עשר באדר והלאה — \u0003מקום שנכנסין\u0004 בני הכפרים אל העיר \u0003ב\u0004יום \u0003שני ו\u0004ביום \u0003חמישי\u0004 בשבוע, \u0003אבל מקום שאין נכנסין\u0004 כרגיל \u0003בשני ובחמישי — אין קורין אותה אלא בזמנה.\u0004","ומעתה נדייק: \u0003מקום שנכנסין בשני וחמישי מיהא קרינן\u0004 \u0005[על כל פנים\u0006 מקדימים ו\u0005קוראים אנו]\u0006 כבר מאחד עשר, \u0003ואפילו בזמן הזה! ומוקים לה\u0004 \u0005[ומעמיד אותה]\u0006 את ה\u0003ברייתא כ\u0004דברי \u0003ר' יוסי בר יהודה.\u0004","על דבר זה תוהים: \u0003ומשום דקשיא ליה\u0004 \u0005[שקשה לו]\u0006 מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה מוקים לה\u0004 \u0005[מעמיד אותה]\u0006 את ה\u0003ברייתא כר' יוסי בר יהודה?!\u0004 כיצד משנים גירסה רק משום שנתקלנו בקושיה שאיננו יודעים ליישבה?","ומסבירים: לא כך היה המעשה, אלא \u0003רב אשי שמיע ליה דאיכא דתני לה\u0004 \u0005[שמע שיש ששונה אותה]\u0006 את הברייתא הזו בשמו של \u0003ר' יהודה, ואיכא דתני לה\u0004 \u0005[ויש ששונה אותה]\u0006 בשמו של \u0003ר' יוסי בר יהודה, ומדקשיא ליה\u0004 \u0005[ומ\u0006כיוון \u0005ש\u0006היה \u0005קשה לו]\u0006 מדברי \u0003ר' יהודה\u0004 על דברי \u0003ר' יהודה, אמר: מאן דתני לה\u0004 \u0005[מי ששונה אותה]\u0006 \u0003כ\u0004דברי \u0003ר' יהודה\u0004 — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003דווקא,\u0004 אינו מדוייק, ו\u0003מאן דתני לה\u0004 \u0005[ומי ששונה אותה]\u0006 \u0003כ\u0004דברי \u0003ר' יוסי בר יהודה\u0004 — \u0003דווקא,\u0004 מדוייק, שהרי על ידי כך נמנעת הסתירה.","שנינו במשנה: \u0003כרכים המוקפים חומה מימות יהושע בן נון קורין בחמשה עשר\u0004 באדר. ושואלים: \u0003מנהני מילי\u0004 \u0005[מניין הדברים הללו]?\u0006 שהרי אינם כתובים במפורש במגילה! \u0003אמר רבא:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"על כן היהודים הפרזים הישבים בערי הפרזות\u0004 עושים את יום ארבעה עשר לחודש אדר\u0003\"\u0004 (אסתר ט, יט), \u0003ומ\u0004כיון שה\u0003פרזים\u0004 עושים \u0003בארבעה עשר\u0004 נלמד שה\u0003מוקפין\u0004 עושים \u0003בחמשה עשר.\u0004","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 כך: \u0003פרזים — בארבעה עשר\u0004 כמאמר הכתוב, \u0003מוקפין — כלל כלל לא!\u0004 ותוהים: כיצד אפשר לומר זאת, \u0003ולאו\u0004 \u0005[ו\u0006כי \u0005לא]\u0006 \u0003ישראל נינהו\u0004 \u0005[הם]?\u0006 \u0003ועוד:\u0004 הלא \u0003\"מהדו ועד כוש\"\u0004 (אסתר א, א) \u0003כתיב\u0004 \u0005[נאמר]\u0006 שהיתה מלכות אחשורוש, ונאמר שימי הפורים נתקבלו בכל מדינות מלכותו.","אלא כך יש להקשות: \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003פרזים\u0004 עושים פורים \u0003בארביסר\u0004 \u0005[ב\u0006יום ה\u0005ארבעה עשר]\u0006 ו\u0003מוקפין\u0004 עושים \u0003בארביסר ובחמיסר\u0004 \u0005[ב\u0006יום ה\u0005ארבעה עשר ו\u0006גם \u0005ב\u0006יום ה\u0005חמישה עשר],\u0006 וכעין ראיה לדבר, \u0003כדכתיב\u0004 \u0005[כפי שנאמר]:\u0006 \u0003\"להיות עשים את יום ארבעה עשר לחדש אדר ואת יום חמשה עשר בו בכל שנה\u0004 ושנה\u0003\"\u0004 (אסתר ט, כא), ומשמע לכאורה שיש שעושים את הפורים בשני הימים.","ודוחים: \u0003אי הוה כתב\u0004 \u0005[אילו היה נאמר]\u0006 בפסוק \u0003\"את יום ארבעה עשר וחמשה עשר\" —\u0004 אכן היה \u0003כדקאמרת\u0004 \u0005[כמו שאתה אומר],\u0006 \u0003השתא דכתיב\u0004 \u0005[עכשיו שנאמר\u0006 בפסוק\u0005]\u0006 \u0003\"את יום ארבעה עשר ואת יום חמשה עשר\"\u0004 הרי \u0003אתא\u0004 \u0005[באה]\u0006 המלה \u0003\"את\" ופסיק\u0004 \u0005[והפסיקה],\u0006 לומר שאין עושים את שני הימים, אלא \u0003הני\u0004 \u0005[אלה]\u0006 \u0003בארבעה עשר, והני\u0004 \u0005[ואלה]\u0006 \u0003בחמשה עשר.\u0004","ומקשים עוד: \u0003ואימא\u0004 \u0005[ואמור]\u0006 כך: \u0003פרזים\u0004 עושים \u0003בארביסר\u0004 \u0005[בארבעה עשר]\u0006 ככתוב, \u0003מוקפין — אי בעו בארביסר, אי בעו בחמיסר\u0004 \u0005[אם רוצים\u0006 עושים \u0005בארבעה עשר, אם רוצים\u0006 עושים \u0005בחמישה עשר]!\u0006 ודוחים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"בזמניהם\",\u0004 ללמדנו כי \u0003זמנו של זה לא זמנו של זה.\u0004","ומקשים עוד: \u0003ואימא בתליסר\u0004 \u0005[ואמור\u0006 שיחוגו \u0005ב\u0006יום \u0005שלושה עשר]\u0006 ולא בחמישה עשר! ומשיבים: מסתבר שעושים זאת \u0003כ\u0004פי שעשו ב\u0003שושן\u0004 שמפורש שחגגו בה ביום חמישה עשר, ומסתבר שכך עושים כל אלה שאינם חוגגים ביום ארבעה עשר.","ומעירים: \u0003אשכחן\u0004 \u0005[למדנו]\u0006 מכאן את ה\u0003עשייה,\u0004 כלומר, את מצוות הפורים שיש בהן צד עשייה, כגון משתה ויום טוב, אולם \u0003זכירה\u0004 שמזכירים, כלומר, שבאותם ימים אף קוראים בני אותם מקומות את המגילה, \u0003מנלן\u0004 \u0005[מניין לנו]?\u0006 ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"והימים האלה נזכרים ונעשים\"\u0004 (אסתר ט, כח), הרי בפסוק \u0003איתקש\u0004 \u0005[הוקשה,\u0006 השוותה\u0005]\u0006 \u0003זכירה לעשייה.\u0004","על עצם ההלכה המובאת במשנה, מעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כי האי תנא\u0004 \u0005[כ\u0006שיטת \u0005תנא זה]\u0006 שתובא מיד. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בתוספתא\u0005],\u0006 \u0003ר' יהושע בן קרחה אומר: כרכין המוקפין חומה מימות אחשורוש — קורין בחמשה עשר,\u0004 ואין הגדרתם תלויה בזמן יהושע,","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 דבריו של \u0003ר' יהושע בן קרחה?\u0004 ומסבירים: \u0003כי\u0004 \u0005[כמו]\u0006 \u0003שושן, מה שושן\u0004 היא עיר \u0003מוקפת חומה מימות אחשורוש, וקורין\u0004 בה \u0003בחמשה עשר — אף כל\u0004 עיר \u0003שמוקפת חומה מימות אחשורוש קורין בחמשה עשר.\u0004","ושואלים: \u0003ו\u0004ה\u0003תנא דידן\u0004 \u0005[שלנו],\u0006 שהוא תולה את הדבר בזמן יהושע \u0003מאי טעמיה\u0004 \u0005[מה טעמו]?\u0006 ומסבירים: \u0003יליף\u0004 \u0005[לומד]\u0006 הוא גזירה שווה על ידי המילים \u0003\"פרזי\" \"פרזי\". כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"על כן היהודים הפרזים\u0004 היושבים בערי הפרזות\u0003\"\u0004 (אסתר ט, יט), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בדבריו של משה לפני כניסת יהושע לארץ: \u0003\"\u0004כל אלה ערים בצורות חומה גבוהה דלתים ובריח \u0003לבד מערי הפרזי הרבה מאד\"\u0004 (דברים ג, ה), \u0003מה להלן\u0004 בספר דברים, מדובר בעיר \u0003מוקפת חומה מימות יהושע בן נון, אף כאן\u0004 מדובר בעיר \u0003מוקפת חומה מימות יהושע בן נון.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 ש\u0003ר' יהושע בן קרחה לא אמר כ\u0004שיטת ה\u0003תנא דידן\u0004 \u0005[שלנו],\u0006 משום \u0003דלית ליה\u0004 \u0005[שאין לו,\u0006 שאינו מקבל\u0005]\u0006 את הגזירה השווה \u0003\"פרזי\" \"פרזי\", אלא\u0004 ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כ\u0004דברי \u0003ר' יהושע בן קרחה?\u0004","על שאלה זו תוהים: \u0003מאי טעמא\u0004 \u0005[מה טעם]?!\u0006 \u0003דהא אית ליה\u0004 \u0005[שהרי יש לו]\u0006 גזירה שווה של \u0003\"פרזי\" \"פרזי\"!\u0004 ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 זו היתה השאלה: \u0003אלא\u0004 לשיטת התנא שלנו, \u0003שושן, דעבדא כמאן\u0004 \u0005[שעושה\u0006 פורים \u0005כמי]\u0006 היא עושה? \u0003לא כפרזים ולא כמוקפין,\u0004 שהרי בשושן חוגגים בחמישה עשר, כמפורש בכתוב, ועיר זו הלא איננה מוקפת חומה מימות יהושע בן נון!","\u0003אמר רבא, ואמרי לה כדי\u0004 \u0005[ויש אומרים אותה סתם]\u0006 בלא לייחס מאמר זה לחכם מסויים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003שושן הואיל ונעשה בה נס\u0004 ביום זה, ומשום כך אף יש לחגוג בה ביום זה, אבל בשאר הערים יש לחלק בין אלה המוקפות חומה מימות יהושע בן נון לאלה שאינן כאלה.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת ה\u0003תנא דידן\u0004 \u0005[שלנו],\u0006 \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"\u0004והימים האלה נזכרים ונעשים בכל דור ודור משפחה ומשפחה \u0003מדינה ומדינה ועיר ועיר\"\u0004 (אסתר ט, כח), ולשיטתו כך מתפרש הכתוב: \u0003\"מדינה ומדינה\"\u0004 עניינו — \u0003לחלק בין\u0004 כרכים ה\u0003מוקפין חומה מימות יהושע בן נון\u0004 שבה נקראת המגילה בחמישה עשר \u0003ל\u0004עיר ה\u0003מוקפת חומה מימות אחשורוש\u0004 שבה נקראת המגילה בארבעה עשר,","\u0003\"עיר ועיר\" נמי\u0004 \u0005[גם כן],\u0006 כדי \u0003לחלק בין שושן לשאר עיירות,\u0004 ששושן, אף שלפי ההגדרה אינה כרך המוקף חומה — עושים בה פורים בחמישה עשר, וכל שאר ערים אחרות שאינן מוקפות עושות בארבעה עשר. \u0003אלא לר' יהושע בן קרחה, בשלמא\u0004 \u0005[נניח]\u0006 שהוא מפרש \u0003\"מדינה ומדינה\",\u0004 שבא \u0003לחלק בין שושן\u0004 וכיוצא בה \u0003לשאר עיירות\u0004 שאינן מוקפות מימי אחשורוש, \u0003אלא \"עיר ועיר\" למאי אתא\u0004 \u0005[למה,\u0006 לאיזה צורך \u0005בא]?\u0006","ומשיבים: \u0003אמר\u0004 \u0005[יכול היה לומר]\u0006 \u0003לך ר' יהושע בן קרחה: ול\u0004שיטת ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 \u0003מי ניחא\u0004 \u0005[האם\u0006 זה \u0005נוח]?\u0006 \u0003כיון דאית ליה\u0004 \u0005[שיש לו]\u0006 גזירה שווה של \u0003\"פרזי\" \"פרזי\",\u0004 אם כן \u0003\"מדינה ומדינה\" למה לי\u0004 ולשם מה דרשה זו מפסוק אחר? \u0003אלא קרא\u0004 \u0005[הכתוב]\u0006 \u0003לדרשה\u0004 אחרת \u0003הוא דאתא\u0004 \u0005[שבא],\u0006 \u0003וכ\u0004דברי \u0003ר' יהושע בן לוי הוא דאתא\u0004 \u0005[שבא],\u0006 ש\u0003אמר ר' יהושע בן לוי: כרך וכל\u0004 מקום \u0003הסמוך לו, וכל הנראה עמו\u0004 שאפשר לראותו משם, גם אם איננו סמוך, \u0003נידון\u0004 לענין זמן קריאת המגילה \u0003כ\u0004אותו \u0003כרך\u0004 ואף בו קוראים בחמישה עשר.","ושואלים: \u0003עד כמה\u0004 נקרא סמוך? \u0003אמר ר' ירמיה ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' חייא בר אבא:\u0004 המרחק הוא \u0003כ\u0004מו מן העיירה \u0003חמתן לטבריא\u0004 (טבריה) — \u0003מיל\u0004 אחד. ושואלים: לשם מה הוא מזכיר את המקומות הללו כדי לציין את המרחק? \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 מיד \u0003מיל!\u0004 ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]:\u0006 \u0003דשיעורא\u0004 \u0005[ששיעורו]\u0006 של \u0003מיל כמה הוי\u0004 \u0005[הוא] —\u0006 \u0003כמחמתן לטבריא.\u0004","כיון שהובא דבר בשם ר' ירמיה, שהיה ספק אולי אמרו ר' חייא בר אבא, מביאים ענין נוסף שנמסר גם הוא בצורה זו. \u0003ואמר ר' ירמיה ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' חייא בר אבא: מנצפ\"ך\u0004 האותיות שיש להן צורה אחרת כשהן באות בסוף מלה — \u0003צופים\u0004 (נביאים) \u0003אמרום,\u0004 שהם חידשו ויצרו את האותיות הסופיות.","ותוהים: \u0003ותסברא\u0004 \u0005[ויכול אתה לסבור\u0006 כן\u0005]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"אלה המצות\u0004 אשר צוה ה' את משה אל בני ישראל בהר סיני\u0003\"\u0004 (ויקרא כז, לד), ללמדנו \u0003שאין נביא רשאי לחדש דבר מעתה,\u0004 שאין הנביאים רשאים לחדש או לשנות ממצוות התורה, וכיצד תיקנו הנביאים צורות חדשות לאותיות? \u0003ועוד,\u0004 ראיה נוספת שהאותיות הסופיות קדומות מאוד, \u0003האמר\u0004 \u0005[\u0006ש\u0005הרי אמר]\u0006 \u0003רב חסדא: מ\"ם וסמ\"ך שבלוחות\u0004 הברית"],["\u0003בנס היו עומדים\u0004 כי האותיות שבלוחות הברית היו חקוקות, ולמדנו מן המסורת שחקיקתם היתה מעבר לעבר. אכן, רוב האותיות, גם אם הן חקוקות יכולות לעמוד, לפי שיש בהן חלק מסויים המחובר אל השטח שמסביבן, מה שאין כן האות סמ\"ך (שהיא עיגול) ולכן החלק האמצעי שלה איננו יכול להיות חקוק כולו אלא אם כן במעשה ניסים, וכן מ\"ם סופית, וכיוון שנאמר ששתי האותיות הללו עמדו בנס, משמע שהיתה כבר מ\"ם סופית בלוחות הברית?","ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003מהוה הוו\u0004 \u0005[היה היו]\u0006 שני סוגי האותיות סגורות ופתוחות \u0003ולא הוו ידעי\u0004 \u0005[ולא היו יודעים],\u0006 לא היתה קביעות, \u0003הי\u0004 \u0005[איזה\u0006 מהן\u0005]\u0006 \u0003באמצע תיבה\u0004 (מלה) \u0003והי\u0004 \u0005[ואיזה\u0006 מהן\u0005]\u0006 \u0003בסוף תיבה ואתו\u0004 \u0005[ובאו]\u0006 \u0003צופים\u0004 (נביאים) \u0003ותקינו\u0004 \u0005[ותיקנו]\u0006 שה\u0003פתוחין\u0004 יהיו \u0003באמצע תיבה וסתומין בסוף תיבה.\u0004","ומקשים: \u0003סוף סוף\u0004 הלא נאמר \u0003\"אלה המצות\"\u0004 (ויקרא כז, לד), ללמד \u0003שאין נביא עתיד לחדש דבר מעתה,\u0004 ואף זה עצמו חידוש הוא! אלא יש לומר: האותיות הסופיות היו קיימות בזמן מתן תורה, \u0003אלא שכחום\u0004 במשך הדורות \u0003וחזרו\u0004 הנביאים \u0003ויסדום.\u0004","ועוד בשם אותה מסורת: \u0003אמר ר' ירמיה ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' חייא בר אבא: תרגום של תורה\u0004 המצוי בארמית ומשתמשים בו בבתי הכנסת, \u0003אונקלוס הגר אמרו מפי\u0004 (על פי הדרכת) \u0003ר' אליעזר ור' יהושע. תרגום של נביאים יונתן בן עוזיאל אמרו מפי,\u0004 כלומר, על פי מסורת שנבעה מאת \u0003חגי זכריה ומלאכי,\u0004 הנביאים האחרונים. מסופר: כשעשה יונתן בן עוזיאל תרגום זה \u0003נזדעזעה ארץ ישראל ארבע מאות פרסה על ארבע מאות פרסה,\u0004 ו\u0003יצתה\u0004 (יצאה) \u0003בת קול ואמרה: מי הוא זה שגילה סתריי לבני אדם?\u0004","\u0003עמד יונתן בן עוזיאל על רגליו ואמר: אני הוא\u0004 זה \u0003שגליתי סתריך לבני אדם\u0004 בתרגום זה, אולם \u0003גלוי וידוע לפניך שלא לכבודי עשיתי, ולא לכבוד בית אבא, אלא לכבודך עשיתי, שלא ירבו מחלוקת בישראל,\u0004 שאם אין תרגום מקובל לפסוקים סתומים, יבואו לידי מחלוקת בדבר משמעותם, ועל ידי התרגום מתברר הפירוש.","\u0003ועוד ביקש\u0004 יונתן בן עוזיאל \u0003לגלות\u0004 גם \u0003תרגום של כתובים, יצתה בת קול ואמרה לו: דייך!\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם] —\u0006 \u0003משום דאית ביה\u0004 \u0005[שיש בו]\u0006 גילוי \u0003קץ\u0004 מתי יבוא ה\u0003משיח\u0004 שהקץ נאמר באופן סתום בספר דניאל, ואם יתורגם ספר דניאל הרי יתגלה על ידי כך הקץ.","ושואלים: \u0003ותרגום של תורה,\u0004 האם \u0003אונקלוס הגר אמרו? והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב איקא בר אבין אמר רב חננאל אמר רב: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 בימי עזרא: \u0003\"ויקראו בספר תורת האלהים מפרש ושום שכל ויבינו במקרא\"\u0004 (נחמיה ח, ח) — כך יש לפרש: \u0003\"ויקראו בספר תורת האלהים\" — זה מקרא\u0004 שקראו בו ככתוב. \u0003\"מפרש\" — זה תרגום\u0004 שתרגמו מיד את המקרא לארמית, כדרך שנהגו במשך דורות לתרגם בבית הכנסת.","\u0003\"ושום שכל\" — אלו הפסוקין\u0004 שלא קראו את הכל כאחד, אלא מחולק לפסוקים. \u0003\"ויבינו במקרא\" — אלו פיסקי טעמים\u0004 השונים, שעל ידם מתבררת יותר משמעות המקרא, \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 כי \u0003אלו המסורת\u0004 — לגבי שימוש ומציאות כל מלה, משמע שתרגום היה קיים כבר בראשית ימי בית שני! ומשיבים: \u0003שכחום וחזרו ויסדום,\u0004 שאף התרגום נשכח מפי הבריות, ואחר כך חזרו ופירסמוהו.","אגב כך שואלים: \u0003מאי שנא דאורייתא\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 תרגום \u0005התורה]\u0006 שעליו \u0003לא אזדעזעה\u0004 \u0005[נזדעזעה]\u0006 הארץ \u0003ואדנביאי\u0004 \u0005[ועל\u0006 תרגום דברי \u0005הנביאים]\u0006 \u0003אזדעזעה\u0004 \u0005[נזדעזעה]?\u0006 ומסבירים: \u0003דאורייתא מיפרשא מלתא\u0004 \u0005[בתורה מפורשים דבריה]\u0006 ולכן אין בתרגום התורה משום גילוי סתרים, אולם \u0003דנביאי איכא מילי דמיפרשן ואיכא מילי דמסתמן\u0004 \u0005[בנביאים יש דברים ש\u0006הם \u0005מפורשים ויש דברים ש\u0006הם \u0005סתומים]\u0006 כגון הפסוק \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ביום ההוא יגדל המספד בירושלים כמספד הדדרימון בבקעת מגידון\"\u0004 (זכריה יב, יא),","\u0003ואמר רב יוסף: אלמלא תרגומא דהאי קרא\u0004 \u0005[תרגומו של כתוב זה]\u0006 \u0003לא ידענא\u0004 \u0005[הייתי יודע]\u0006 \u0003מאי קאמר\u0004 \u0005[מה הוא אומר],\u0006 כי לא מצאנו במקרא מעשה זה של הדדרימון בבקעת מגידון. ואילו התרגום מסביר כך: \u0003ביומא\u0004 \u0005[ביום]\u0006 \u0003ההוא יסגי מספדא\u0004 \u0005[יגדל המספד]\u0006 \u0003בירושלים כמספדא\u0004 \u0005[כמספד]\u0006 \u0003אחאב בר עמרי דקטל יתיה\u0004 \u0005[שהרג אותו]\u0006 \u0003הדדרימון בן טברימון ברמות גלעד וכמספדא\u0004 \u0005[וכמספד]\u0006 \u0003יאשיה בר אמון דקטל יתיה\u0004 \u0005[שהרג אותו]\u0006 \u0003פרעה חגירא\u0004 \u0005[נכה]\u0006 \u0003בבקעת מגידו\u0004 ולולי התרגום היה הפסוק נשאר סתום ובלתי מובן.","ועוד דברים בשם אותה מסורת, נאמר במקרא: \u0003\"וראיתי אני דניאל לבדי את המראה והאנשים אשר היו עמי לא ראו את המראה אבל חרדה גדלה נפלה עליהם ויברחו בהחבא\"\u0004 (דניאל י, ז). ושאלו: \u0003מאן נינהו\u0004 \u0005[מי הם]\u0006 אותם \u0003אנשים?\u0004 כי \"אנשים\" — משמע אנשים חשובים, ומי איפוא היו אלה? \u0003אמר ר' ירמיה ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' חייא בר אבא: זה\u0004 הנביאים \u0003חגי וזכריה ומלאכי,\u0004","ומעירים: בדברים מסויימים \u0003אינהו עדיפי מיניה\u0004 \u0005[הם עדיפים ממנו],\u0006 מדניאל, \u0003ואיהו\u0004 \u0005[ו\u0006בדברים מסויימים \u0005הוא],\u0006 דניאל, \u0003עדיף מינייהו\u0004 \u0005[מהם].\u0006 \u0003אינהו עדיפי מיניה\u0004 \u0005[הם עדיפים ממנו] —\u0006 \u0003דאינהו נביאי\u0004 \u0005[שהם נביאים]\u0006 \u0003ואיהו לאו\u0004 \u0005[והוא לא]\u0006 \u0003נביא\u0004 הוא, כי חגי זכריה ומלאכי נשלחו להתנבא לישראל בדבר ה' ואילו דניאל לא היה נביא־שליח ולא נשלח לגלות את חזונותיו לאחרים. ואילו מצד אחר \u0003איהו\u0004 \u0005[הוא]\u0006 \u0003עדיף מינייהו\u0004 \u0005[מהם]\u0006 — \u0003דאיהו חזא\u0004 \u0005[שהוא ראה]\u0006 \u0003ואינהו\u0004 \u0005[והם]\u0006 \u0003לא חזו\u0004 \u0005[ראו]\u0006 את המראה, הרי שכוחו בראיית הסתומות גדול היה משלהם,","ושואלים לגופו של ענין: \u0003וכי מאחר\u0004 ש\u0003לא חזו\u0004 \u0005[ראו],\u0006 \u0003מאי טעמא איבעיתו\u0004 \u0005[מה טעם נבהלו]?\u0006 ומדוע ברחו? ומשיבים: \u0003אף על גב דאינהו לא חזו מזלייהו חזו\u0004 \u0005[אף על פי שהם\u0006 עצמם \u0005לא ראו, מזלם,\u0006 נשמתם \u0005ראתה]\u0006 והבחינה בדבר, ולכן הרגישו שיש משהו מבעית במקום, וברחו.","\u0003אמר רבינא: שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003האי מאן דמיבעית, אף על גב דאיהו לא חזי, מזליה חזי\u0004 \u0005[מי שנבהל\u0006 בלא סיבה, \u0005אף על פי שהוא לא רואה\u0006 ואינו מרגיש את הסיבה לכך, \u0005מזלו רואה\u0006 אותה\u0005]\u0006 ולכן צריך לעשות דבר מה כדי להמלט מן הסכנה הזו, ושואלים: \u0003מאי תקנתיה\u0004 \u0005[מה תקנתו]?\u0006 \u0003ליקרי\u0004 \u0005[שיקרא]\u0006 \u0003קריאת שמע\u0004 שתגן עליו, \u0003ואי קאים\u0004 \u0005[ואם עומד]\u0006 \u0003במקום הטנופת\u0004 שאסור לקרוא בו דברי תורה, \u0003לנשוף מדוכתיה\u0004 \u0005[שיקפוץ ממקומו]\u0006 \u0003ארבע גרמידי\u0004 \u0005[אמות]\u0006 ויעבור למקום אחר שבו אין סכנה אורבת לו, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא,\u0004 שאינו יכול — \u0003לימא הכי\u0004 \u0005[שיאמר כך],\u0006 לחש זה כסגולה: \u0003\"עיזא דבי טבחי שמינא מינאי\"\u0004 \u0005[העז של בית המטבחיים שמנה ממני]\u0006 ואם צריכה לבוא פורענות — שתבוא עליה.","עתה חוזרים לעסוק בגופו של הענין שהוזכר קודם. \u0003והשתא\u0004 \u0005[ועכשיו]\u0006 ש\u0003אמרת\u0004 שהכתוב \u0003\"מדינה ומדינה\"\u0004 וכן הכתוב \u0003\"ועיר ועיר\"\u0004 באים \u0003לדרשה,\u0004 אם כן, \u0003\"משפחה ומשפחה\"\u0004 הכתוב באותו פסוק (אסתר ט, כח) \u0003למאי אתא\u0004 \u0005[למה\u0006 הוא \u0005בא],\u0006 מה הוא בא ללמדנו? \u0003אמר ר' יוסי בר חנינא:\u0004 הרי זה בא \u0003להביא\u0004 (לרבות) אף \u0003משפחות כהונה ולויה שמבטלין\u0004 (מפסיקים) \u0003עבודתן\u0004 במקדש \u0003ובאין לשמוע מקרא מגילה.\u0004","ש\u0003אמר רב יהודה אמר רב: כהנים בעבודתן ולוים בדוכנן\u0004 (שעומדים על הדוכן ושרים במקדש) \u0003וישראל במעמדן,\u0004 אותם אנשים מישראל שהיו באים לירושלים ומתאספים בשאר מקומות וקוראים פסוקים מענין מעשה בראשית כנציגי העם בעבודת הקודש עם כל משמר כהנים — \u0003כולן מבטלין עבודתן ובאין לשמוע מקרא מגילה.\u0004","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003כהנים בעבודתן, ולוים בדוכנן, וישראל במעמדן\u0004 — \u0003כולן מבטלין עבודתן ובאין לשמוע מקרא מגילה.\u0004 ו\u0003מכאן סמכו\u0004 החכמים \u0003של בית רבי ש\u0004היו \u0003מבטלין תלמוד תורה ובאין לשמוע מקרא מגילה\u0004 ולמדו זאת ב\u0003קל וחומר מעבודה; ומה עבודה\u0004 שבמקדש \u0003שהיא חמורה,\u0004 בכל זאת \u0003מבטלינן\u0004 \u0005[מבטלים אנו]\u0006 אותה מפני מקרא מגילה — \u0003תלמוד תורה\u0004 שהוא קל ממנה, \u0003לא כל שכן.\u0004","ומקשים: וכי \u0003עבודה חמורה מתלמוד תורה? והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ויהי בהיות יהושע ביריחו וישא עיניו וירא והנה איש עמד לנגדו\u0004 וחרבו שלופה בידו וילך יהושע אליו ויאמר לו הלנו אתה אם לצרינו. ויאמר לא כי אני שר צבא ה' עתה באתי ויפול יהושע על פניו \u0003וישתחו\"\u0004 (יהושע ה, יג-יד).","לפני הדיון לענייננו שואלים על הפסוק כשלעצמו: \u0003והיכי עביד הכי\u0004 \u0005[וכיצד\u0006 יהושע \u0005עשה כך]\u0006 שהשתחווה למראה שאינו מכיר? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יהושע בן לוי: אסור לאדם שיתן שלום לחבירו בלילה,\u0004 אם אינו מכירו, כי \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא שד הוא!\u0004 ומניין ידע יהושע שאיננו שד? ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו איש שראה בפירוש: \u0003\"כי אני שר צבא ה'\"\u0004 (יהושע ה, יד).","ושואלים שוב: \u0003ודלמא משקרי\u0004 \u0005[ושמא\u0006 שד היה \u0005ושיקר\u0006 ואמר כך\u0005]?\u0006 ומשיבים: \u0003גמירי\u0004 \u0005[למודים אנו\u0006 מן המסורת\u0005]\u0006 ש\u0003לא מפקי\u0004 \u0005[מוציאים]\u0006 השדים \u0003שם שמים לבטלה,\u0004 וכיון שהזכיר שם שמים היה יהושע בטוח שאכן מלאך הוא.","ולגופו של דבר מפרשים את שליחותו של המלאך כך, ש\u0003אמר לו\u0004 המלאך: \u0003אמש בטלתם\u0004 קרבן \u0003תמיד של בין הערבים,\u0004 שלא הוקרב בשל המלחמה \u0003ועכשיו בטלתם תלמוד תורה\u0004 ובאתי להזהירכם על כך. \u0003אמר לו\u0004 יהושע: \u0003על איזה מהן באת? אמר לו: \"עתה באתי\"\u0004 (יהושע ה, יד), שעל העבירה השניה הנוכחית בא, ו\u0003מיד\u0004 עשה יהושע תיקון לדבר, ולעת המצור הבא, שצרו על העי, אכן נאמר: \u0003\"וילן יהושע בלילה ההוא בתוך העמק\"\u0004 (יהושע ח, יג), \u0003אמר ר' יוחנן:\u0004"],["\u0003מלמד שלן בעומקה של הלכה\u0004 שעסק בתורה עם ישראל. \u0003ו\u0004כן \u0003אמר רב שמואל בר אוניא: גדול תלמוד תורה יותר מהקרבת תמידין, שנאמר: \"עתה באתי\"\u0004 (יהושע ה, יד), שהרי בא על ביטול תורה ולא על החסרת הקרבן. ואם כן כיצד החליטו בני בית רבי שעבודה חשובה יותר מתלמוד תורה?","ומשיבים: דבר זה \u0003לא קשיא\u0004 \u0005[קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שהוא חשוב יותר מעבודה, הרי זה בתלמוד תורה של \u0003רבים, והא\u0004 \u0005[וזה]\u0006 של בית רבי, היה זה בתלמוד תורה של \u0003יחיד.\u0004","ומקשים: \u0003ו\u0004האם תלמוד תורה של \u0003יחיד קל? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003נשים ב\u0004חול ה\u0003מועד מענות\u0004 (אומרות כולן כאחת דברי קינה), \u0003אבל לא מטפחות\u0004 בידים או על גופן כביטוי של אבל, ו\u0003ר' ישמעאל אומר: אם היו סמוכות למטה\u0004 שעליה מונח המת — \u0003מטפחות.\u0004 ואם היה הדבר \u0003בראשי חדשים בחנוכה ובפורים,\u0004 אף שימים אלה הם ימי שמחה, מכל מקום אינם מן התורה ו\u0003מענות ומטפחות בזה ובזה, אבל לא מקוננות\u0004 (שאחת מהן אומרת דברי קינה והאחרות עונות אחריה).","\u0003ואמר רבה בר הונא:\u0004 כל זה נאמר באדם סתם, אבל \u0003אין מועד בפני תלמיד חכם\u0004 שאם מת בחג — מקוננים עליו כרגיל ו\u0003כל שכן\u0004 ב\u0003חנוכה ו\u0004ב\u0003פורים.\u0004 הרי משמע שאפילו תלמוד תורה של יחיד חשוב ביותר!","ודוחים: אין כאן קושיה, כי אתה מענין \u0003כבוד\u0004 ה\u0003תורה קאמרת\u0004 \u0005[אמרת]\u0006 ודבר זה הוא ענין אחר, ואכן, \u0003כבוד\u0004 ה\u0003תורה\u0004 של \u0003יחיד חמור,\u0004 ואילו \u0003תלמוד תורה\u0004 של \u0003יחיד — קל.\u0004","\u0003אמר רבא: פשיטא\u0004 \u0005[פשוט]\u0006 \u0003לי,\u0004 כלומר, יש כמה דברים שברורים בעיני, למשל: אם יש לפני אדם \u0003עבודה\u0004 במקדש \u0003ומקרא מגילה — מקרא מגילה עדיף, מ\u0004מה שדרש \u0003ר' יוסי בר חנינא,\u0004 וזאת למדתי מהמילים \"משפחה ומשפחה\". היו לפניו \u0003תלמוד תורה ומקרא מגילה —\u0004 אף אז \u0003מקרא מגילה עדיף,\u0004 ודבר זה אני למד \u0003מ\u0004מה ש\u0003סמכו\u0004 האנשים \u0003של בית רבי\u0004 לעשות כן.","נזדמן לו לאדם \u0003תלמוד תורה ו\u0004בתוך זמן לימודו נזדמן לו \u0003מת מצוה\u0004 שאין לו קוברים — העיסוק בקבורת \u0003מת מצוה עדיף, מדתניא\u0004 \u0005[מ\u0006מה \u0005ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003מבטלין תלמוד תורה להוצאת מת\u0004 לקבורה, \u0003ולהכנסת כלה.\u0004 נזדמנו לו \u0003עבודה\u0004 במקדש \u0003ומת מצוה — מת מצוה עדיף, מ\u0004מה שנאמר בדרשה על המלה \u0003\"ולאחתו\".\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר בנזיר \"כל ימי הזירו לה' על נפש מת לא יבוא. לאביו ולאמו לאחיו ולאחותו לא יטמא להם במותם\" (במדבר ו, ו-ז), וכיון שכל הפרטים שבפסוק השני לכאורה מיותרים, דורשים כל אחד מהם, כהוראה שאיסור זה יש להתירו לגבי מת מצוה, אפילו היה כהן גדול ונזיר כאחד. ושואלים: \u0003\"ולאחותו\" מה תלמוד לומר\u0004 במלה זו? ומשיבים שבאה ללמד לא לענין נזיר בלבד אלא אף לביטול שאר מצות \u0003הרי שהיה הולך לשחוט את פסחו\u0004 או \u0003למול את בנו, ושמע שמת לו מת, יכול יטמא —\u0004","\u0003אמרת: לא יטמא,\u0004 אלא ימשיך בדרכו. שכן הוא הולך למצוה חשובה שיש איסור כרת על ביטולה, \u0003יכול כשם שאינו מיטמא לאחותו, כך אינו מיטמא\u0004 אף \u0003למת מצוה — תלמוד לומר: \"ולאחתו\",\u0004 ללמדנו בהדגשה זו: \u0003לאחותו הוא\u0004 ש\u0003אינו מיטמא, אבל מיטמא\u0004 הוא \u0003למת מצוה.\u0004","עד כאן הדברים שהיו ברורים לרבא, ועל סמך דברים אלה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: מקרא מגילה ומת מצוה הי מינייהו\u0004 \u0005[איזה מהם]\u0006 \u0003עדיף?\u0004 וצדדי השאלה: האם נאמר ש\u0003מקרא מגילה עדיף משום פרסומי ניסא\u0004 \u0005[פרסום הנס],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003מת מצוה עדיף משום כבוד הבריות\u0004 הכרוך בדבר? \u0003בתר דבעיא הדר פשטה\u0004 \u0005[אחר ששאל\u0006 את השאלה \u0005חזר\u0006 הוא עצמו \u0005ופתרה]:\u0006 \u0003מת מצוה עדיף,\u0004 שכן \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003גדול כבוד הבריות שדוחה\u0004 אפילו \u0003את\u0004 מצות \u0003לא תעשה שבתורה,\u0004 ולכן ודאי שהוא דוחה גם את מצות מגילה שהיא מדברי סופרים על פרסום הנס שבה.","\u0003גופא\u0004 (לגופו) של מה שנאמר קודם, \u0003אמר ר' יהושע בן לוי: כרך וכל הסמוך לו וכל הנראה עמו נדון\u0004 לענין זמן קריאת המגילה \u0003ככרך\u0004 עצמו. \u0003תנא\u0004 \u0005[שנה\u0006 החכם בתוספתא\u0005]:\u0006 הדין כן אף ב\u0003סמוך אף על פי שאינו נראה,\u0004 וכן ב\u0003נראה אף על פי שאינו סמוך.\u0004","ודנים בדבר: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003נראה אף על פי שאינו סמוך — משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 אפשרות \u0003כגון דיתבה\u0004 \u0005[שיושבת\u0006 העיר\u0005]\u0006 \u0003בראש ההר\u0004 ולכן היא נראית ממקומות רחוקים אף שאינה סמוכה להם, \u0003אלא סמוך אף על פי שאינו נראה היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותה]?\u0006 שלכאורה אם הוא סמוך — ודאי הוא נראה. \u0003אמר ר' ירמיה:\u0004 כגון \u0003שיושבת\u0004 העיר \u0003בנחל,\u0004 בעמק ואז יתכן שתהא קרובה ואינה נראית.","\u0003ואמר ר' יהושע בן לוי: כרך שישב,\u0004 כלומר, במקום זה היה תחילה ישוב כלשהו \u0003ולבסוף הוקף\u0004 חומה — עדיין הוא \u0003נדון ככפר\u0004 ואינו ככרך לענין \"בתי ערי חומה\". \u0003מאי טעמא\u0004 \u0005[ומה טעמו]\u0006 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואיש כי ימכר בית מושב עיר חומה\"\u0004 (ויקרא כה, כט), ונדקדק מלשון הכתוב שמדובר במקום \u0003שהוקף ולבסוף ישב,\u0004 וכלשון הכתוב שהיה בית מושב בתוך עיר חומה, \u0003ולא שישב ולבסוף הוקף.\u0004","\u0003ואמר ר' יהושע בן לוי: כרך שאין בו עשרה בטלנין\u0004 (אנשים הפנויים ממלאכה ועוסקים בצרכי הציבור) — הרי זה \u0003נדון ככפר.\u0004 ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 בכך\u0005]\u0006 הלא \u0003תנינא\u0004 \u0005[שנינו\u0006 דבר זה בברייתא\u0005]:\u0006 \u0003איזו היא עיר גדולה — כל שיש בה עשרה בטלנין, פחות מכאן — הרי זה כפר?\u0004 ומשיבים: בכל זאת יש חידוש, כי \u0003כרך\u0004 דווקא \u0003איצטריך ליה\u0004 \u0005[נצרך לו,\u0006 ללמדנו\u0005]\u0006 ש\u0003אף על גבי דמיקלעי מעלמא\u0004 \u0005[אף על פי שמזדמנים\u0006 לו אנשים \u0005מן העולם,\u0006 מן החוץ\u0005]\u0006 ונמצאים בו עשרה בטלנים באותה שעה, מכל מקום, כיוון שאין עשרה אלה מבני המקום עדיין הוא נדון ככפר.","ועוד באותו ענין, \u0003ואמר ר' יהושע בן לוי: כרך שחרב ולבסוף\u0004 חזר ו\u0003ישב — נדון ככרך.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 משמעו\u0005]\u0006 של \u0003\"חרב\"? אילימא\u0004 \u0005[אם תאמר]\u0006 \"חרב\" — ש\u0003חרבו חומותיו,\u0004 וכי אם \u0003ישב — אין\u0004 \u0005[כן]\u0006 דינו ככרך, ואם \u0003לא ישב — לא? והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' אליעזר בר יוסי אומר\u0004 על הכתוב \u0003\"אשר לוא חמה\"\u0004 (ויקרא כה, ל), שכתוב \"לא\" אף שהכוונה היא ל\"לו\", שבא הדבר ללמד שכן דינו \u0003אף על פי שאין לו עכשיו והיה לו קודם לכן,\u0004 נמצא שאף שחרבו החומות, מעמדו של המקום ככרך לא בטל.","\u0003אלא מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חרב\" — שחרב מעשרה בטלנין,\u0004 ואז נחשב המקום רק ככפר גדול, ואם שוב יש בו ציבור כזה — הריהו חוזר ונחשב ככרך,","\u0003ו\u0004עוד \u0003אמר ר' יהושע בן לוי:\u0004"],["\u0003לוד ואונו וגיא החרשים\u0004 ערים \u0003מוקפות חומה מימות יהושע בן נון הוו\u0004 \u0005[היו].\u0006","ושואלים: \u0003והני\u0004 \u0005[ו\u0006כי את הערים \u0005הללו]\u0006 \u0003יהושע בננהי\u0004 \u0005[בנאן]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אלפעל בננהי\u0004 \u0005[\u0006הוא ש\u0005בנאן]\u0006 מאוחר יותר, \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"ובני אלפעל עבר ומשעם ושמר הוא בנה את אונו ואת לד ובנתיה\"\u0004 (דברי הימים א' ח, יב)! על שאלה זו עצמה, תמהים: אם כן \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 שאתה מוכיח שבנו ערים אלה אחר כך, תוכל לומר כי \u0003אסא\u0004 מלך יהודה \u0003בננהי\u0004 \u0005[בנאן],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ויבן אסא את ערי הבצורות אשר ליהודה\"\u0004 (דברי הימים ב' יד, ה), ואם כן, ברור שנבנו יותר מפעם אחת.","\u0003אמר ר' אלעזר: הני\u0004 \u0005[\u0006ערים \u0005אלה]\u0006 \u0003מוקפות חומה מימות יהושע בן נון הוו\u0004 \u0005[היו],\u0006 \u0003חרוב\u0004 \u0005[נחרבו]\u0006 \u0003בימי פילגש בגבעה\u0004 שהרי הן מנחלת בנימין, ובאותה מלחמה נהרסו כל ערי בנימין, \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003אלפעל בננהי\u0004 \u0005[\u0006ו\u0005בנה אותן]\u0006 \u0003הדור אינפול\u0004 \u0005[חזרו\u0006 ו\u0005נפלו]\u0006 במלחמות יהודה וישראל, ואז \u0003אתא\u0004 \u0005[בא]\u0006 \u0003אסא שפצינהו\u0004 \u0005[\u0006ו\u0005שיפץ אותן]\u0006 שוב.","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן\u0006 הדבר\u0005]\u0006 בלשון הכתוב, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 באסא: \u0003\"ויאמר ליהודה נבנה את הערים האלה\"\u0004 (דברי הימים ב' יד, ו) \u0003מכלל\u0004 הדברים אתה למד ש\u0003ערים הוו מעיקרא\u0004 \u0005[היו\u0006 אלה \u0005מתחילה]\u0006 ולא שבנה ערים חדשות. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","\u0003ואמר ר' יהושע בן לוי\u0004 עוד בענין פורים: \u0003נשים חייבות במקרא מגילה, שאף הן היו\u0004 שותפות חשובות \u0003באותו הנס. ואמר ר' יהושע בן לוי: פורים שחל להיות בשבת, שואלין ודורשין\u0004 בשבת \u0003בענינו של יום.\u0004","על ההלכה האחרונה שואלים: \u0003מאי אריא\u0004 \u0005[מה שייך],\u0006 מדוע נאמר דבר זה דווקא ב\u0003פורים? אפילו יום טוב נמי\u0004 \u0005[גם כן]\u0006 שואלים ודורשים בענין החג! \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003משה תיקן לישראל שיהו שואלין ודורשין בענינו של יום,\u0004 ועוסקים ב\u0003הלכות פסח בפסח,\u0004 ב\u0003הלכות עצרת\u0004 (שבועות) \u0003בעצרת ו\u0004ב\u0003הלכות חג\u0004 הסוכות \u0003בחג!\u0004","ומשיבים: אף על פי כן \u0003פורים איצטריכא ליה\u0004 \u0005[הוצרכה לו\u0006 לומר במיוחד\u0005],\u0006 כי \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003נגזור\u0004 בפורים שחל בשבת שלא לשאול ולדרוש בענין פורים \u0003משום\u0004 גזירה של \u0003רבה\u0004 שהסביר שאין קוראים מגילה בפורים שחל בשבת שמא יבואו לטלטלה ברשות הרבים, ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין גוזרים דרשה משום קריאה.","\u0003ו\u0004עוד \u0003אמר ר' יהושע בן לוי: חייב אדם לקרות את המגילה בלילה ולשנותה ביום.\u0004 ורמז לדבר — \u0003שנאמר: \"אלהי אקרא יומם ולא תענה ולילה ולא דמיה לי\"\u0004 (תהלים כב, ג), הרי קריאה ביום ובלילה.","\u0003סבור מינה\u0004 \u0005[סבורים\u0006 היו השומעים ללמוד \u0005מכאן]\u0006 שהכוונה היא \u0003למקרייה בליליא\u0004 \u0005[לקרוא אותה,\u0006 את המגילה עצמה \u0005בלילה]\u0006 \u0003ולמיתנא מתניתין דידה ביממא\u0004 \u0005[ולשנות את המשניות שלה ביום],\u0006 שכך הבינו \"לשנותה ביום\". \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' ירמיה: לדידי מיפרשא לי מיניה\u0004 \u0005[לי\u0006 עצמי \u0005נתפרש לי\u0006 הדבר \u0005ממנו]\u0006 מדברי \u0003ר' חייא בר אבא\u0004 שאין הכוונה \"לשנותה\" במובן זה, אלא \u0003כגון\u0004 מטבע הלשון \u0003דאמרי אינשי\u0004 \u0005[שאומרים אנשים]:\u0006 \u0003אעבור פרשתא דא\u0004 \u0005[פרשה זו]\u0006 \u0003ואתנייה\u0004 \u0005[ואשנה אותה],\u0006 כלומר, אלמדנה פעם שניה, שההלכה היא שקוראים את המגילה בלילה וחוזרים וקוראים אותה ביום.","\u0003איתמר נמי\u0004 \u0005[נאמר גם כן\u0006 אותו דבר\u0005]\u0006 בשם אמורא אחר, \u0003אמר ר' חלבו אמר עולא ביראה\u0004 \u0005[\u0006מ\u0005בירי]:\u0006 \u0003חייב אדם לקרות את המגילה בלילה ולשנותה ביום, שנאמר\u0004 רמז לדבר בפרק הנדרש (בפסיקתא דרב כהנא) בענין מרדכי אסתר, המן ואחשורוש: \u0003\"למען יזמרך כבוד ולא ידם ה' אלהי לעולם אודך\"\u0004 (תהלים ל, יג).","עתה חוזרים לפירוש המשנה. נאמר במשנה: \u0003אלא שהכפרים מקדימין ליום הכניסה\u0004 ולכן אינם קוראים בתאריך קבוע, אלא בתאריכים שונים. \u0003אמר ר' חנינא: חכמים\u0004 הם ש\u0003הקילו על הכפרים להיות מקדימין ליום הכניסה כדי שיספקו מים ומזון לאחיהם שבכרכין,\u0004 שאם הכל יעסקו בקריאת המגילה לא יהיה לבני הכרכים מה לאכול."],["\u0003למימרא דתקנתא\u0004 \u0005[האם לומר ש\u0006דבר זה \u0005תקנה]\u0006 של ה\u0003כרכין הוי\u0004 \u0005[הוא],\u0006 שלשם תועלתם של הכרכים נעשה? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003חל\u0004 פורים \u0003להיות בשני\u0004 בשבוע — \u0003כפרים ועיירות גדולות קורין בו ביום. ואם איתא\u0004 \u0005[יש\u0006 מקום לומר\u0005]\u0006 שנעשתה התקנה לתועלת הערים, אם כן \u0003ליקדמו\u0004 \u0005[שיקדימו]\u0006 את קריאת המגילה בכפר \u0003ליום הכניסה\u0004 הקודם ויוכלו לספק לערים מזון ביום שני! ודוחים: אין זה אפשרי. כי אם היו עושים כן \u0003הוו להו\u0004 \u0005[היה להם]\u0006 פורים ביום \u0003עשרה\u0004 באדר, \u0003ועשרה\u0004 באדר \u0003לא תקינו רבנן\u0004 \u0005[תיקנו חכמים]\u0006 לקרות בו.","ומביאים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה מקטע אחר במשנתנו: \u0003חל\u0004 ארבע עשר \u0003להיות בחמישי\u0004 — \u0003כפרים ועיירות גדולות קורין בו ביום, ואם איתא\u0004 \u0005[יש]\u0006 מקום לדברי ר' חנינא, אם כן \u0003ליקדמו\u0004 \u0005[שיקדימו]\u0006 לקרוא ביום שני \u0003ליום הכניסה\u0004 שהרי יום \u0003אחד עשר הוא!\u0004 ודוחים: \u0003מיום הכניסה\u0004 אחד \u0003ליום הכניסה\u0004 אחר \u0003לא דחינן\u0004 \u0005[דוחים אנו],\u0006 כי הדבר עשוי להביא לידי טעות.","ומביאים ראיה אחרת; \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ש\u0003אמר ר' יהודה: אימתי\u0004 נאמרו דינים אלה — \u0003במקום שנכנסים\u0004 (מתכנסים) בו כרגיל בני הכפרים \u0003ב\u0004ימים \u0003שני וחמישי, אבל מקום שאין נכנסים\u0004 בני הכפרים \u0003בשני ובחמישי\u0004 — \u0003אין קורין אותה אלא בזמנה. ואי סלקא דעתך תקנתא\u0004 \u0005[ואם יעלה על דעתך\u0006 לומר\u0005]\u0006 שכל זאת תקנת ה\u0003כרכין היא\u0004 — \u0003משום\u0004 ש\u0003אין נכנסים\u0004 בני הכפרים \u0003בשני ובחמישי מפסדי להו\u0004 \u0005[מפסידים הם]\u0006 \u0003ל\u0004בני ה\u0003כרכין\u0004 שתקנה זו נעשתה לטובתם?","אלא \u0003לא תימא\u0004 \u0005[אל תאמר]\u0006 שהטעם הוא \u0003כדי שיספקו מים ומזון\u0004 לתועלת הכרך, \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003מפני שמספקים מים ומזון לאחיהם שבכרכין\u0004 ונעשה הדבר לתועלת בני הכפר שלא יפסידו פרנסתם, שהרי כרגיל הם מספקים מים ומזון לבני הכרכים, ואם לא יקדימו להם את יום הפורים יימצאו מפסידים. ואם כן, במקום שאינם נכנסים, אין להם כל תועלת בהקדמה.","שנינו במשנה: \u0003כיצד\u0004 משתנים ימי הקריאה? \u0003חל להיות\u0004 ארבע עשר \u0003בשני בשבת\u0004 — \u0003כפרים ועיירות גדולות קורין בו ביום וכו'.\u0004 ושואלים: \u0003מאי שנא רישא דנקט סידורא דירחא\u0004 \u0005[\u0006ב\u0005מה שונה ראשה\u0006 של המשנה \u0005שאחז\u0006 בו את \u0005סדר\u0006 ימי \u0005החודש],\u0006 שהרי הוא אומר: באחד עשר, בשנים עשר וכו' \u0003ומאי שנא סיפא דנקט סידורי דיומי\u0004 \u0005[ו\u0006ב\u0005מה שונה בסוף ש\u0006הוא \u0005אוחז\u0006 בו את \u0005סדר הימים],\u0006 שהדברים מפורשים לפי סדר ימי השבוע; שני, שלישי, רביעי?","ומשיבים: \u0003איידי דמיתהפכי ליה נקט סידורא דיומי\u0004 \u0005[מתוך ש\u0006הם \u0005מתהפכים לו\u0006 הוא \u0005אוחז\u0006 את \u0005סדר הימים].\u0006 שאם היה מסדר לפי ימי החודש, היה צריך לפרט את הימים האפשריים לאחור; תחילה פורים שחל ביום ראשון, ואחר כך ביום שישי ואחר כך ביום רביעי ושלישי, ועל כן פירט בדרך שלא תביא לידי בלבול.","נאמר במשנה: \u0003חל\u0004 ארבע עשר \u0003להיות בערב שבת\u0004 — כפרים מקדימים ליום הכניסה, ועיירות גדולות ומוקפות חומה קוראים בו ביום, שאף מוקפות החומה מקדימות אז יום אחד. ושואלים: \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי היא]?\u0006 אפשר לומר כי היא \u0003אי\u0004 \u0005[או]\u0006 כשיטת \u0003רבי, אי\u0004 \u0005[או]\u0006 כשיטת \u0003ר' יוסי\u0004 ולא כשיטתם של חכמים אחרים.","ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 שיטת \u0003רבי? דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 שאם \u0003חל\u0004 ארבע עשר \u0003להיות בערב שבת — כפרים ועיירות גדולות,\u0004 שניהם \u0003מקדימין ליום הכניסה, ו\u0004אילו \u0003מוקפין חומה קורין בו ביום.\u0004 ואילו \u0003רבי אומר, אומר אני: לא ידחו עיירות ממקומן\u0004 שיהיו הן יכולות לקרוא בו ביום, בזמן הראוי להם, \u0003אלא אלו ואלו\u0004 גם עיירות וגם כרכים \u0003קורין בו ביום.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של ה\u0003תנא קמא\u0004 \u0005[הראשון]?\u0006 ומסבירים, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במגילה: \u0003\"בכל שנה ושנה\"\u0004 (אסתר ט, כז), לומר שצריך לנהוג בכל השנים באופן זהה. והוא לומד כך: \u0003מה\u0004 ב\u0003כל שנה ושנה עיירות קודמות למוקפין\u0004 יום אחד, \u0003אף כאן עיירות קודמות למוקפין.\u0004 וכיון שאין המוקפים יכולים לקרוא בשבת וצריכים להקדים ליום שישי — מקדימים גם את העיירות יום אחד לפני כן.","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שהפסוק \u0003\"בכל שנה ושנה\"\u0004 בא ללמד כך: \u0003מה כל שנה ושנה אין נדחין עיירות ממקומן,\u0004 אלא קורין בארבעה עשר — \u0003אף כאן לא ידחו עיירות ממקומן!\u0004 ומשיבים: \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 \u0003דלא\u0004 (שאי) \u0003אפשר\u0004 לקיים את כל הדברים כאחת.","ולהיפך, \u0003ורבי, מאי טעמיה\u0004 \u0005[מה טעמו] —\u0006 כפי שנאמר: \u0003\"בכל שנה ושנה\", מה כל שנה ושנה אין עיירות נדחין ממקומן — אף כאן לא ידחו עיירות ממקומן.\u0004","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 להיפך: \u0003\"בכל שנה ושנה\" — מה כל שנה ושנה עיירות קודמות למוקפין — אף כאן נמי\u0004 \u0005[גם כן]\u0006 \u0003עיירות קודמות למוקפין!\u0004 ומשיבים: \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 \u0003דלא\u0004 (שאי) \u0003אפשר\u0004 לקיים את שני הדברים כאחד.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 שיטת \u0003ר' יוסי? דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חל להיות\u0004 ארבעה עשר \u0003בערב שבת — מוקפין וכפרים מקדימין ליום הכניסה,\u0004 שהמוקפים מקדימים ביומיים \u0003ועיירות גדולות קורין בו ביום. ר' יוסי אומר: אין מוקפין קודמין לעיירות\u0004 לעולם, \u0003אלא אלו ואלו\u0004 מוקפים ועיירות \u0003קורין בו ביום.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של ה\u0003תנא קמא? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בכל שנה ושנה\" — מה כל שנה ושנה עיירות\u0004 קוראות \u0003בארבעה עשר,\u0004 ואינן זזות ממקומן, \u0003וזמנו של זה לא זמנו של זה,\u0004 שלעולם אין מוקפים ועיירות קוראים באותו היום, \u0003אף כאן — עיירות\u0004 תשארנה \u0003בארבעה עשר, וזמנו של זה לא זמנו של זה\u0004 ולכן צריך להקדים את המוקפים.","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 להיפך: \u0003\"בכל שנה ושנה\" — מה כל שנה ושנה אין מוקפין קודמין לעיירות, אף כאן — אין מוקפין קודמין לעיירות!\u0004 ומשיבים: \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 \u0003דלא\u0004 (שאי) \u0003אפשר\u0004 לעשות שיהיו הדברים כאחד.","ולהיפך, \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יוסי? —\u0004 שיהיו \u0003\"בכל שנה ושנה\", מה כל שנה ושנה אין מוקפין קודמין לעיירות, אף כאן — אין מוקפין קודמין לעיירות.\u0004","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 באופן אחר — \u0003\"בכל שנה ושנה\", מה כל שנה ושנה — זמנו של זה לא זמנו של זה, אף כאן\u0004 בשנה זו — \u0003זמנו של זה לא זמנו של זה!\u0004 ומשיבים: \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 \u0003דלא\u0004 (שאי) \u0003אפשר\u0004 ועל כן ברור ששיטת משנתנו יכולה להיות או כשיטת רבי או כשיטת רבי יוסי, ולא כאחת השיטות החולקים עליהם.","ושואלים: \u0003ו\u0004כי \u0003סבר רבי עיירות לא דחינן\u0004 \u0005[אין אנו דוחים אותם]\u0006 \u0003ליום הכניסה\u0004 כלל? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא אחרת\u0005]:\u0006 \u0003חל להיות\u0004 ארבע עשר \u0003בשבת — כפרים מקדימין ליום הכניסה, ועיירות גדולות קורין בערב שבת, ומוקפות חומה\u0004 קוראים \u0003למחר. רבי אומר, אומר אני: הואיל ונדחו עיירות ממקומן,\u0004 שאינן קוראות בארבעה עשר — \u0003ידחו\u0004 אף הן \u0003ליום הכניסה.\u0004 ואם כן גם רבי מסכים שעיירות נידחות, ומדוע בברייתא הקודמת אין הוא מסכים לכך?","ותוהים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בברייתא השניה \u0003זמנם\u0004 הלא \u0003שבת היא,\u0004 ובשבת הלא אי אפשר לקרות, \u0003והואיל\u0004 וכבר \u0003נדחו,\u0004 שאינם יכולים לקרוא בזמנם — \u0003ידחו\u0004 (יוקדמו) יום אחד, שיהיו כל ישראל קוראים ביום אחד. \u0003ו\u0004אלו \u0003הכא\u0004 \u0005[כאן]\u0006 הלא \u0003זמנם ערב שבת\u0004 ומדוע יצטרכו לדחות?","ושואלים: \u0003כמאן אזלא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת]\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר ר' חלבו אמר רב הונא: פורים שחל להיות בשבת\u0004 — \u0003הכל נדחין ליום הכניסה.\u0004 תחילה תוהים על הלשון: \u0003הכל נדחין סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 \u0003מוקפין דעבדי\u0004 \u0005[שעושים]\u0006 \u0003למחר,\u0004 ביום ראשון, לכל הדעות! \u0003אלא\u0004 כך יש לומר: \u0003כל הנדחה — ידחה ליום הכניסה. כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי] —\u0006 \u0003כ\u0004שיטת \u0003רבי.\u0004","מתוך כל הדברים שלמדנו במשנה ובברייתות, היה ברור \u0003דכולי עלמא מיהא\u0004 \u0005[לדעת הכל על כל פנים]\u0006 \u0003מגילה בשבת לא קרינן\u0004 \u0005[קוראים אנו],\u0006 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003אמר רבה: הכל חייבין בקריאת מגילה ובתקיעת שופר\u0004 אולם \u0003אין הכל בקיאין במקרא מגילה,\u0004 ואם לא ישנו את זמן קריאת המגילה משבת, \u0003גזירה שמא יטלנה בידו וילך אצל בקי ללמוד\u0004 את קריאתה או לשמוע ממנו, ובתוך טרדתו ישכח \u0003ויעבירנה ארבע אמות ברשות הרבים\u0004 ומשום כך קבעו שלא יקראו מגילה בשבת.","ומעירים: \u0003והיינו טעמא\u0004 \u0005[וזהו הטעם]\u0006 שגזרו שלא יתקעו ב\u0003שופר\u0004 בראש השנה שחל להיות בשבת, שכיון שהכל חייבים בשמיעה ואין הכל בקיאים בתקיעה, יש לחשוש שמא יעבירנו ארבע אמות ברשות הרבים בדרכו להתלמד. \u0003והיינו טעמא\u0004 \u0005[וזהו הטעם]\u0006 שאין נוטלים \u0003לולב\u0004 בשבת.","\u0003רב יוסף אמר:\u0004 במגילה יש טעם אחר, \u0003מפני שעיניהן של עניים נשואות במקרא מגילה\u0004 שהעניים מצפים זמן רב ליום מקרא מגילה, מפני שמחלקים בו ביום מתנות לעניים, ואם יקראוה בשבת אי אפשר לתת להם כסף, ונמצאים העניים מתאכזבים. ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנינו\u0006 בברייתא \u0005גם כן כך],\u0006 שמתחשבים בצרכיהם של העניים; \u0003אף על פי שאמרו כפרים מקדימין ליום הכניסה — גובין בו ביום,\u0004 את הכסף המיועד למתנות לאביונים \u0003ומחלקין\u0004 אותו לעניים \u0003בו ביום.\u0004","ותוהים: \u0003אף על פי שאמרו?\u0004 מה קשור הדבר להקדמת זמן קריאת המגילה בכפרים? שהרי אין זה ניגוד, אלא \u0003אדרבה, משום\u0004 ש\u0003אמרו הוא\u0004 זה שהקדימו את מתן המתנות! \u0003אלא\u0004 יש לתקן קצת את הלשון: \u0003הואיל ואמרו שכפרים מקדימין ליום הכניסה\u0004 — \u0003גובין בו ביום,\u0004 ביום הכניסה שקוראים בו, \u0003ומחלקין בו ביום,\u0004 וזאת \u0003מפני שעיניהם של עניים נשואות במקרא מגילה,\u0004 ודואגים להם שלא יבואו לידי אכזבה. \u0003אבל\u0004"],["\u0003שמחה\u0004 של פורים וכל מה ששייך לה, \u0003אינה נוהגת אלא בזמנה —\u0004 בארבעה עשר.","\u0003אמר רב: מגילה\u0004 אם קוראים אותה \u0003בזמנה\u0004 בארבעה עשר — \u0003קורין אותה אפילו ביחיד,\u0004 ואם קוראים אותה \u0003שלא בזמנה,\u0004 כגון בכפרים המקדימים ליום הכניסה — קוראים אותה רק \u0003בעשרה,\u0004 מפני שהתקנה לקרוא את המגילה קודם זמנה נתקנה רק עבור ציבור שלם. ואילו \u0003רב אסי אמר: בין בזמנה בין שלא בזמנה\u0004 חובה לקרותה \u0003בעשרה.\u0004 ומספרים: \u0003הוה עובדא וחש ליה\u0004 \u0005[היה מעשה וחשש לו]\u0006 \u0003רב להא\u0004 \u0005[לזה]\u0006 שאמר \u0003רב אסי\u0004 והקפיד לאסוף עשרה למקרא מגילה, אף שקראה בזמנה.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רב הכי\u0004 \u0005[כך]\u0006 שמגילה שלא בזמנה נקראת בעשרה דווקא? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003רב שמואל בר שילת משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: פורים שחל להיות בשבת — ערב שבת זמנם,\u0004 ותוהים על הלשון: \u0003ערב שבת זמנם?! והא\u0004 \u0005[והרי]\u0006 \u0003שבת זמנם הוא! אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כלומר, כך צריך להבין: \u0003שלא בזמנם\u0004 דינו \u0003כזמנם, מה\u0004 ב\u0003זמנם\u0004 קוראים \u0003אפילו ביחיד, אף שלא בזמנם — אפילו ביחיד?\u0004","ודוחים: דברי רב אלה \u0003לא לענין מקרא מגילה בעשרה\u0004 נאמרו, \u0003אלא מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ערב שבת זמנם\" — לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003רבי,\u0004 ש\u0003אמר: הואיל ונדחו עיירות ממקומן — ידחו ליום הכניסה,\u0004 לכך \u0003הא קמשמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 ש\u0003ערב שבת זמנם הוא\u0004 כמו שכתוב במשנתנו, ושלא כשיטת רבי.","\u0003אי זו היא עיר גדולה\u0004 שזמנה הוא בארבעה עשר ואינה נדחית כרגיל — \u0003כל שיש בה עשרה בטלנין?\u0004 היו בה \u0003פחות מכאן\u0004 (מכן, ממספר זה) — \u0003הרי זה\u0004 נחשב כ\u0003כפר,\u0004 גם אם יש בה תושבים רבים.","\u0003באלו\u0004 בזמני קריאת המגילה \u0003אמרו\u0004 ש\u0003מקדימין\u0004 אותם לפני ארבעה עשר \u0003ולא מאחרין\u0004 לאחר חמישה עשר, \u0003אבל זמן עצי כהנים\u0004 שקבעו חכמים ימי שמחה לבני משפחות קבועות שהיו נוהגות מדורות להביא קרבן עצים בהתנדבות, \u0003ו\u0004כן \u0003תשעה באב,\u0004 וכן קרבן ה\u0003חגיגה\u0004 שמקריבים ביום טוב, \u0003ו\u0004כן \u0003הקהל\u0004 שמקהילים את כל ישראל במוצאי חג הסוכות לשמוע את קריאת התורה מפי המלך — כל אלה, אם חלו בשבת — \u0003מאחרין\u0004 אותם לאחריה \u0003ולא מקדימין.\u0004","ועוד אומרים לגבי המגילה: \u0003אף על פי שאמרו\u0004 בזמני קריאת המגילה \u0003מקדימין ולא מאחרין\u0004 — בכל זאת אותם ימים נוספים \u0003מותרין בהספד ובתענית,\u0004 שאינם כימי הפורים ממש, אבל נותנים בהם \u0003מתנות לאביונים. אמר ר' יהודה: אימתי\u0004 אמרו לנו שמקדימים את ימי הפורים? ב\u0003מקום שנכנסין\u0004 (מתכנסים) בו \u0003בשני ובחמישי, אבל מקום שאין נכנסין לא בשני ולא בחמישי — אין קורין אותה\u0004 את המגילה \u0003אלא בזמנה.\u0004","במשנה הוזכרו עשרה בטלנים, ומסבירים בתוספתא, \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003עשרה בטלנין\u0004 שאמרו, אלו הם עשרה בטלנים \u0003שבבית הכנסת.\u0004 כלומר, עשרה אנשים שבטלים ממלאכתם ויושבים בבית הכנסת ועוסקים בצרכי ציבור ובכל ענייני תורה ומצוות, ופרנסתם מוטלת על הציבור, ובגללם נקבע שעיר זו באמת מקום חשוב הוא.","שנינו במשנה שדווקא \u0003באלו,\u0004 בימי מקרא מגילה, \u0003אמרו מקדימין ולא מאחרין.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אמר ר' אבא אמר שמואל: אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"\u0004קיימו וקבלו היהודים עליהם ועל זרעם ועל כל הנלוים עליהם \u0003ולא יעבור\"\u0004 (אסתר ט, כז), ולכן מקפידים שלא יעבור זמן הפורים לאחר זמנו.","כיוון שהזכרנו דברי הלכה של רבי אבא בשם שמואל אומרים עוד דבר בשמו; \u0003ואמר ר' אבא אמר שמואל: מנין שאין מונין ימים לשנים,\u0004 כלומר, שבכל חשבון של שנה מונים רק שנים עשר חודש, ואין מקפידים להשלים את מנין ימי שנת החמה (365 יום) — \u0003שנאמר: \"לחדשי השנה\"\u0004 (שמות יב, ב) ללמדנו — \u0003חדשים אתה מונה לשנים, ואי\u0004 (ואין) \u0003אתה מונה ימים לשנים.\u0004","ומוסיפים: \u0003ורבנן\u0004 \u0005[וחכמי]\u0006 \u0003קיסרי משום\u0004 (משמו של) \u0003ר' אבא אמרו: מנין שאין מחשבין שעות לחדשים,\u0004 אלא חושבים רק מיום ליום, גם אם זה לא משעה לשעה, \u0003שנאמר: \"עד חדש ימים\"\u0004 (במדבר יא, כ), ללמדנו: \u0003ימים אתה מחשב לחדשים, ואי אתה מחשב שעות לחדשים.\u0004","שנינו במשנה: \u0003אבל זמן עצי כהנים ותשעה באב וחגיגה והקהל מאחרין ולא מקדימין.\u0004 ומסבירים מה טעם הלכה זו לגבי כל אחד מאלה: \u0003תשעה באב\u0004 אין מקדימים — משום ש\u0003אקדומי\u0004 \u0005[להקדים]\u0006 \u0003פורענות לא מקדמי\u0004 \u0005[מקדימים]\u0006 ודוחים ככל האפשר כל ענין של צרה. \u0003חגיגה והקהל\u0004 אין מקדימים — \u0003משום דאכתי\u0004 \u0005[שעדיין]\u0006 \u0003לא מטא\u0004 \u0005[הגיע]\u0006 \u0003זמן חיובייהו\u0004 \u0005[חיובם],\u0006 ומכיוון שחיובם מן התורה הוא ביום מסויים דווקא — אין להקדימו לפני אותו יום.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם בתוספתא\u0005]:\u0006 \u0003חגיגה וכל זמן חגיגה מאחרין.\u0004 ומנסים לברר מה משמעות הענין: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מה שנאמר שמאחרים \u0003חגיגה,\u0004 הכוונה היא \u0003דאי מיקלע בשבתא\u0004 \u0005[שאם מזדמן\u0006 יום טוב \u0005בשבת]\u0006 ואי אפשר להקריב קרבן חגיגה בשבת \u0003מאחרינן לה\u0004 \u0005[מאחרים אותה]\u0006 \u0003לבתר שבתא\u0004 \u0005[לאחר שבת]\u0006 ומקריבים בחול המועד. \u0003אלא זמן חגיגה מאי היא\u0004 \u0005[מה\u0006 פירושו של \u0005זה]?\u0006","\u0003אמר רב אושעיא, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003חגיגה בשבת, ועולת ראייה, אפילו ביום טוב\u0004 שהוא \u0003זמן חגיגה,\u0004 שהרי מקריבים קרבן חגיגה ביום טוב \u0003— מכל מקום מאחרין\u0004 את קרבן החגיגה לאחר השבת ואת קרבן העולה לאחרי החג.","ומעירים: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 — כדעת \u0003בית שמאי היא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003בית שמאי אומרים: מביאין שלמים ביום טוב\u0004 להקריב במקדש, שכיון שהשלמים נאכלים ברובם לכהנים ולבעלים אפשר לראות את שחיטתם כשחיטה לצורך אוכל שמותרת ביום טוב, \u0003ואין סומכין עליהן\u0004 שיש בסמיכה משום עבודה בבעלי חיים ביום טוב,","\u0003אבל לא\u0004 מביאים \u0003עולות\u0004 ביום טוב כלל, שכיון שאינן לצורך אדם — אין להביאן. \u0003ובית הלל אומרים: מביאין\u0004 גם \u0003שלמים ו\u0004גם \u0003עולות, וסומכין עליהן.\u0004","\u0003רבא אמר\u0004 הסבר אחר לאותה תוספתא, ולדעתו יש לראות את הדבר כביטוי אחד: קרבן \u0003חגיגה, כל זמן חגיגה,\u0004 כלומר, כל ימי החג — \u0003מאחרין, טפי\u0004 \u0005[יותר]\u0006 מזה — \u0003לא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שלא חג,\u0004 שלא הביא קרבן חגיגה \u0003ביום טוב הראשון של חג — חוגג והולך את כל הרגל כולו\u0004 בחול המועד, \u0003ו\u0004ב\u0003יום טוב האחרון של חג. עבר הרגל ולא חג — אינו חייב באחריותו,\u0004 כלומר, אינו צריך להשלים ולהביא את הקרבן — שכבר בטלה חובה זו.","\u0003רב אשי אמר\u0004 כך יש להבין את התוספתא: \u0003חגיגה\u0004 עצמה \u0003וכל זמן חגיגה מאחרין, ו\u0004ללמדנו כי \u0003אפילו עצרת\u0004 (חג השבועות) \u0003דחד יומא\u0004 \u0005[ש\u0006הוא רק \u0005יום אחד]\u0006 ואין בו חול המועד, אם חל בשבת — \u0003מאחרין,\u0004 שמותר להביא קרבנות עוד שישה ימים אחר כך, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מודים\u0004 בית שמאי ובית הלל \u0003שאם חל עצרת להיות בשבת — שיום טבוח,\u0004 יום הקרבת קרבנות החג, הוא \u0003אחר השבת\u0004 ביום ראשון. ואם כן זה פירוש הדבר, שלחגיגה, גם בחג השבועות, יש אחריה גם זמן חגיגה כל הימים שיש בכל ימי חג אחר.","\u0003אמר ר' אלעזר אמר ר' חנינא: רבי\u0004 עשה כמה דברים שאינם רגילים, \u0003נטע נטיעה בפורים\u0004 ולא חשש משום מלאכה וזילזול ביום זה."],["\u0003ורחץ\u0004 בפומבי \u0003בקרונה\u0004 (בשעת הילוך הקרונות, כלומר, ביום השוק) \u0003של צפורי בשבעה עשר בתמוז\u0004 להראות שמותר לרחוץ בו. \u0003ובקש לעקור תשעה באב — ו\u0004על תשעה באב \u0003לא הודו לו\u0004 חכמים.","\u0003אמר לפניו,\u0004 לפני ר' אלעזר, \u0003ר' אבא בר זבדא: רבי, לא כך היה מעשה,\u0004 שרצה לעקור את תשעה באב באופן כללי, \u0003אלא\u0004 מדובר היה במקרה מסויים, ש\u0003תשעה באב שחל להיות בשבת הוה\u0004 \u0005[היה]\u0006 באותה שנה, \u0003ו\u0004ממילא \u0003דחינוהו לאחר השבת, ואמר רבי: הואיל ונדחה\u0004 כבר מזמנו — \u0003ידחה\u0004 ויבטל לגמרי תשעה באב בשנה זו, \u0003ולא הודו\u0004 לו \u0003חכמים\u0004 בכך. \u0003קרי עליה\u0004 \u0005[קרא עליו]\u0006 רבי אלעזר את הכתוב: \u0003\"טובים השנים מן האחד\"\u0004 (קהלת ד, ט), כלומר, טוב שהיית כאן, שעל ידיך נמסר סיפור המעשה כראוי.","ושואלים: \u0003ורבי היכי\u0004 \u0005[כיצד]\u0006 \u0003נטע נטיעה בפורים? והתני\u0004 \u0005[והרי שנה]\u0006 \u0003רב יוסף:\u0004 נאמר \u0003\"\u0004עושים את יום ארבעה עשר לחודש אדר \u0003שמחה ומשתה ויום טוב\"\u0004 (אסתר ט, יט), ושלושת הלשונות הללו ללמד באו; \u0003\"שמחה\" — מלמד שאסורים\u0004 ימי הפורים \u0003בהספד, \"משתה\" — מלמד שאסור בתענית, \"ויום טוב\" — מלמד שאסור בעשיית מלאכה! אלא\u0004 המעשה כך היה: \u0003רבי, בר ארביסר הוה\u0004 \u0005[בן\u0006 חיוב \u0005ארבעה עשר היה],\u0006 שהיה גר במקום שנוהגים פורים ביום ארבעה עשר, \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003נטע — בחמיסר\u0004 \u0005[בחמישה עשר]\u0006 הוא ש\u0003נטע,\u0004 שהרי אינו פורים עבורו.","ותוהים: \u0003איני\u0004 \u0005[הכן הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבי בטבריא הוה\u0004 \u0005[בטבריה היה]\u0006 \u0003וטבריא\u0004 הלא \u0003מוקפת חומה מימות יהושע בן נון הואי\u0004 \u0005[היתה],\u0006 ואם כן, בן חמישה עשר היה! \u0003אלא\u0004 להיפך, \u0003רבי בר חמיסר הוה\u0004 \u0005[בן חמישה עשר היה],\u0006 \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003נטע — בארביסר הוה\u0004 \u0005[בארבעה עשר\u0006 \u0005היה\u0006 זה\u0005].\u0006","ושואלים: \u0003ומי פשיטא ליה\u0004 \u0005[והאם פשוט לו\u0006 לרבי\u0005]\u0006 \u0003דטבריא\u0004 \u0005[ש\u0006העיר \u0005טבריה]\u0006 \u0003מוקפת חומה מימות יהושע בן נון\u0004 היא? \u0003והא\u0004 \u0005[והרי]\u0006 החכם \u0003חזקיה קרי בטבריא בארביסר ובחמיסר\u0004 \u0005[היה קורא\u0006 את המגילה \u0005בטבריה\u0006 גם \u0005בארבעה עשר ו\u0006גם \u0005בחמישה עשר]\u0006 ומדוע? \u0003מספקא ליה\u0004 \u0005[מסופק\u0006 היה \u0005לו]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003מוקפת חומה מימות יהושע בן נון היא אי\u0004 \u0005[אם]\u0006 \u0003לא.\u0004 ומשיבים: זו אינה קושיה, אמנם \u0003לחזקיה מספקא ליה\u0004 \u0005[ספק היה לו],\u0006 \u0003לרבי פשיטא ליה\u0004 \u0005[פשוט היה לו].\u0006","ומקשים עוד: \u0003וכי פשיטא ליה\u0004 \u0005[וכאשר פשוט היה לו]\u0006 הדבר שבטבריה קוראים ביום זה, \u0003מי שרי\u0004 \u0005[האם מותר]\u0006 לעשות מלאכה ביום האחר? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003במגילת תענית: את יום ארבעה עשר ואת יום חמשה עשר\u0004 באדר \u0003יומי פוריא אינון, דלא למספד בהון\u0004 \u0005[ימי הפורים הם, שאין לספוד בהם],\u0006","\u0003ואמר רבא: לא נצרכא\u0004 \u0005[נצרכה]\u0006 הלכה זו שתיכתב במגילת תענית שהרי היא כתובה במקרא, \u0003אלא\u0004 כדי ללמדנו \u0003לאסור את של זה בזה ואת של זה בזה,\u0004 כלומר, גם מי שחל פורים אצלו בחמישה עשר אסור בהספד בארבעה עשר, ואם כן מדוע עשה רבי מלאכה ביום שאינו יום של קריאת המגילה במקומו? ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים \u0003בהספד ובתענית\u0004 שאסורים בשני הימים, \u0003אבל מלאכה\u0004 אסורה רק \u0003יום אחד ותו\u0004 \u0005[ויותר]\u0006 \u0003לא.\u0004","ושואלים: \u0003איני\u0004 \u0005[האם כך הוא]?\u0006 שאיסור מלאכה הוא יום אחד בלבד? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב חזייה לההוא גברא דהוה קא שדי כיתנא בפוריא, ולטייה\u0004 \u0005[ראה אדם אחד שהיה זורע פשתן בפורים, וקיללו]\u0006 \u0003ולא צמח כיתניה\u0004 \u0005[הפשתן שלו]!\u0006 ומשיבים: \u0003התם, בר יומא הוה\u0004 \u0005[שם, בן\u0006 אותו \u0005יום היה]\u0006 שזרע ביום שקראו בו את המגילה במקומו, ויום זה ודאי אסור לו במלאכה.","\u0003רבה בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא, אמר\u0004 להסביר בדרך אחרת: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שנטע רבי נטיעה \u0003ביומיה\u0004 \u0005[ביומו\u0006 ביום הקריאה במקומו\u0005],\u0006 אלא בעיקרו של דבר איסור \u0003הספד ותענית\u0004 ביום הפורים \u0003קבילו עלייהו\u0004 \u0005[קיבלו עליהם]\u0006 כל ישראל, אולם איסור \u0003מלאכה לא קבילו עלייהו\u0004 \u0005[קיבלו עליהם].\u0006","וראיה לדבר, ממה \u0003דמעיקרא כתיב\u0004 \u0005[שבתחילה נאמר]\u0006 כשהציעו מרדכי ואסתר את החג \u0003\"שמחה ומשתה ויום טוב\"\u0004 (אסתר ט, יט) \u0003ולבסוף כתיב\u0004 \u0005[נאמר]\u0006 שקיבלו לקיים עליהם \u0003\"לעשות אותם ימי משתה ושמחה\"\u0004 (אסתר ט, כב) \u0003ואילו \"יום טוב\" לא כתיב\u0004 \u0005[נאמר],\u0006 הרי שלא קיבלו עליהם לאסור בו מלאכה כביום טוב.","ושואלים: \u0003ואלא רב מאי טעמא לטייה לההוא גברא\u0004 \u0005[מה טעם קילל את אותו האיש]\u0006 אם מותר לעשות מלאכה בפורים? ומשיבים: \u0003דברים המותרים ואחרים נהגו בהם איסור הוה\u0004 \u0005[היה\u0006 הדבר\u0005],\u0006 וכלל הוא שדברים שמצד עיקר הדין מותרים הם, אבל אנשים במקום מסויים נוהגים בהם איסור — אסור לעשותם באותו מקום בפרהסיה. \u0003ו\u0004אילו \u0003באתריה\u0004 \u0005[במקומו]\u0006 של \u0003רבי לא\u0004 היה \u0003נהוג\u0004 כלל איסור מלאכה בפורים ולכן עשה בו מלאכה בפרהסיה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם\u0004 תפרש שנהגו לאסור מלאכה בפורים, אבל \u0003רבי\u0004 — \u0003נטיעה של שמחה נטע,\u0004 שפעמים נוטע אדם נטיעה שאין בה צורך כלכלי אלא מעשה של שמחה. \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]\u0006 בענין תעניות הציבור: \u0003עברו אלו\u0004 המועדים שקבעו לתעניות הציבור על הגשם \u0003ולא נענו\u0004 ישראל ולא בא גשם — \u0003ממעטין\u0004 הכל \u0003במשא ו\u0004ב\u0003מתן, בבנין ובנטיעה באירוסין ובנישואין.\u0004","\u0003ותנא עלה\u0004 \u0005[ושנה עליה\u0006 החכם בתוספתא\u0005]:\u0006 מה שאמרו \u0003בנין —\u0004 זה הוא \u0003בנין של שמחה\u0004 דווקא ולא בנין אחר, ו\u0003נטיעה\u0004 — הכוונה היא \u0003נטיעה של שמחה.\u0004 ומסבירים: \u0003איזהו בנין של שמחה? זה הבונה בית חתנות לבנו.\u0004 שהיו נוהגים לבנות עבור החתן בית מיוחד שבו היתה נערכת החתונה, ולפעמים היה הזוג גר בו. \u0003איזו היא נטיעה של שמחה? זה הנוטע אבורנקי\u0004 (גינה, שדרה) \u0003של מלכים\u0004 שעשויה רק לנוי ולשעשוע, ומכיוון שנטיעה כזו קרויה שמחה — עשה זאת רבי בפורים משום שמחה.","\u0003לגופא\u0004 של הלכה שהוזכרה קודם, אמרנו ש\u0003חזקיה קרי בטבריא בארביסר ובחמיסר\u0004 \u0005[\u0006היה \u0005קורא\u0006 את המגילה \u0005בטבריה בארבעה עשר ובחמישה עשר\u0006 באדר\u0005],\u0006 וזאת משום ש\u0003מספקא ליה אי\u0004 \u0005[\u0006ש\u0005מסופק\u0006 היה \u0005לו אם]\u0006 \u0003מוקפת חומה מימות יהושע בן נון היא אי\u0004 \u0005[או]\u0006 \u0003לא.\u0004 ושואלים: \u0003ומי מספקא ליה מלתא דטבריא\u0004 \u0005[והאם מסופק לו הדבר,\u0006 הענין, \u0005של טבריה]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"וערי מבצר הצדים צר וחמת רקת וכנרת\"\u0004 (יהושע יט, לה), \u0003וקיימא לן\u0004 \u0005[ומוחזק בידינו]\u0006 כי \u0003רקת — זו טבריא\u0004 \u0005[טבריה]!\u0006 ומשיבים: \u0003היינו טעמא דמספקא ליה\u0004 \u0005[זהו הטעם שמסופק לו],\u0006 לא משום זיהוי העיר, אלא \u0003משום דחד גיסא שורא דימא הות\u0004 \u0005[שצד אחד\u0006 של טבריה איננו בנוי חומה, אלא \u0005חומה של הים היה],\u0006 שהים הוא המקיף אותה.","ושואלים: \u0003אי הכי, אמאי מספקא ליה\u0004 \u0005[אם כך, מדוע\u0006 היה \u0005ספק לו]?\u0006 חומת ים \u0003ודאי\u0004 הלא \u0003לאו\u0004 \u0005[לא]\u0006 \u0003חומה היא! דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בדין בתי ערי חומה: \u0003\"אשר לו חמה\"\u0004 (ויקרא כה, ל) ודרשו: \u0003ולא שור איגר\u0004 \u0005[חומת גגות],\u0006 שאם העיר בנויה באופן שהיא מוקפת בתים צמודים זה לזה ללא חומה מיוחדת — אין זו נקראת עיר מוקפת חומה, וכן נאמר: \u0003\"\u0004אשר אין להם חומה \u0003סביב\"\u0004 (ויקרא כה, לא) — \u0003פרט לטבריא שימה\u0004 הוא \u0003חומתה\u0004 מצד אחד, ומכאן שטבריה איננה נקראת מוקפת חומה!","ומשיבים: \u0003לענין בתי ערי חומה לא מספקא ליה\u0004 \u0005[מסופק לו],\u0006 וברור לו שאין זו בכלל עיר חומה, \u0003כי קא מספקא ליה\u0004 \u0005[כאשר מסופק לו]\u0006 הרי זה \u0003לענין מקרא מגילה, מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003פרזים ומאי\u0004 \u0005[ומה\u0006 הם\u0005]\u0006 \u0003מוקפין דכתיבי\u0004 \u0005[שנאמרו]\u0006 ל\u0003גבי מקרא מגילה,\u0004 האם ההגדרה היא \u0003משום דהני מיגלו\u0004 \u0005[שאלו\u0006 הפרזים \u0005מגולים\u0006 הם\u0005]\u0006 \u0003והני\u0004 \u0005[ואלה]\u0006 המוקפים \u0003לא מיגלו\u0004 \u0005[מגולים\u0006 הם\u0005],\u0006 \u0003והא נמי מיגליא\u0004 \u0005[וזו גם כן מגולה] —\u0006 שהרי אין לה חומה סביב, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003משום דהני מיגנו\u0004 \u0005[שאלה\u0006 המוקפים \u0005מוגנים\u0006 הם\u0005]\u0006 \u0003והני\u0004 \u0005[ואלה\u0006 הפרוזים\u0005]\u0006 \u0003לא מיגנו\u0004 \u0005[מוגנים\u0006 הם\u0005]\u0006 \u0003והא נמי מיגניא\u0004 \u0005[וזו,\u0006 טבריה \u0005גם כן מוגנת\u0006 היא\u0005]\u0006 על ידי הים. \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003מספקא ליה\u0004 \u0005[מסופק\u0006 היה \u0005לו].\u0006","מספרים: \u0003רב אסי קרי\u0004 \u0005[\u0006היה \u0005קורא]\u0006 \u0003מגילה ב\u0004עיר \u0003הוצל\u0004 שבבבל \u0003בארביסר ובחמיסר\u0004 \u0005[בארבעה עשר ובחמישה עשר]\u0006 באדר, כי \u0003מספקא ליה\u0004 \u0005[\u0006היה \u0005מסופק לו]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003מוקפת חומה מימות יהושע בן נון היא, אי\u0004 \u0005[או]\u0006 \u0003לא,\u0004 משום שהיתה זו עיר עתיקה ביותר, שיש מקום לחשוב שהיתה עיר מוקפת חומה כבר באותם ימים. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת, לא כספק אלא כודאי, ש\u0003אמר רב אסי: האי\u0004 \u0005[זאת]\u0006 העיר \u0003הוצל\u0004 הריהי מחלק \u0003בית\u0004 (שבט) \u0003בנימין,\u0004 ו\u0003מוקפת חומה מימות יהושע בן נון היא.\u0004","אגב מה שעסקנו בבירור עניינה של טבריה, מספרים: \u0003אמר ר' יוחנן: כי הוינא טליא אמינא מלתא דשאילנא לסבייא\u0004 \u0005[כאשר הייתי ילד אמרתי דבר ששאלתי\u0006 עליו \u0005לזקנים]\u0006"],["\u0003ואישתכח כוותי\u0004 \u0005[ונמצא כמותי],\u0006 שאף שלא היה הדבר מקובל, התברר שצדקתי. שהוא סבר ש\u0003חמת זו\u0004 היא \u0003טבריא\u0004 \u0005[טבריה]\u0006 \u0003ולמה נקרא שמה \"חמת\"? על שום\u0004 (שם) \u0003חמי טבריא\u0004 המצויים בה. ואילו \u0003רקת זו ציפורי, ולמה נקרא שמה \"רקת\"? משום דמידלייא כרקתא דנהרא\u0004 \u0005[משום ש\u0006היא \u0005מוגבהת\u0006 מסביבתה \u0005כשפת הנהר].\u0006 \u0003כינרת זו גינוסר, ולמה נקרא שמה \"כינרת\"? דמתיקי פירא כקלא דכינרי\u0004 \u0005[שמתוקים פירותיה כקול הכינור].\u0006","\u0003אמר רבא: מי איכא למאן דאמר\u0004 \u0005[האם יש מי שאומר]\u0006 כי \u0003רקת לאו טבריא הוא\u0004 \u0005[לא טבריה היא]?\u0006 \u0003והא כי שכיב איניש הכא, התם ספדי ליה הכי\u0004 \u0005[והרי כאשר מת אדם\u0006 גדול \u0005כאן,\u0006 בבבל, \u0005שם סופדים לו\u0006 בלשון זו \u0005כך]:\u0006 \u0003\"גדול הוא בששך\u0004 \u0005[בבבל]\u0006 (ראה ירמיהו כה, כו) \u0003ושם\u0004 יצא \u0003לו ברקת\". וכי מסקי ארונא להתם, ספדי ליה הכי\u0004 \u0005[וכאשר מעלים ארון\u0006 של אדם חשוב \u0005לשם, סופדים לו כך]:\u0006 אתם \u0003אוהבי\u0004 ישראל ה\u0003שרידים יושבי רקת, צאו וקבלו הרוגי עומק,\u0004 כלומר, את אלו שמתו בבבל שהיא ארץ עמוקה ונמוכה, משמע, שהכל מסכימים שרקת זו טבריה.","וכן מספרים: \u0003כי נח נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003ר' זירא, פתח עליה ההוא ספדנא\u0004 \u0005[פתח עליו ספדן אחד]\u0006 את הספדו במילים אלה: \u0003ארץ שנער\u0004 (בבל) \u0003הרה וילדה,\u0004 שר' זירא היה מבבל, \u0003ארץ צבי\u0004 (ארץ ישראל) \u0003גידלה\u0004 את \u0003שעשועיה\u0004 של בבל, שאחר כך עלה לארץ ישראל וגדל בה, \u0003אוי נא לה, אמרה רקת, כי אבדה כלי חמדתה.\u0004 ואם כן, נראה שמקובל על הכל שרקת זו טבריה.","\u0003אלא אמר רבא: חמת זו חמי גרר\u0004 הסמוכים לטבריה, \u0003רקת זו טבריא, כינרת זו גינוסר, ולמה נקרא שמה\u0004 של טבריה \u0003\"רקת\"? שאפילו ריקנין שבה, מלאין מצות כרמון. ר' ירמיה אמר:\u0004 בעצם \u0003\"רקת\" שמה, ולמה נקרא שמה \"טבריא\" —\u0004 משום \u0003שיושבת בטבורה\u0004 (במרכזה) \u0003של ארץ ישראל. רבה אמר: \"רקת\" שמה, ולמה נקרא שמה \"טבריא\" —\u0004 כעין נוטריקון: \u0003שטובה ראייתה.\u0004","כיוון שעסקנו בזיהוי של שמות מקומות המוזכרים במקרא, \u0003אמר זעירא: קטרון\u0004 הנזכרת במקרא, \u0003זו\u0004 היא העיר \u0003ציפורי. ולמה נקרא שמה \"ציפורי\"?\u0004 מפני \u0003שיושבת בראש ההר כצפור.\u0004","ושואלים: \u0003וקטרון,\u0004 האם \u0003ציפורי היא? והא\u0004 \u0005[והרי]\u0006 \u0003קטרון בחלקו של זבולון הואי\u0004 \u0005[היתה],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"זבולון לא הוריש את יושבי קטרון ואת יושבי נהלל\"\u0004 (שופטים א, ל), שאף שהיתה מן הערים שנפלו בחלקו, מכל מקום עבר על הציווי של \"לא תחיה כל נשמה\" והותיר את בני העיר בחיים כדי שיעלו לו מס, ואנחנו יודעים כי \u0003זבולון מתרעם על מדותיו\u0004 (מזלו) \u0003הוה\u0004 \u0005[היה],\u0006 \u0003שנאמר: \"זבלון עם חרף נפשו למות\"\u0004 (שופטים ה, יח), \u0003מה טעם? משום\u0004 ש\u0003\"נפתלי על מרומי שדה\"\u0004 (שופטים ה, יח), וכך מפרשים:","\u0003אמר זבולון לפני הקדוש ברוך הוא: רבונו של עולם, לאחיי\u0004 שאר השבטים הסמוכים לנחלתי \u0003נתת להם\u0004 ארץ \u0003שדות וכרמים, ולי נתת הרים וגבעות. לאחיי נתת להם ארצות ולי נתת ימים ונהרות! אמר לו\u0004 הקדוש ברוך הוא: בכל זאת \u0003כולן צריכין לך על ידי חלזון, שנאמר: \"עמים הר יקראו\u0004 שם יזבחו זבחי צדק כי שפע ימים יינקו \u0003ושפני טמוני חול\"\u0004 (דברים לג, יט),","ו\u0003תני\u0004 \u0005[\u0006ו\u0005שנה]\u0006 \u0003רב יוסף\u0004 על כך: \u0003\"שפני\" — זה חלזון\u0004 הנמצא בימו של זבולון, \u0003\"טמוני\" — זו טרית,\u0004 מין דג (סרדין) שדגים במימי החוף, \u0003\"חול\" — זו\u0004 החול שממנו עושים \u0003זכוכית לבנה. אמר\u0004 זבולון \u0003לפניו:\u0004 אמנם כל אלה נמצאים בארצי, אולם, \u0003רבונו של עולם מי מודיעני\u0004 אם יקחו ממני בלי רשות? \u0003אמר לו\u0004 ככתוב באותו פסוק: \u0003\"שם יזבחו זבחי צדק\", סימן זה יהא לך: כל הנוטל ממך בלא דמים\u0004 (תשלום) — \u0003אינו מועיל בפרקמטיא\u0004 (במסחר) \u0003שלו כלום.\u0004","ומכל מקום למדנו מכאן שארצו של זבולון היתה ארץ שלא היו בה שדות וכרמים, \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 ש\u0003קטרון זו ציפורי, אמאי\u0004 \u0005[מדוע]\u0006 \u0003מתרעם על מדותיו? והא הויא\u0004 \u0005[והרי היתה]\u0006 \u0003ציפורי\u0004 שהיא \u0003מילתא דעדיפא טובא\u0004 \u0005[דבר שעדיף ביותר]\u0006 מבחינת פוריותו! \u0003וכי תימא דלית\u0004 \u0005[ואם תאמר שאין]\u0006 \u0003בה\u0004 קרקע משובחת שהיא \u0003זבת חלב ודבש — והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ריש לקיש: לדידי חזי לי\u0004 \u0005[\u0006אני \u0005עצמי ראיתי]\u0006 את ארץ \u0003זבת חלב ודבש\u0004 שבסביבת \u0003ציפורי, והויא\u0004 \u0005[והיתה]\u0006 \u0003ששה עשר מיל על ששה עשר מיל!\u0004","\u0003וכי תימא דלא נפישא דידיה כדאחוה\u0004 \u0005[ואם תאמר שאין מרובה שלו כשל אחיו]\u0006 והם קיבלו יותר ממנו ארץ זבת חלב ודבש, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר בר חנה אמר ר' יוחנן: לדידי חזי לי\u0004 \u0005[\u0006אני \u0005בעצמי ראיתי]\u0006 \u0003זבת חלב ודבש\u0004 של \u0003כל ארעא\u0004 \u0005[ארץ]\u0006 \u0003ישראל, והויא\u0004 \u0005[והיה\u0006 גודלה\u0005]\u0006 \u0003כ\u0004מו \u0003מ\u0004ן המקום \u0003בי כובי\u0004 ו\u0003עד אקרא\u0004 \u0005[מבצר]\u0006 \u0003תולבקני,\u0004 ובסך הכל: \u0003עשרין ותרתין פרסי אורכא, ופותיא שיתא פרסי\u0004 \u0005[עשרים ושתיים פרסות אורכה, ורוחבה שש פרסות]\u0006 שהם פחות מחלקו של זבולון בצפורי!","ומשיבים: אכן, מבחינת היבול היה חלקו מספיק ואולם \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003שדות וכרמים עדיפא ליה\u0004 \u0005[עדיפים\u0006 היו \u0005לו],\u0006 כי זבת חלב ודבש שבחלקו היתה בארץ הררית שיש טורח בעיבודה. ומעירים: \u0003דיקא נמי דכתיב\u0004 \u0005[מדוייק גם כן,\u0006 ממה \u0005שנאמר]:\u0006 \u0003\"ונפתלי על מרומי שדה\",\u0004 שטענתו של זבולון היתה מדוע לנפתלי יש שדות, ומעירים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא.","בענין זיהוי שמות מקומות: \u0003אמר ר' אבהו\u0004 מה שנאמר \u0003\"ועקרון תעקר\"\u0004 (צפניה ב, ד) — \u0003זו\u0004 רמז ל\u0003קסרי בת אדום.\u0004 שרוב בני העיר היו יוונים ורומאים, והיא היתה השלטת על ארץ ישראל במשך זמן השלטון הרומי, \u0003שהיא יושבת בין החולות, והיא היתה יתד תקועה לישראל\u0004 עוד \u0003בימי יוונים\u0004 שהיתה מכשול להתפשטות הישוב היהודי \u0003וכשגברה מלכות בית חשמונאי ונצחום, היו קורין אותה \"אחידת\u0004 \u0005[תפוסת,\u0006 כבושת\u0005]\u0006 \u0003מגדל שיר\".\u0004","\u0003אמר ר' יוסי בר חנינא מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"והסירתי דמיו מפיו ושקציו מבין שניו ונשאר גם הוא לאלהינו\"\u0004 (זכריה ט, ז) — כך יש לדרוש: \u0003\"והסרתי דמיו מפיו\" — זה בית במיא\u0004 (במות להקרבת קרבנות) \u0003שלהם —\u0004 מקום הקרבת הקרבנות שלהם, \u0003\"ושקציו מבין שניו\" — זה בית גליא\u0004 (גלי אבנים של פולחן) \u0003שלהן,\u0004","\u0003\"ונשאר גם הוא לאלהינו\" — אלו בתי כנסיות ובתי מדרשות שבאדום.\u0004 ועוד דרשו מה שנאמר: \u0003\"והיה כאלף ביהודה ועקרון כיבוסי\"\u0004 (זכריה ט, ז) \u0003אלו תראטריות וקרקסיות\u0004 (בתי תיאטרון וקרקסים) \u0003שבאדום, שעתידין שרי יהודה ללמד בהן תורה ברבים.\u0004 והוא שרומז הכתוב, שארץ זו שהיא עכשיו של הגוים תהיה כאלוף (מלמד) ביהודה.","ועוד \u0003אמר ר' יצחק: לשם — זו\u0004 העיר הקרויה בזמן התלמוד \u0003פמייס, \"עקרון תעקר\" — זו קסרי בת אדום, שהיא היתה מטרופולין\u0004 (עיר האם, הבירה) \u0003של מלכים. איכא דאמרי\u0004 \u0005[יש שאומרים,\u0006 מפרשים\u0005]:\u0006 \u0003דמרבי\u0004 \u0005[שמגדלים]\u0006 \u0003בה מלכי\u0004 \u0005[\u0006את ה\u0005מלכים]\u0006 \u0003ואיכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003דמוקמי מינה מלכי\u0004 \u0005[שמעמידים ממנה מלכים],\u0006 שמיושבי העיר הזאת מעמידים אחר כך מלכים לאדום.","ואמרו חכמים: \u0003קסרי וירושלים\u0004 הם שני ניגודים, ולכן \u0003אם יאמר לך אדם: חרבו שתיהן — אל תאמן,\u0004 אם יאמר לך: \u0003ישבו שתיהן\u0004 בשלווה — \u0003אל תאמן,\u0004 אלא אם יאמר לך ש\u0003חרבה קסרי וישבה ירושלים\u0004 או שיאמר לך \u0003חרבה ירושלים וישבה קסרי\u0004 — אז \u0003תאמן, שנאמר: \"\u0004יען אשר אמרה צור על ירושלים האח נשברה דלתות העמים נסבה אלי \u0003אמלאה החרבה\"\u0004 (יחזקאל כו, ב), ללמד: \u0003אם מליאה זו — חרבה זו, אם מליאה זו — חרבה זו\u0004 ששתיהן הן כניגודים זו לזו.","\u0003רב נחמן בר יצחק אמר\u0004 אותו רעיון \u0003מהכא\u0004 \u0005[מכאן\u0006 מפסוק זה\u0005]\u0006 שנאמר על יעקב ועשו: \u0003\"ולאם מלאם יאמץ\"\u0004 (בראשית כה, כג), לאמר: כשזה עולה — השני בהכרח יורד.","מכיוון שהזכרנו את אדום, \u0003אמר ר' יצחק: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"יחן רשע בל למד צדק\u0004 בארץ נכוחות יעול ובל יראה גאות ה'\u0003\"\u0004 (ישעיה כו, י) — \u0003אמר יצחק לפני הקדוש ברוך הוא: רבונו של עולם, יוחן עשו\u0004 שהוא בנו, וכידוע אהב אותו. \u0003אמר לו\u0004 הקדוש ברוך הוא: \u0003רשע הוא\u0004 עשו! \u0003אמר לו\u0004 יצחק לקדוש ברוך הוא: וכי \u0003\"בל למד צדק\",\u0004 כלומר, וכי אין אדם אשר יוכל ללמד עליו זכות ולדבר בצדקו? \u0003אמר לו\u0004 הקדוש ברוך הוא: \u0003\"בארץ נכחות יעול\",\u0004 כלומר, רשע גדול הוא ועתיד הוא להחריב את ארץ ישראל. \u0003אמר לו\u0004 יצחק: \u0003אם כן\u0004 אם רשע הוא כל כך, \u0003\"בל יראה גאות ה'\".\u0004","\u0003ואמר ר' יצחק: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"אל תתן ה' מאויי רשע זממו אל תפק ירומו סלה\"\u0004 (תהלים קמ, ט) — \u0003אמר יעקב לפני הקדוש ברוך הוא: רבונו של עולם, אל תתן לעשו הרשע תאות לבו,\u0004 כלומר, לעשות את מה שהוא רוצה, שרצונו לכלות אותנו בני יעקב. ומה שנאמר \u0003\"זממו אל תפק\"\u0004 מתפרש: אל תוציא ממנו את הזמם שמחזיק אותו ואיננו נותן לו להתפרץ ולהתחזק — \u0003זו\u0004"],["\u0003גרממיא של אדום\u0004 גרמניה הסמוכה לארץ אדום (רומי) \u0003שאלמלי הן\u0004 הגרמנים \u0003יוצאין\u0004 והולכים לפי דרכם, הרי הם \u0003מחריבין כל העולם כולו.\u0004","\u0003ואמר ר' חמא בר חנינא: תלת מאה קטירי תגא איכא\u0004 \u0005[שלוש מאות קשורי כתר יש]\u0006 \u0003בגרממיא של אדום,\u0004 כלומר, שלוש מאות מלכים קטנים, \u0003ותלת מאה ושיתין וחמישה מרזבני איכא ברומי\u0004 \u0005[ושלוש מאות ושישים וחמישה שרים יש ברומא]\u0006 \u0003ובכל יומא נפקי הני לאפי הני\u0004 \u0005[ובכל יום יוצאים אלה אל פני אלה\u0006 להילחם\u0005]\u0006 \u0003ומקטיל חד מינייהו, ומיטרדי לאוקמי מלכא\u0004 \u0005[ונהרג אחד מהם, ו\u0006הם \u0005נטרדים מלהעמיד מלך],\u0006 ומשום שאינם מתאחדים, אינם יכולים לנצח במלחמה. ומלחמות אלה שבין רומי והגרמנים הן שזוממות (מעכבות) את עשיו־רומי שלא יתגבר יותר מדי.","\u0003ואמר ר' יצחק\u0004 בסגנון הדברים שנאמרו בענין הקודם, \u0003אם יאמר לך אדם: יגעתי ולא מצאתי — אל תאמן.\u0004 וכן אם יאמר לך: \u0003לא יגעתי ו\u0004בכל זאת \u0003מצאתי — אל תאמן.\u0004 אבל אם יאמר: \u0003יגעתי ומצאתי — תאמן.\u0004","ומעירים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים \u0003בדברי תורה,\u0004 שבהם התוצאה והמציאה היא לפי היגיעה, \u0003אבל במשא ומתן\u0004 — הצלחה במסחר \u0003סייעתא\u0004 \u0005[סיוע]\u0006 \u0003הוא מן שמיא\u0004 \u0005[השמים],\u0006 שאין יחס בין ההצלחה והיגיעה. \u0003ולדברי תורה לא אמרן\u0004 \u0005[אמרנו]\u0006 \u0003אלא לחדודי\u0004 \u0005[ל\u0006ענין \u0005חידוד]\u0006 והעמקה בה, שהמתייגע יותר מבין יותר, \u0003אבל לאוקמי גירסא\u0004 \u0005[להעמיד גירסה]\u0006 של ידיעה בסיסית — \u0003סייעתא מן שמיא היא\u0004 \u0005[סיוע משמים הוא]\u0006 ולא כל אדם זוכה לו, ואפילו ברוב יגיעה ועמל.","\u0003ו\u0004עוד ממה ש\u0003אמר ר' יצחק: אם ראית רשע שהשעה משחקת לו\u0004 שהוא מצליח ביותר — \u0003אל תתגרה בו, שנאמר: \"אל תתחר במרעים\"\u0004 (תהלים לז, א). \u0003ולא עוד, אלא שדרכיו מצליחין\u0004 גם אם אתה מתגרה בו, \u0003שנאמר: \"יחילו דרכו בכל עת\"\u0004 (תהלים י, ה). \u0003ולא עוד, אלא\u0004 שאם דנים כנגדו \u0003שזוכה בדין, שנאמר: \"מרום משפטיך מנגדו\"\u0004 (תהלים י, ה), כאילו המשפט מורם מעליו ואינו נוגע בו. \u0003ולא עוד, אלא שרואה בשונאיו\u0004 כשהם נופלים, \u0003שנאמר: \"כל צורריו יפיח בהם\"\u0004 (תהלים י, ה).","ותוהים: \u0003איני\u0004 \u0005[האם כן הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי: מותר להתגרות ברשעים בעולם הזה, שנאמר: \"עזבי תורה יהללו רשע ושמרי תורה יתגרו בם\"\u0004 (משלי כח, ד), \u0003ותניא\u0004 \u0005[ו\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' דוסתאי בר מתון אמר: מותר להתגרות ברשעים בעולם הזה, ואם לחשך\u0004 (ילחש לך) \u0003אדם\u0004 לומר לך שאין הדבר כן, ויסתמך על הכתוב \u0003\"אל תתחר במרעים ואל תקנא בעשי עולה\"\u0004 (תהלים לז, א) — דע לך ש\u0003מי שלבו נוקפו\u0004 (שהוא מפחד) \u0003אומר כן.\u0004","\u0003אלא\u0004 כוונת אותו פסוק היא: \u0003\"אל תתחר במרעים\" —\u0004 שלא תתחרה במעשיהם \u0003להיות כמרעים\u0004 (עושי רע), \u0003\"ואל תקנא בעשי עולה\" — להיות כעושי עולה. ו\u0004ראיה לדבר ממה ש\u0003אומר\u0004 הכתוב במקום אחר: \u0003\"אל יקנא לבך בחטאים\u0004 כי אם ביראת ה' כל היום\u0003\"\u0004 (משלי כג, יז), משמע שלקנא בחטאים אין פירושו להילחם כנגדם בקנאות, אלא לקנא בהם להיות כמותם, וממקורות אלה נובע שמותר להתגרות ברשעים, ושלא כדברי רבי יצחק!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמר ר' יצחק שלא יתגרה בו, הרי זה \u0003במילי דידיה\u0004 \u0005[בדברים,\u0006 עניינים \u0005שלו],\u0006 \u0003והא\u0004 \u0005[וזה]\u0006 שמשמע מדברי הכתובים שאפשר להתגרות בו, הרי זה \u0003במילי דשמיא\u0004 \u0005[בדברי,\u0006 ענייני \u0005שמים].\u0006","\u0003ואיבעית אימא: הא והא במילי דידיה\u0004 \u0005[ואם תרצה אמור: זה וזה בדברים שלו],\u0006 \u0003ו\u0004בכל זאת דבר זה \u0003לא קשיא\u0004 \u0005[קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרו שיתגרה, מדובר \u0003בצדיק גמור,\u0004 ו\u0003הא\u0004 \u0005[וזה]\u0006 שהזהיר שלא יתגרה בו — \u0003בצדיק שאינו גמור.\u0004 ש\u0003אמר רב הונא, מאי דכתיב\u0004 \u0005[מהו\u0006 \u0005שנאמר]:\u0006 \u0003\"למה תביט בוגדים תחריש בבלע רשע צדיק ממנו\"\u0004 (חבקוק א, יג) — ללמדך: \u0003צדיק ממנו בולע,\u0004 שהרשע יכול לבלוע מי שהוא צדיק רק ממנו, כלומר, שאינו צדיק גמור, אבל \u0003צדיק גמור — אינו בולע.\u0004","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר לסתירה: \u0003שעה משחקת לו שאני\u0004 \u0005[שונה],\u0006 שאם אתה רואה שהשעה משחקת לו אין אף לצדיק גמור להתגרות בו, משום שעכשיו מסייעים בידו משמים.","כיוון שהזכרנו קודם את רומי והכרוך בה, מביאים מה ש\u0003אמר עולא: איטליא של יון,\u0004 שהיא דרומה של איטליה, \u0003זה כרך גדול של רומי, והויא\u0004 \u0005[והריהי]\u0006 \u0003תלת מאה\u0004 \u0005[שלוש מאות]\u0006 \u0003פרסה על תלת מאה\u0004 \u0005[שלוש מאות]\u0006 \u0003פרסה, ויש בה שלש מאות ששים וחמישה שווקים, כמנין ימות החמה, וקטן שבכולם\u0004 הוא שוק \u0003של מוכרי עופות, והויא\u0004 \u0005[והוא]\u0006 \u0003ששה עשר מיל על ששה עשר מיל, ומלך\u0004 (הקיסר הרומי) \u0003סועד בכל יום באחד מהן,\u0004","\u0003ו\u0004עוד, \u0003הדר בה\u0004 ברומי \u0003אף על פי שאינו נולד בה — נוטל פרס\u0004 שכר ומשכורת לקיומו \u0003מבית המלך, והנולד בה אף על פי שאינו דר בה\u0004 — גם הוא \u0003נוטל פרס מבית המלך, ושלשת אלפים בי בני\u0004 \u0005[בתי מרחצאות]\u0006 \u0003יש בו, וחמש מאות חלונות מעלין עשן\u0004 מבתי המרחץ אל \u0003מחוץ לחומה\u0004 באופן שאין החומות עצמן משחירות ממנו, \u0003צדו אחד\u0004 של המקום הוא \u0003ים וצדו אחד הרים וגבעות, צדו אחד מחיצה של ברזל וצדו אחד חולסית\u0004 (מקום אבנים) \u0003ומצולה\u0004 (בוץ ומים).","\u0003קראו את המגילה באדר הראשון\u0004 ואחר כך \u0003נתעברה השנה\u0004 ויש עכשיו איפוא אדר שני — \u0003קורין אותה\u0004 בשנית \u0003באדר שני.\u0004 וכלל אמרו: \u0003אין בין אדר הראשון לאדר השני\u0004 הבדל במה שיש לעשות בהם \u0003אלא קריאת המגילה, ומתנות לאביונים,\u0004 שבשנה מעוברת אין מקיימים את שתי אלה אלא באדר השני דווקא ולא בראשון.","ומעירים: \u0003הא לענין סדר פרשיות\u0004 ארבע הפרשיות (שקלים, זכור, פרה, החודש) שנוהגים להוסיף לקריאת התורה בסביבות הפורים \u0003זה וזה שוין,\u0004 שקריאתם באדר ראשון פוטרת מלקרוא באדר שני.","ומעירים: אם כן, \u0003מני מתניתין\u0004 \u0005[\u0006כשיטת \u0005מי משנתנו]?\u0006 \u0003לא\u0004 כשיטת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 בברייתא שנביא, \u0003ולא\u0004 כשיטת \u0003ר' אליעזר בר' יוסי ולא\u0004 כשיטת \u0003רבן שמעון בן גמליאל. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003קראו את המגילה באדר הראשון ונתעברה השנה — קורין אותה באדר השני, שכל מצות שנוהגות בשני נוהגות בראשון, חוץ ממקרא מגילה,\u0004","\u0003ר' אליעזר בר' יוסי אומר: אין קורין אותה באדר השני\u0004 כלל, \u0003שכל מצות שנוהגות בשני נוהגות בראשון\u0004 וכיון שקיימן בראשון, שוב אינו זקוק לשני.","\u0003רבן שמעון בן גמליאל אומר משום\u0004 (בשם) \u0003ר' יוסי: אף קורין אותה באדר השני, שכל מצות שנוהגות בשני אין נוהגות בראשון. ושוין\u0004 כולם \u0003בהספד ובתענית שאסורין בזה ובזה.\u0004 כלומר, שימי ארבעה עשר וחמישה עשר בחודש אדר, בין באדר ראשון בין באדר שני — אין מספידים ואין מתענים בהם.","ותחילה מבררים את הברייתא לגופה: הלא שיטת \u0003רבן שמעון בן גמליאל היינו\u0004 \u0005[זוהי]\u0006 שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 ומה חידש? \u0003אמר רב פפא:\u0004 לענין \u0003סדר פרשיות איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005].\u0006 וכיצד? שה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003סבר\u0004 כי \u0003לכתחילה\u0004 עושים את סדר הפרשיות \u0003בשני, ואי עבוד\u0004 \u0005[ואם עשו]\u0006 \u0003בראשון — עבוד\u0004 \u0005[עשו],\u0006 \u0003בר\u0004 \u0005[חוץ]\u0006 \u0003ממקרא מגילה, דאף על גב דקרו\u0004 \u0005[שאף על פי שקראו]\u0006 כבר \u0003בראשון\u0004 — \u0003קרו\u0004 \u0005[קוראים]\u0006 פעם נוספת \u0003בשני.\u0004","\u0003ו\u0004אילו \u0003ר' אליעזר בר' יוסי סבר: אפילו מקרא מגילה לכתחילה בראשון,\u0004 ובשני אין צורך לחזור ולקרוא. \u0003ורבן שמעון בן גמליאל סבר: אפילו סדר פרשיות, אי\u0004 \u0005[אם]\u0006 כבר \u0003קרו\u0004 \u0005[קראו]\u0006 את הפרשיות \u0003בראשון — קרו\u0004 \u0005[קוראים]\u0006 אותם פעם נוספת \u0003בשני,\u0004","ואם כן, \u0003מני\u0004 \u0005[\u0006של \u0005מי היא]\u0006 משנתנו שלנו, לפי איזו שיטה היא הולכת? \u0003אי\u0004 \u0005[אם]\u0006 לפי ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003קשיא\u0004 \u0005[קשה]\u0006 מענין \u0003מתנות\u0004 לאביונים, שבברייתא הזכיר רק מקרא מגילה ואילו במשנה מזכיר גם מתנות, \u0003אי\u0004 \u0005[אם]\u0006 לפי \u0003ר' אליעזר בר' יוסי — קשיא נמי\u0004 \u0005[קשה גם כן]\u0006 מענין \u0003מקרא מגילה,\u0004 ו\u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 לפי \u0003רבן שמעון בן גמליאל\u0004 — \u0003קשיא\u0004 \u0005[קשה]\u0006 גם כן \u0003סדר פרשיות!\u0004","ומתרצים: \u0003לעולם\u0004 תאמר שמשנתנו היא לפי שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 שבברייתא, \u0003ותנא\u0004 \u0005[ושנה\u0006 החכם בברייתא\u0005]\u0006 \u0003מקרא מגילה והוא הדין\u0004 לעניין \u0003מתנות לאביונים, דהא בהא תליא\u0004 \u0005[שזה בזה תלוי],\u0006 שהרי כבר הסברנו שביום שבו קוראים את המגילה גובים ומחלקים גם מתנות לאביונים.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם\u0004 שיטת \u0003רבן שמעון בן גמליאל היא, ומתניתין חסורי מיחסרא והכי קתני\u0004 \u0005[ומשנתנו חסרה\u0006 דבר מה \u0005וכך יש לשנותה]:\u0006 \u0003אין בין ארבעה עשר שבאדר הראשון לארבעה עשר שבאדר השני אלא מקרא מגילה ומתנות. הא\u0004 \u0005[הרי]\u0006 \u0003לענין הספד ותענית — זה וזה שוין, ואילו\u0004 מענין \u0003סדר\u0004 ה\u0003פרשיות לא מיירי\u0004 \u0005[אינו עוסק\u0006 כלל\u0005]\u0006 ולא בא לדון אלא בפורים בלבד.","\u0003אמר ר' חייא בר אבין אמר ר' יוחנן: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כרבן שמעון בן גמליאל שאמר משום\u0004 (בשם) \u0003ר' יוסי.\u0004","\u0003אמר ר' יוחנן: ושניהם\u0004 גם רבן שמעון, וגם ר' אליעזר בר' יוסי \u0003מקרא אחד דרשו,\u0004 אלא שנחלקו בפירושו, שנאמר: \u0003\"\u0004להיות עושים את יום ארבעה עשר בחודש אדר ואת יום חמישה עשר בו \u0003בכל שנה ושנה\"\u0004 (אסתר ט, כא), \u0003ר' אליעזר בר' יוסי סבר:\u0004 כפי שנוהגים \u0003בכל שנה ושנה\u0004 צריכים לעשות גם בשנה מעוברת, \u0003מה כל שנה ושנה\u0004 עושים את חג הפורים ב\u0003אדר הסמוך לשבט — אף כאן\u0004 בשנה מעוברת יש לעשות את חג הפורים ב\u0003אדר הסמוך לשבט,\u0004","\u0003ורבן שמעון בן גמליאל סבר: \"בכל שנה ושנה\", מה כל שנה ושנה — אדר הסמוך לניסן, אף כאן,\u0004 בשנה מעוברת, יש לעשות את חג הפורים ב\u0003אדר הסמוך לניסן.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ר' אליעזר בר' יוסי מסתבר טעמא\u0004 \u0005[מסתבר טעם]\u0006 דבריו, שכן כלל הוא ש\u0003אין מעבירין על המצות,\u0004 שכאשר באה לידו של אדם מצווה אין לדחותה ויש לעשותה מיד, \u0003אלא רבן שמעון בן גמליאל מאי טעמא\u0004 \u0005[מה טעם]\u0006 דבריו?","\u0003אמר ר' טבי: טעמא\u0004 \u0005[טעם]\u0006 דברי \u0003ר' שמעון בן גמליאל\u0004 הוא, ש\u0003מסמך\u0004 \u0005[שלסמוך]\u0006 \u0003גאולה לגאולה עדיף\u0004 הוא, וראוי לסמוך גאולת פורים לגאולת פסח.","ואילו \u0003ר' אלעזר אמר: טעמא\u0004 \u0005[טעם]\u0006 דברי \u0003ר' שמעון בן גמליאל\u0004 נלמד \u0003מהכא\u0004 \u0005[מכאן],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לקים את אגרת הפרים הזאת השנית\"\u0004 (אסתר ט, כט), לרמז שפעמים קוראים אותה בחודש השני.","ומעירים: \u0003ואיצטריך למיכתב\u0004 \u0005[והוצרך לכתוב]\u0006"],["\u0003\"השנית\" ואיצטריך למיכתב\u0004 \u0005[והוצרך לכתוב]\u0006 גם \u0003\"בכל שנה ושנה\"\u0004 ואין די בראיה אחת. \u0003דאי\u0004 \u0005[שאם]\u0006 היה מביא ראיה רק \u0003מ\"בכל שנה ושנה\" הוה אמינא כי קושין\u0004 \u0005[הייתי אומר כמו קושייתנו]\u0006 שהקשינו מדוע לא נעשהו סמוך לשבט, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 במה שנאמר \u0003\"השנית\". ואי אשמועינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 \u0003\"השנית\"\u0004 בלבד \u0003הוה אמינא בתחילה\u0004 \u0005[הייתי אומר\u0006 כי \u0005מלכתחילה]\u0006 יש לעשות פורים \u0003בראשון ובשני\u0004 יחד, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003\"בכל שנה ושנה\",\u0004 לומר שאף בשנת העיבור, כבכל שנה ושנה, עושים רק פעם אחת.","ושואלים: \u0003ור' אליעזר בר' יוסי האי\u0004 \u0005[\u0006מלה \u0005זו]\u0006 \u0003\"השנית\" מאי עביד ליה\u0004 \u0005[מה עושה הוא\u0006 בה\u0005]\u0006 ומה דורש הוא מזה? ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרכה לו]\u0006 לדרשה של \u0003רב שמואל בר יהודה,\u0004 ש\u0003אמר רב שמואל בר יהודה: בתחילה קבעוה\u0004 את שמחת הפורים \u0003בשושן\u0004 בלבד, \u0003ולבסוף בכל העולם כולו,\u0004 על פי אגרת הפורים השנית.","אגב דברי רב שמואל בר יהודה לענין קביעת חג הפורים, מובא עוד, \u0003אמר רב שמואל בר יהודה: שלחה להם אסתר לחכמים: קבעוני לדורות,\u0004 כלומר, עשו את חגיגת הפורים וקריאת המגילה תקנה לדורות! \u0003שלחו לה: קנאה את מעוררת עלינו לבין האומות,\u0004 שהרי במגילה מסופר נצחון היהודים על הגויים, ומוטב שלא נפרסם את הדבר. \u0003שלחה להם: כבר כתובה אני על דברי הימים למלכי מדי ופרס,\u0004 ואם כן ידוע כבר הדבר בעולם וראוי שגם בישראל יעשו כן.","מסופר: \u0003רב ורב חנינא ור' יוחנן ורב חביבא מתנו\u0004 \u0005[\u0006היו \u0005שונים],\u0006 ומעירים: \u0003בכוליה\u0004 \u0005[בכל]\u0006 \u0003סדר מועד כל\u0004 מקום שנמצא \u0003כי האי זוגא\u0004 \u0005[\u0006בדומה \u0005לזוג הזה]\u0006 של ארבעת החכמים \u0003חלופי\u0004 \u0005[מחליפים]\u0006 את \u0003ר' יוחנן ומעייל\u0004 \u0005[ומכניסים]\u0006 במקומו את \u0003ר' יונתן,\u0004 וכך אמרו: \u0003שלחה להם אסתר לחכמים: כתבוני לדורות. שלחו לה:\u0004 כבר נאמר \u0003\"הלא כתבתי לך שלישים\"\u0004 (משלי כב, כ), לומר: \u0003שלישים ולא רבעים,\u0004 כלומר, שיש להזכיר את מפלת עמלק שלוש פעמים, וכיון שהיא נזכרת בשלושה מקומות במקרא, אין צורך להוסיף לה עוד מקור רביעי,","\u0003עד שמצאו לו מקרא כתוב בתורה,\u0004 ומה נאמר? \u0003\"כתב זאת זכרון בספר\u0004 ושים באזני יהושע כי מחה אמחה את זכר עמלק מתחת השמים\u0003\"\u0004 (שמות יז, יד), וכך דרשו: \u0003\"כתב זאת\" — מה שכתוב כאן\u0004 בספר שמות \u0003וב\u0004ספר \u0003משנה תורה\u0004 (ספר דברים) שהוא הדבר הכתוב בתורה, \u0003\"זכרון\" — מה שכתוב בנביאים\u0004 בענין זה, \u0003\"בספר\" — מה שכתוב במגלה,\u0004 ואם כן המגילה היא הזכרה שלישית ולא רביעית. שכל שנזכר בתורה בענין זה נחשב אחד.","ומעירים: \u0003כתנאי\u0004 \u0005[כתנאים]\u0006 שנחלקו בענין זה, שהיו שדרשו: \u0003\"כתב זאת\" — מה שכתוב כאן\u0004 בספר שמות, \u0003\"זכרון\" — מה שכתוב במשנה תורה, \"בספר\" — מה שכתוב בנביאים.\u0004 אלו \u0003דברי ר' יהושע.\u0004 ואילו \u0003ר' אלעזר המודעי אומר: \"כתב זאת\" — מה שכתוב כאן ובמשנה תורה, \"זכרון\" — מה שכתוב בנביאים, \"בספר\" — מה שכתוב במגילה,\u0004 וגם כאן נחלקו אם למגילה יש תוקף וקדושה כשאר ספרי המקרא.","ו\u0003אמר רב יהודה אמר שמואל:\u0004 אף שגזרו חכמים שכתבי הקודש יטמאו את הידים הנוגעות בהם כדי להרחיק את הספרים מן התרומה, מכל מקום מגילת \u0003אסתר אינה מטמאה את הידים,\u0004 לפי שלא נתקדשה בקדושת כתבי הקודש.","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר\u0006 מכאן\u0005]\u0006 ש\u0003סבר שמואל\u0004 שמגילת \u0003אסתר לאו\u0004 \u0005[לא]\u0006 \u0003ברוח הקודש נאמרה? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל\u0004 עצמו ש\u0003אסתר ברוח הקודש נאמרה!\u0004 ומתרצים: \u0003נאמרה לקרות,\u0004 שעצם המגילה ברוח הקודש נקבעה ומשום כך יש לקרוא אותה ברבים \u0003ו\u0004אולם \u0003לא נאמרה ליכתוב,\u0004 כלומר, שאין הדברים הכתובים מקודשים באותיותיהם שתהא בהם קדושת כתבי הקודש.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005],\u0006 מן המשנה, ששנינו, \u0003ר' מאיר אומר:\u0004 ספר \u0003קהלת — אינו מטמא את הידים,\u0004 שאין בו קדושת כתבי הקודש \u0003ומחלוקת בשיר השירים\u0004 אם מטמא. \u0003ר' יוסי אומר: שיר השירים מטמא את הידים, ומחלוקת\u0004 היא \u0003בקהלת. ר' שמעון אומר: קהלת\u0004 הוא \u0003מקולי בית שמאי ומחומרי בית הלל,\u0004 שלבית הלל הוא מטמא ולבית שמאי אינו מטמא, \u0003אבל רות ושיר השירים ואסתר\u0004 לכל הדעות \u0003מטמאין את הידים.\u0004 הרי משנה מפורשת שלדעת הכל אסתר מטמא את הידים. ומשיבים: \u0003הוא\u0004 שמואל ש\u0003אמר\u0004 את דבריו, היה זה \u0003כ\u0004שיטת \u0003ר' יהושע\u0004 שהובאה קודם, שמגילת אסתר לא נתקדשה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן מנסיא אומר: קהלת אינו מטמא את הידים מפני שחכמתו של שלמה היא\u0004 אבל אינה ברוח הקודש, \u0003אמרו לו:\u0004 ודאי ברוח הקודש נאמרה, שמגילת קהלת נבחרה משום כך משאר דברי שלמה, שהרי \u0003וכי זו בלבד אמר? והלא כבר נאמר: \"וידבר שלשת אלפים משל\u0004 ויהי שירו חמישה ואלף\u0003\"\u0004 (מלכים א' ה, יב) הרי שאמר שלמה משלים הרבה ורק חלק מהם אספו במקרא ובודאי יחודם של אלה הוא בכך שברוח הקודש נאמרו. \u0003ואומר: \"אל תוסף על דבריו\"\u0004 (משלי ל, ו).","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 מדוע מוסיף \u0003\"ואומר\"?\u0004 הרי לכאורה הראיה הראשונה מספקת! ומשיבים: \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003מימר טובא\u0004 \u0005[לומר הרבה]\u0006 \u0003אמר,\u0004 אלא שהעלה על הכתב רק דברים מסויימים, \u0003דאי בעי\u0004 \u0005[שאם רצה]\u0006 להעלות על הכתב דבר מסויים — אכן \u0003איכתיב\u0004 \u0005[נכתב],\u0006 \u0003ודאי בעי\u0004 \u0005[ואם רצה]\u0006 שלא להעלות על הכתב דברים אחרים — \u0003לא איכתיב\u0004 \u0005[נכתב],\u0006 ולכן לא נשארו כל דבריו. \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ממה שנאמר: \u0003\"אל תוסף על דבריו\",\u0004 לומר שאם אסור להוסיף עליהם, משמע שברוח הקודש נאמרו.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' אליעזר אומר:\u0004 מגילת \u0003אסתר ברוח הקודש נאמרה, שנאמר: \"ויאמר המן בלבו\"\u0004 (אסתר ו, ו) שאם אינה מרוח הקודש — מניין אם כן ידעו מה חשב המן בלבו? \u0003ר' עקיבא אומר: אסתר ברוח הקודש נאמרה, שנאמר: \"ותהי אסתר נשאת חן בעיני כל ראיה\"\u0004 (אסתר ב, טו), וכיצד ידעו זאת, אם לא ברוח הקודש?!","\u0003ר' מאיר אומר: אסתר ברוח הקודש נאמרה, שנאמר\u0004 בענין הקשר שקשרו בגתן ותרש על אחשורוש: \u0003\"ויודע הדבר למרדכי\"\u0004 (אסתר ב, כב), וכיצד נודע לו? ודאי ברוח הקודש. \u0003ר' יוסי בן דורמסקית אומר: אסתר ברוח הקודש נאמרה, שנאמר: \"ובבזה לא שלחו את ידם\"\u0004 (אסתר ט, טו) וכיצד ידעו מה קרה בכל העולם? אלא ודאי ברוח הקודש הוא.","\u0003אמר שמואל: אי הואי התם, הוה אמינא מלתא דעדיפא מכולהו\u0004 \u0005[אילו הייתי שם\u0006 בין התנאים \u0005הייתי אומר דבר ש\u0006הוא \u0005עדיף מכולם]\u0006 והוא, \u0003שנאמר\u0004 במגילה: \u0003\"קימו וקבל\"\u0004 (אסתר ט, כז) וכבר דרשוהו: \u0003קימו למעלה מה שקיבלו למטה,\u0004 ודבר זה יכול להיאמר רק ברוח הקודש.","\u0003אמר רבא: לכולהו אית להו פירכא\u0004 \u0005[לכולם יש פירכה]\u0006 לסתור את דבריהם, \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מ\u0004לדברי \u0003שמואל דלית ליה פירכא\u0004 \u0005[שאין לו פירכה],\u0006 ומסבירים מה היא הפירכה: שמה שאמר \u0003ר' אליעזר\u0004 כיצד ידעו מה חשב המן בליבו — \u0003סברא הוא\u0004 שהרי \u0003לא הוה איניש דחשיב למלכא כוותיה\u0004 \u0005[לא היה אדם שחשוב למלך כמותו]\u0006 \u0003והאי כי קא מפיש טובא\u0004 \u0005[וזה שהירבה הרבה]\u0006 \u0003ואמר\u0004 \"יביאו לבוש מלכות\" (אסתר ו, ח) — \u0003אדעתיה דנפשיה קאמר\u0004 \u0005[על דעת\u0006 שיעשו זאת עבור \u0005עצמו אמר].\u0006","וכן מה ש\u0003אמר ר' עקיבא\u0004 כיצד ידעו שמצאה חן בעיני הכל — \u0003דלמא\u0004 \u0005[שמא]\u0006 יש להבינו מסברה ו\u0003כ\u0004דברי \u0003ר' אלעזר,\u0004 ש\u0003אמר: מלמד שכל אחד ואחד נדמתה לו כ\u0004בת \u0003אומתו,\u0004 ולכן סביר להניח שמצאה חן בעיני הכל.","\u0003והא\u0004 \u0005[וזה]\u0006 שאמר \u0003ר' מאיר\u0004 הלומד מזה שנודע דבר הקשר על אחשוורוש למרדכי — \u0003דלמא\u0004 \u0005[שמא]\u0006 היה הדבר \u0003כ\u0004דעת \u0003ר' חייא בר אבא,\u0004 ש\u0003אמר: בגתן ותרש שני טרשיים היו\u0004 ודיברו זה עם זה בשפתם ומרדכי שהיה בקי בלשונות רבות, הבין מה הם מדברים.","\u0003והא\u0004 \u0005[וזה]\u0006 שאמר \u0003ר' יוסי בן דורמסקית\u0004 מהיכן ידעו מה קרה בכל העולם בענין הביזה — \u0003דלמא פריסתקי שדור\u0004 \u0005[שמא שליחים שלחו]\u0006 והם שהודיעו להם. אלא הראיה שמביא \u0003שמואל\u0004 שקיימו למעלה מה שקיבלו למטה, \u0003ודאי לית ליה פירכא\u0004 \u0005[אין לו פירכה].\u0006 \u0003אמר רבינא: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים]\u0006 בפתגם עממי: \u0003טבא חדא פלפלתא חריפתא ממלי צני קרי\u0004 \u0005[טוב פילפל חריף אחד ממלוא הסל דלעות],\u0006 שהוא טעים יותר מכולן.","\u0003רב יוסף אמר מהכא\u0004 \u0005[מכאן]\u0006 יש ראיה שהמגילה נכתבה ברוח הקודש, שנאמר: \u0003\"וימי הפורים האלה לא יעברו מתוך היהודים\"\u0004 (אסתר ט, כח) וקביעה החלטית זו ודאי שאינה יכולה להיאמר אלא ברוח הקודש. \u0003רב נחמן בר יצחק אומר מהכא\u0004 \u0005[מכאן],\u0006 מסופו של פסוק זה, שנאמר: \u0003\"וזכרם לא יסוף מזרעם\".\u0004","שנינו במשנה, שנותנים \u0003מתנות לאביונים. תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף\u0004 בברייתא, נאמר: \u0003\"ומשלח מנות איש לרעהו\"\u0004 (אסתר ט, כב) ומדקדוק הלשון משמע: \u0003שתי מנות\u0004 אפילו \u0003לאיש אחד,\u0004 די בהן לצאת ידי חובה. ומה שנאמר \u0003\"ומתנות לאבינים\"\u0004 (אסתר ט, כב), משמע — \u0003שתי מתנות לשני בני אדם\u0004 לפחות.","מסופר: \u0003ר' יהודה נשיאה\u0004 \u0005[הנשיא]\u0006 \u0003שדר ליה\u0004 \u0005[שלח לו]\u0006 בפורים \u0003לר' אושעיא אטמא דעיגלא תלתא וגרבא דחמרא\u0004 \u0005[ירך של עגל משולש,\u0006 שהוא שלישי לאמו, \u0005וקנקן יין],\u0006 \u0003שלח ליה\u0004 \u0005[לו]\u0006 ר' אושעיא דברי תודה:"],["\u0003קיימת בנו רבינו\u0004 שתי מצוות יחד, גם \u0003\"ומשלח מנות איש לרעהו\"\u0004 וגם \u0003\"ומתנות לאבינים\",\u0004 כי הוא היה עני וזו היתה מתנה חשובה.","מסופר עוד: \u0003רבה שדר ליה\u0004 \u0005[שלח לו]\u0006 \u0003למרי בר מר\u0004 מבית ראש הגולה \u0003ביד אביי\u0004 שהיה בן אחיו ותלמידו משלוח מנות \u0003מלא טסקא דקשבא\u0004 \u0005[הסל תמרים]\u0006 \u0003ומלי כסא קמחא דאבשונא\u0004 \u0005[ומלוא כוס קמח של קלי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: השתא אמר\u0004 \u0005[עכשיו יאמר]\u0006 \u0003מרי\u0004 את הפתגם המקובל: \u0003אי חקלאה מלכא ליהוי\u0004 \u0005[אם האכר נעשה מלך]\u0006 \u0003דיקולא מצואריה לא נחית\u0004 \u0005[הסל איננו יורד מצווארו],\u0006 שהרי רבה נעשה ראש ישיבה, ובכל זאת שלח מתנות פשוטות מאוד (וטעמו של דבר — שרבה היה עני מאוד, ולא יכול לשלוח יותר).","\u0003הדר שדר ליה איהו\u0004 \u0005[חזר\u0006 ו\u0005שלח לו הוא]\u0006 מרי בר מר \u0003מלא טסקא דזנגבילא\u0004 \u0005[הסל זנגביל]\u0006 \u0003ומלא כסא דפלפלתא אריכא\u0004 \u0005[הכוס פלפל ארוך]\u0006 שהוא כמובן מתנה יקרה הרבה יותר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: השתא אמר מר\u0004 \u0005[עכשיו יאמר אדוני,\u0006 כלומר: רבה\u0005]:\u0006 \u0003אנא שדרי ליה חוליא ואיהו שדר לי חורפא\u0004 \u0005[אני שלחתי לו\u0006 דברים \u0005מתוקים והוא שולח לי\u0006 דברים \u0005חריפים].\u0006","אגב אותו ענין, על מה שאירע באותה הזדמנות \u0003אמר אביי: כי נפקי מבי מר הוה שבענא\u0004 \u0005[כאשר יצאתי מבית אדוני\u0006 רבה ללכת לבית מרי בר מר, \u0005הייתי שבע]\u0006 \u0003כי מטאי להתם\u0004 \u0005[כאשר באתי לשם]\u0006 לבית מרי בר מר \u0003קריבו\u0004 \u0005[הביאו]\u0006 \u0003לי שיתין צעי דשיתין\u0004 \u0005[שישים צלחות של שישים]\u0006 \u0003מיני קדירה\u0004 (תבשיל) \u0003ואכלי בהו שיתין פלוגי\u0004 \u0005[ואכלתי בהם שישים מנות]\u0006 \u0003ובישולא בתרייתא הוו קרו ליה\u0004 \u0005[והבישול האחרון קראו לו]\u0006 \u0003צלי קדר\u0004 והייתי עדיין כל כך רעב \u0003ובעאי למיכס צעא אבתרא\u0004 \u0005[ורציתי לכסוס,\u0006 ללעוס עוד \u0005את הצלחת אחריה].\u0006","ובהמשך לכך \u0003אמר אביי: היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים אנשים]\u0006 בפתגם ידוע: \u0003כפין עניא ולא ידע\u0004 \u0005[רעב העני ואיננו יודע],\u0006 שהרי אביי לא ידע עד כמה נשאר רעב בבית רבו. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לומר שזה מתאים לפתגם אחר: \u0003רווחא לבסימא שכיח\u0004 \u0005[הרווח ל\u0006דברים \u0005מתוקים מצוי],\u0006 כלומר, יש רווח מספיק בבטן עבור דברים מסויימים טובים.","מסופר: \u0003אביי בר אבין ור' חנינא בר אבין מחלפי סעודתייהו להדדי\u0004 \u0005[\u0006היו \u0005מחליפים\u0006 את \u0005סעודותיהם זה עם זה]\u0006 ועל ידי כך היו יוצאים ידי חובת משלוח מנות (ר\"נ).","\u0003אמר רבא: מיחייב איניש לבסומי בפוריא\u0004 \u0005[חייב אדם להשתכר בפורים]\u0006 \u0003עד\u0004 ש\u0003לא ידע\u0004 להבדיל \u0003בין ארור המן לברוך מרדכי,\u0004 כלומר, שיהא שיכור ביותר.","ומסופר: \u0003רבה ור' זירא עבדו\u0004 \u0005[עשו]\u0006 \u0003סעודת פורים בהדי הדדי\u0004 \u0005[ביחד],\u0006 \u0003איבסום\u0004 \u0005[השתכרו],\u0006 \u0003קם רבה שחטיה\u0004 \u0005[שחטו]\u0006 את \u0003ר' זירא. למחר\u0004 כשהתפקח וראה מה עשה, \u0003בעי רחמי ואחייה\u0004 \u0005[ביקש\u0006 עליו \u0005רחמים והחייהו].\u0006 \u0003ל\u0004אחר \u0003שנה אמר ליה\u0004 \u0005[לו]\u0006 רבה לר' זירא \u0003ניתי מר ונעביד\u0004 \u0005[יבוא אדוני ונעשה]\u0006 שוב \u0003סעודת פורים בהדי הדדי\u0004 \u0005[ביחד].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 איני רוצה, וזאת לאור אירועי השנה שעברה. ואף שבסופו של דבר אכן קמתי לתחייה, מכל מקום הרי \u0003לא בכל שעתא ושעתא\u0004 \u0005[שעה ושעה]\u0006 \u0003מתרחיש ניסא\u0004 \u0005[מתרחש נס]\u0006 וחושש אני שמא מה שאירע בפורים שעבר יתרחש שוב וללא תקנה.","\u0003אמר רבא: סעודת פורים שאכלה בלילה\u0004 — \u0003לא יצא ידי חובתו. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003\"ימי משתה ושמחה\"\u0004 (אסתר ט, כב) \u0003כתיב\u0004 \u0005[נאמר]\u0006 ולא לילה. מסופר: \u0003רב אשי הוה יתיב קמיה\u0004 \u0005[היה יושב לפני]\u0006 \u0003רב כהנא\u0004 רבו, \u0003נגה ולא אתו רבנן\u0004 \u0005[חשך\u0006 היום \u0005ולא באו החכמים]\u0006 שהיו רגילים לבוא ללמוד בשיעור. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003מאי טעמא לא אתו רבנן\u0004 \u0005[מה טעם לא באו חכמים היום]?\u0006 אמר לו: \u0003דלמא טרידי\u0004 \u0005[שמא טרודים\u0006 הם\u0005]\u0006 \u0003בסעודת פורים. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ו\u0004כי \u0003לא הוה\u0004 \u0005[היה]\u0006 \u0003אפשר למיכלה באורתא\u0004 \u0005[לאוכלה בערב]\u0006 בליל פורים, ולא לבטל תורה היום? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 וכי \u0003לא שמיע ליה למר הא\u0004 \u0005[שמע אדוני זה]\u0006 ש\u0003אמר רבא: סעודת פורים שאכלה בלילה לא יצא ידי חובתו? אמר ליה\u0004 \u0005[לו]:\u0006 האם \u0003אמר רבא הכי\u0004 \u0005[כך]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006 \u0003תנא מיניה ארבעין זימנין ודמי ליה כמאן דמנח בכיסיה\u0004 \u0005[שנה ממנו\u0006 וחזר על כך \u0005ארבעים פעמים עד שדומה היה לו הדבר כמי שמונח בכיסו],\u0006 שחזר על כך עד שנקלט יפה בזכרונו.","המשנה הקודמת פתחה בנוסח \"אין בין\" וסיכמה בכך הבדל שיש בין שתי הלכות, אגב זאת מביאים סדרה של הלכות בעניינים שאין להם קשר לדיני מגילה, אלא שאף הן מנוסחות באותה צורה. הראשונה בהן: \u0003אין בין יום טוב לשבת\u0004 בענין איסור מלאכה, \u0003אלא אוכל נפש בלבד.\u0004 שמותר לעשות מלאכות בישול ואפיה לצורך היום בחג, מה שאין כן בשבת.","ומדייקים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לענין\u0004 הכנת \u0003מכשירי אוכל נפש,\u0004 כלומר, מכשירים שבהם עושים אחר כך אוכל — \u0003זה וזה,\u0004 שבת ויום טוב, \u0003שוין\u0004 לאיסור.","ומעירים: אם כן \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' יהודה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין בין יום טוב לשבת אלא אוכל נפש, ר' יהודה מתיר אף\u0004 הכנת \u0003מכשירי אוכל נפש\u0004 ביום טוב.","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 דבריו של ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 — \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"אך אשר יאכל לכל נפש \u0003הוא\u0004 לבדו יעשה לכם\" (שמות יב, טז), והדיוק: \"הוא\" — \u0003ולא מכשיריו, ור' יהודה אמר:\u0004 נאמר שם \u0003\"לכם\"\u0004 משמע: \u0003לכם — לכל צורכיכם.\u0004","ומקשים: \u0003ואידך נמי\u0004 \u0005[והאחר גם כן]\u0006 חכמים, \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"לכם\"!\u0004 ומשיבים: צריך לדייק באופן אחר: \u0003לכם — ולא לגוים, לכם — ולא לכלבים,\u0004 שעבורם אסור לעשות מלאכה אף כדי להאכילם.","ושואלים: \u0003ואידך נמי\u0004 \u0005[והאחר,\u0006 ר' יהודה, \u0005גם כן],\u0006 \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"הוא\",\u0004 לשון המצמצמת את הדבר? ומשיבים: \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"הוא\" וכתיב\u0004 \u0005[ונאמר]\u0006 גם \u0003\"לכם\",\u0004 וצריך לפשר בין שני הכתובים; \u0003כאן\u0004 מדובר \u0003במכשירים\u0004 של אוכל נפש \u0003שאפשר לעשותן מערב יום טוב\u0004 שאותם אסור לעשות ביום טוב עצמו, \u0003כאן — במכשירין שאי אפשר לעשותן מערב יום טוב\u0004 והותרה עשייתם ביום טוב עצמו.","\u0003אין בין שבת ליום הכפורים\u0004 הבדל בענין איסורי מלאכה בהם, \u0003אלא שזה,\u0004 שבת, \u0003זדונו\u0004 (מי שעובר עליו בזדון) והעידו עליו עדים — נענש \u0003בידי אדם\u0004 בסקילה, \u0003וזה,\u0004 יום הכיפורים, \u0003זדונו בכרת.\u0004","ומעירים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לענין תשלומין זה וזה שוין.\u0004 כלומר: ההלכה היא, שאם עשה אדם מלאכה בשבת וגרם אגב כך נזק לרכושו של אחר, כיון שעבירה זו גוררת אחריה עונש מיתה — הרי הוא פטור מתשלום הנזקים מפני שכבר התחייב בעונש החמור של מיתה, וממשנתנו נראה שכן הדין גם אם עשה זאת ביום הכיפורים.","ומעירים: \u0003מני מתניתין\u0004 \u0005[\u0006כשיטת \u0005מי היא משנתנו]?\u0006 כשיטת \u0003ר' נחוניא בן הקנה היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' נחוניא בן הקנה היה עושה את יום הכפורים כשבת לתשלומין, מה שבת\u0004 כיון ש\u0003מתחייב בנפשו\u0004 הריהו \u0003פטור מן התשלומין — אף\u0004 ב\u0003יום הכפורים\u0004 כיון ש\u0003מתחייב בנפשו\u0004 לכן הריהו \u0003פטור מן התשלומין.\u0004","\u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]:\u0006 אף שחייבי כריתות אינם לוקים (אף שגם הם כשאר חייבי מלקות אחרים עברו על מצות \"לא תעשה\"), לפי שאין די להם בעונש זה, מכל מקום \u0003כל חייבי כריתות שלקו\u0004 (שקיבלו מלקות בבית דין), \u0003נפטרו\u0004 על ידי כך \u0003מידי\u0004 עונש \u0003כריתתן\u0004 בידי שמים. \u0003שנאמר\u0004 על האיש החייב מלקות: \u0003\"ונקלה אחיך לעיניך\"\u0004 (דברים כה, ג) ללמדנו: \u0003כיון שלקה — הרי הוא כאחיך,\u0004 ונמחלו עוונותיו. אלה \u0003דברי ר' חנניה בן גמליאל. אמר ר' יוחנן: חלוקין עליו חביריו על ר' חנניה בן גמליאל\u0004 ואין זו דעת הכל.","\u0003אמר רבא: אמרי בי\u0004 \u0005[אומרים\u0006 חכמים \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003רב, תנינא\u0004 \u0005[שנינו]:\u0006 \u0003אין בין יום הכפורים לשבת אלא שזה,\u0004 שבת, \u0003זדונו בידי אדם וזה,\u0004 יום הכיפורים \u0003זדונו בהיכרת. ואם איתא\u0004 \u0005[יש]\u0006 מקום לדברי ר' חנניה בן גמליאל — אם כן \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 גם שבת וגם יום הכיפורים, שעונשו כרת, הרי עונשם \u0003בידי אדם היא!\u0004","\u0003אמר רב נחמן:\u0004 אין מכאן ראיה, שהרי אפשר לומר כי \u0003הא מני\u0004 \u0005[\u0006משנתנו \u0005זו כ\u0006שיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' יצחק היא\u0004 ש\u0003אמר\u0004 כלל: \u0003מלקות בחייבי כריתות ליכא\u0004 \u0005[אין\u0006 בהם\u0005].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יצחק אומר: חייבי כריתות בכלל\u0004 חייבי מלקות \u0003היו, ולמה יצאת כרת באחותו\u0004 שבנוסף למה שנאמר חיוב כרת לגבי כל המקרים המפורשים בפרשה (ויקרא פרק כ), נאמר שוב כרת באחותו — ללמדנו על ידי הדגשה יתירה זו \u0003לדונה בכרת ולא במלקות,\u0004 ומכאן אנחנו למדים שבמקום שיש חיוב כרת אין עוד מלקות.","\u0003רב אשי אמר:\u0004 אין זו הוכחה, \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו היא כדעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 שיש חיוב מלקות בכרת, ובכל זאת: \u0003זה\u0004 שבת — \u0003עיקר\u0004 העונש על \u0003זדונו בידי אדם, וזה\u0004 יום הכיפורים, \u0003עיקר\u0004 העונש על \u0003זדונו\u0004 הוא \u0003בהיכרת,\u0004 אבל אם לקה — נפטר מידי כריתותו."],["\u0003אין בין המודר הנאה מחבירו\u0004 (שנדר שלא יהנה מחבירו כלל) \u0003למודר ממנו מאכל\u0004 (שנדר רק שלא יהנה מכל אוכל של חבירו), \u0003אלא\u0004 לענין \u0003דריסת הרגל,\u0004 שהמודר הנאה אסור אף לדרוך בחצירו של האחר, \u0003ו\u0004כן לעניין לשאול ממנו \u0003כלים שאין עושין בהן אוכל נפש\u0004 אלא משמשים לצורך אחר.","ומדקדקים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לענין כלים שעושין בהן אוכל נפש\u0004 — \u0003זה וזה, ו\u0004המודר הנאה המודר מאכל, \u0003שוין\u0004 באיסור הנאה מהם.","נאמר במשנה שהמודר הנאה אסור ב\u0003דריסת הרגל\u0004 אצל חבירו, ותוהים: מה הנאה היא זו? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא קפדי אינשי\u0004 \u0005[מקפידים אנשים]\u0006 על דברים כגון דריכת אדם בחצירו של חבירו! \u0003אמר רבא: הא מני\u0004 \u0005[זו\u0006 משנתנו, כשיטת \u0005מי היא] —\u0006 כשיטת \u0003ר' אליעזר,\u0004 ש\u0003אמר: ויתור אסור במודר הנאה,\u0004 כלומר, אפילו דברים שאנשים רגילים לוותר עליהם זה לזה ואינם מקפידים בהם, אבל מי שהדיר עצמו מחבירו — אסור לו ליהנות אף מדבר כזה.","\u0003אין\u0004 הבדל \u0003בין נדרים לנדבות\u0004 שנדרו ונדבו למקדש \u0003אלא\u0004 בזה: \u0003שהנדרים חייב באחריותן\u0004 שאם אבדו או מתו צריך להביא אחרים במקומם \u0003ונדבות אינו חייב באחריותן,\u0004 שאם אבדו או מתו אינו חייב להביא אחרות תחתיהן.","ומדייקים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לענין\u0004 איסור \u0003\"בל תאחר\"\u0004 שעובר אם לא הביא אותם בזמנם — \u0003זה וזה שוין.\u0004","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003אי זהו נדר? האומר: \"הרי עלי עולה\"\u0004 או קרבן נדבה אחר. \u0003איזו היא נדבה? האומר\u0004 על בהמה מסויימת: \u0003\"הרי זו עולה\", ומה\u0004 ההבדל \u0003בין נדרים לנדבות? נדרים\u0004 אם \u0003מתו\u0004 הבהמות \u0003או נגנבו או אבדו — חייב באחריותן,\u0004 שהרי התחייב באופן כללי להביא קרבן מסויים וכל עוד לא נתקיימו דבריו עדיין לא נפטר מחובתו, ואילו \u0003נדבות\u0004 אם \u0003מתו או נגנבו או אבדו\u0004 — \u0003אינו חייב באחריותן.\u0004","ושואלים: \u0003מנהני מילי\u0004 \u0005[מניין דברים אלה]?\u0006 ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים],\u0006 נאמר בקרבן העולה: \u0003\"ונרצה לו לכפר עליו\"\u0004 (ויקרא א, ד), \u0003ר' שמעון אומר:\u0004 מלשון פסוק זה למדים כי \u0003את שעליו,\u0004 כלומר, שההתחייבות שקיבל היא עליו — \u0003חייב באחריותו, ואת שאינו עליו,\u0004 אלא על בהמה מסויימת שתהיה היא לקרבן \u0003— אינו חייב באחריותו.\u0004","ושואלים: \u0003מאי משמע\u0004 \u0005[מהי משמעותו],\u0006 מה הקשר בין לשון הכתוב ודברי הלכה אלו? \u0003אמר ר' יצחק בר אבדימי: כיון\u0004 ש\u0003אמר \"עלי\" כמאן דטעין אכתפיה דמי\u0004 \u0005[כמי שטוען על כתפו הוא נחשב],\u0006 שלשון \"עלי\" משמעה נטילת האחריות על עצמו, שחייב עצמו בהבאת קרבן, והתחייבות מעין זו אינה תלויה בבהמה מסויימת דווקא.","\u0003אין\u0004 הבדל \u0003בין זב הרואה שתי ראיות,\u0004 זה שיצאה ממנו זיבה פעמיים \u0003לרואה שלש,\u0004 שיצאה ממנו זיבה שלוש פעמים, \u0003אלא\u0004 שהזב בעל שלוש ראיות חייב להביא \u0003קרבן\u0004 לאחר שיתרפא כדי להשלים את תהליך הטהרה.","ומדייקים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לענין משכב ומושב,\u0004 שהזב מטמא את מה שהוא שוכב או יושב עליו, \u0003ו\u0004כן לענין \u0003ספירת שבעה,\u0004 שלאחר שפסקה הזיבה צריך לספור שבעה ימים שיהיו נקיים מזיבה כדי שיוכל לטבול ולהיטהר — \u0003זה וזה,\u0004 הרואה שתים והרואה שלוש, \u0003שוין.\u0004","ושואלים: \u0003מנהני מילי\u0004 \u0005[מניין הדברים הללו]\u0006 לגבי שתים ושלוש ראיות זיבה וההבדל ביניהם? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003ר' סימאי אומר: מנה הכתוב שתים;\u0004 \"איש איש כי יהיה זב מבשרו זובו טמא הוא\" (ויקרא טו, ב), שנזכרו בכתוב זה שתי זיבות \u0003וקראו\u0004 לזב \u0003\"טמא\",\u0004 מנה הכתוב \u0003שלש\u0004 פעמים לשון זיבה; \"וזאת תהיה טומאתו בזובו רר בשרו את זובו או החתים בשרו מזובו טומאתו היא\" (ויקרא טו, ג) \u0003וקראו\u0004 גם כן \u0003טמא, הא כיצד?\u0004 שלכאורה אם טמא כבר בשתים, לשם מה שלוש? אלא ללמד: \u0003שתים ל\u0004ענין \u0003טומאה\u0004 בלבד \u0003ושלש\u0004 כדי \u0003ל\u0004הוסיף גם \u0003קרבן.\u0004","ומקשים: \u0003ואימר\u0004 \u0005[ואמור]\u0006 להיפך: \u0003שתים לטומאה ולא לקרבן, שלש לקרבן ולא לטומאה!\u0004 ודוחים: הדבר לא יתכן, \u0003אמרת\u0004 \u0005[\u0006הרי \u0005אומר אתה]\u0006 \u0003עד שלא ראה שלש\u0004 כבר \u0003ראה שתים\u0004 וכיוון שכך תמיד יהיה טמא, אף בשלוש.","אלא מקשים מצד אחר: \u0003ואימר\u0004 \u0005[ואמור]\u0006 כך: \u0003שתים לקרבן ולא לטומאה, שלש\u0004 לקרבן ו\u0003אף לטומאה!\u0004 ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כך, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב: \u0003\"וכפר עליו הכהן לפני ה' מזובו\"\u0004 (ויקרא טו, טו), ה־מ' שנוסף למלה \"זובו\" בא להשמיענו אף על מקצת זובו; \u0003מקצת זבין מביאין קרבן ומקצת זבין אין מביאין קרבן. הא כיצד?\u0004 אם \u0003ראה שלש\u0004 ראיות — \u0003מביא, שתים — אינו מביא.\u0004","ושואלים בברייתא: \u0003או אינו אלא ראה שתים מביא, ראה שלש אינו מביא, אמרת\u0004 שאין הדבר אפשרי שכן \u0003עד שלא ראה שלש\u0004 כבר \u0003ראה שתים,\u0004","ומעירים: \u0003ואיצטריך\u0004 \u0005[והוצרכה]\u0006 הראיה של \u0003ר' סימאי ואצטריך\u0004 \u0005[והוצרכה]\u0006 הראיה ממה שנאמר \u0003\"מזובו\", דאי\u0004 \u0005[שאם]\u0006 \u0003מ\u0004זו של \u0003ר' סימאי\u0004 בלבד \u0003הוה אמינא כי קושיין\u0004 \u0005[הייתי אומר כמו הקושיה שלנו]\u0006 שהקשינו על כך, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003\"מזובו\". ואי\u0004 \u0005[ואם]\u0006 היה אומר רק \u0003\"מזובו\" — לא ידענא\u0004 \u0005[הייתי יודע]\u0006 \u0003כמה ראיות,\u0004 אלא הייתי יודע רק שחלק מהזבים אינם מביאים קרבן, על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 את המקור שאמר \u0003ר' סימאי.\u0004","ושואלים: \u0003והשתא דאמרת\u0004 \u0005[ועכשיו שאומר אתה]\u0006 שהביטוי \u0003\"מזובו\"\u0004 בא למעט ולשם \u0003דרשא,\u0004 אם כן מה שנאמר \u0003\"וכי יטהר הזב מזובו\u0004 וספר לו שבעת ימים לטהרתו\u0003\"\u0004 (ויקרא טו, יג) \u0003מאי דרשת ביה\u0004 \u0005[מה דורש אתה בו]?\u0006","ומשיבים: הפסוק \u0003ההוא מיבעי ליה לכדתניא\u0004 \u0005[נצרך לו לכפי ששנינו\u0006 בברייתא\u0005],\u0006 על הפסוק \u0003\"וכי יטהר הזב\u0004 מזובו\", שיש לפרשו \u0003לכשיפסוק מזובו, \"מזובו\"\u0004 למעט משמע: \u0003ולא מזובו ונגעו,\u0004 שאם היה גם זב וגם מצורע, איננו צריך להימנע מלספור שבעה נקיים, עד שיטהר גם מן הצרעת, אלא יספור לזובו ולכשיטהר מצרעתו יטבול לשניהם. ומה שנאמר \u0003\"מזובו וספר\"\u0004 (ויקרא טו, יג) — \u0003לימד על זב בעל שתי ראיות שטעון ספירת שבעה.\u0004","ואומרים: \u0003והלא דין הוא\u0004 שאפשר ללמוד את הדבר, מקל וחומר, ולכאורה אינו צריך ללימוד מיוחד; שכן \u0003אם מטמא משכב ומושב\u0004 בזמן שראה שתי ראיות \u0003לא יהא טעון ספירת שבעה\u0004 כדי להיטהר?"],["ומשיבים: \u0003שומרת יום כנגד יום\u0004 אשה שזב ממנה דם בתוך יום או יומיים שלא בעת וסתה, שהיא ממתינה (שומרת) יום אחר לאחר שראתה דם, ואם לא ראתה שוב — הריהי נטהרת לגמרי, \u0003תוכיח, שמטמאה משכב ומושב ו\u0004בכל זאת \u0003אינה טעונה ספירת שבעה.\u0004","\u0003ואף אתה אל תתמה על זה, ש\u0004הזב, \u0003אף על פי שמטמא משכב ומושב לא יהא טעון ספירת שבעה\u0004 כדין שומרת יום כנגד יום, \u0003תלמוד לומר: \"מזובו וספר\"\u0004 (ויקרא טו, יג) במובן: \u0003מקצת זובו וספר\u0004 — \u0003לימד על זב בעל שתי ראיות\u0004 שאף שהוא רק זב במקצת, \u0003שטעון ספירת שבעה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: מאי שנא האי\u0004 \u0005[במה שונה\u0006 פסוק \u0005זה]\u0006 שנאמר בו \u0003\"מזובו\" דמרבי ביה\u0004 \u0005[שמרבה בו]\u0006 ומוסיף על ידו לספירת שבעה אף את ה\u0003זב בעל שתי ראיות, ומאי שנא האי\u0004 \u0005[ובמה שונה\u0006 פסוק \u0005זה]\u0006 \u0003\"מזובו\"\u0004 שהובא מקודם \u0003דממעט ביה\u0004 \u0005[שממעט בו]\u0006 \u0003זב בעל שתי ראיות\u0004 מחובת הבאת קרבן? שאם הביטוי \"מזובו\" הוא ביטוי של מיעוט, מדוע במקום אחר אנחנו רואים אותו כריבוי?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003אי סלקא דעתך האי למעוטי הוא דאתא\u0004 \u0005[אם עולה על דעתך\u0006 ש\"מזובו\" \u0005זה למעט הוא בא]\u0006 — \u0003לישתוק קרא מיניה\u0004 \u0005[שישתוק הכתוב ממנו]\u0006 ולא יזכיר אותו כלל ולא יעלה על דעתנו לכלול כאן גם זב בעל שתי ראיות, \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003אתיא מדינא\u0004 \u0005[יבוא\u0006 הדבר \u0005מקל וחומר]\u0006 בלא כתוב מפורש, הרי \u0003שומרת יום כנגד יום תוכיח\u0004 שאין ללמוד מדין טומאה חמורה לחובת ספירת שבעה.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003האי מיבעי ליה\u0004 \u0005[זה נחוץ לו]\u0006 למיעוט אחר, ללמוד \u0003מזובו ולא מנגעו, אם כן ליכתב קרא\u0004 \u0005[שיכתוב הכתוב]\u0006 רק \u0003\"וכי יטהר הזב\" ולישתוק\u0004 \u0005[וישתוק],\u0006 ונלמד מהפסוק שכשנטהר מהזיבה סופר ואפילו יש לו נגע צרעת בזמן הספירה, ואם כן \u0003\"מזובו\" למה לי?\u0004 אלא ודאי הוא ריבוי ולא בענין נגעים אלא \u0003לימד על זב בעל שתי ראיות שטעון ספירת שבעה.\u0004","\u0003אין בין מצורע מוסגר\u0004 שהוא מצורע שהכהן אינו יודע עדיין אם טמא הוא, אלא מסגירו שבוע או שבועיים וממתין אם יתגלו בו סימני טומאה או טהרה, \u0003למצורע מוחלט,\u0004 זה שהכהן טימא אותו לחלוטין, ואין לו תקנה עד שיתרפא, \u0003אלא פריעה\u0004 של הראש \u0003ופרימה\u0004 של בגדים, שהמוחלט חייב בהם ולא המוסגר.","וכן \u0003אין בין\u0004 מצורע ש\u0003טהור מתוך הסגר\u0004 שהוסגר ואחר כך נתגלה שהוא טהור, \u0003לטהור מתוך החלט אלא תגלחת וצפרים,\u0004 שהמוחלט צריך לגלח את כל שערו ולהביא שתי צפרים לטהרתו.","לענין ההבדל בין מצורע מוסגר למצורע מוחלט מדייקים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לענין שילוח\u0004 שחייב לצאת משלושה מחנות (כלומר, מחוץ לעיר) \u0003ו\u0004לכל דיני \u0003טומאה\u0004 של המצורע, \u0003זה וזה\u0004 המוסגר והמוחלט \u0003שוין.\u0004","ושואלים: \u0003מנהני מילי\u0004 \u0005[מניין הדברים הללו],\u0006 מה מקורם במקרא? \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רב שמואל בר יצחק\u0004 ברייתא \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב הונא:\u0004 נאמר במצורע שנטהר מתוך הסגר: \u0003\"וטהרו הכהן מספחת היא וכבס בגדיו וטהר\"\u0004 (ויקרא יג, ו), ולשון \"טהר\" אינה לשון עתיד אלא לשון הווה, ללמד ש\u0003טהור מפריעה ופרימה דמעיקרא\u0004 \u0005[שמתחילה],\u0006 לומר לנו שמתחילה לא היה צריך לפרוע ולפרום, שהביטוי \"וטהר\" משמעו: התברר שהוא טהור, שרק הטמא המוחלט פורע ופורם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אלא מעתה\u0004 שאתה מפרש כך את הלשון \"וטהר\", \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003זב דכתיב\u0004 \u0005[שנאמר\u0006 בו\u0005]\u0006 \u0003\"וכבס בגדיו\u0004 ורחץ בשרו במים חיים \u0003וטהר\"\u0004 (ויקרא טו, יג), \u0003התם מאי\u0004 \u0005[שם מה]\u0006 ענין \u0003\"וטהר\" מעיקרא איכא\u0004 \u0005[מתחילה יש\u0006 בו\u0005]?\u0006 שהרי לכל דבר הוא טמא!","\u0003אלא\u0004 על כרחך \"וטהר\" משמעו: \u0003טהור השתא\u0004 \u0005[עכשיו]\u0006 \u0003מלטמא כלי חרס בהיסט.\u0004 שזב המזיז (מסיט) כל כלי חרס אף שכלי חרס אינו מיטמא במגע מגבו, וגם אם הכלי הזה קטן עד שאינו יכול להכניס אפילו אצבע בתוכו, מכל מקום, דין מיוחד הוא בטומאת הזב שמטמא בהיסט, ובא הכתוב ללמדנו שכיוון שנטהר הזב שוב איננו מטמא, והחידוש שנזכר \u0003אף על גב דהדר חזי\u0004 \u0005[אף על פי ש\u0006הוא \u0005חוזר ורואה\u0006 שוב זיבה\u0005]\u0006 \u0003לא מטמא למפרע\u0004 ואין אומרים שזיבה זו מצטרפת למה שהיה קודם לכן וייחשב כאילו היה טמא כל הזמן אף אחר שטבל, אלא כיון שספר וטבל, שוב אינו מטמא למפרע כתחילת זיבה חדשה.","\u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 תפרש שמה שנאמר במצורע \"טהר\" כוונתו \u0003טהור השתא\u0004 \u0005[עכשיו]\u0006 מוסגר זה \u0003מלטמא\u0004 את הבית ואת האדם או הכלים שבתוכו \u0003בביאה\u0004 לתוך הבית \u0003למפרע\u0004 כדין מצורע מוחלט, שאם ייראו סימני טומאה במצורע שהוסגר וטוהר, אין אומרים שבעצם היה מצורע משעה שהוסגר בראשונה ומטמא בביאה, אלא כיון שנטהר עכשיו — טהור הוא לגמרי. ואם כן הראיה שהביא רב שמואל בר יצחק אינה ראיה.","\u0003אלא אמר רבא: מהכא\u0004 \u0005[מכאן]\u0006 יש להביא ראיה: נאמר \u0003\"והצרוע אשר בו הנגע\u0004 בגדיו יהיו פרומים וראשו יהיה פרוע\u0003\"\u0004 (ויקרא יג, מה) ללמדנו כי דווקא \u0003מי שצרעתו תלויה בגופו\u0004 (שיש \"בו\" נגע צרעת), — הוא שיש בו דין פריעה ופרימה, \u0003יצא זה\u0004 המוסגר \u0003שאין צרעתו תלויה בגופו אלא בימים\u0004 שהרי בהכרח עליו להמתין שבעה ימים, ואין הדבר תלוי בגופו בלבד.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה\u0004 אם כך אתה למד הרי כתוב גם \u0003\"כל ימי אשר הנגע בו יטמא\"\u0004 (ויקרא יג, מו) ונפרש באותו אופן: \u0003מי שצרעתו תלויה בגופו הוא\u0004 ש\u0003טעון שילוח\u0004 מחוץ למחנה, \u0003ו\u0004אולם זה \u0003שאין צרעתו תלויה בגופו — אין טעון שילוח,\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הכי נמי\u0004 \u0005[כך\u0006 הוא \u0005גם כן],\u0006 \u0003והא קתני\u0004 \u0005[והרי שנה\u0006 במשנתנו\u0005]:\u0006 \u0003אין בין מצורע מוסגר למצורע מוחלט אלא פריעה ופרימה, הא\u0004 \u0005[הרי]\u0006 \u0003לענין שילוח ולטמויי\u0004 \u0005[ולטמא]\u0006 \u0003בביאה זה וזה שוין!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: שם יש מקור אחר, כי יכול היה לכתוב כך \u0003\"ימי\u0004 אשר הנגע בו \u0003\"\u0004ונאמר \u0003\"כל ימי\",\u0004 ו\"כל\" זה שנאמר, בא להוסיף ו\u0003לרבות מצורע מוסגר ל\u0004ענין \u0003שילוח,\u0004 שגם הוא, כמו המוחלט, חייב שילוח.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שאתה למד ריבוי זה למוסגר, \u0003תגלחת וצפרים מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 חייב בהם המוסגר? \u0003דקתני\u0004 \u0005[ש\u0006הרי \u0005שנה\u0006 בהמשך המשנה\u0005]\u0006 \u0003אין בין טהור מתוך הסגר לטהור מתוך החלט אלא תגלחת וצפרים!\u0004","\u0003אמר אביי\u0004 על כך: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ויצא הכהן אל מחוץ למחנה\u0004 וראה הכהן \u0003והנה נרפא נגע הצרעת\u0004 מן הצרוע\u0003\"\u0004 (ויקרא יד, ג) ואז נעשה סדר הטהרה בתגלחת וצפרים, ללמד שמדובר דווקא ב\u0003מי שצרעתו תלויה ברפואות\u0004 (שתקנתו תלויה בריפוי מן הנגע) \u0003יצא זה\u0004 המוסגר \u0003שאין צרעתו תלויה ברפואות אלא בימים,\u0004 שבכל מקרה חייב להמתין שבעת ימי ההסגר עד שייטהר.","\u0003אין\u0004 הבדל \u0003בין ספרים\u0004 ספרי תורה \u0003לתפלין ומזוזות\u0004 בדרך כתיבתם, \u0003אלא שהספרים נכתבין בכל לשון, ותפלין ומזוזות אינן נכתבות אלא אשורית,\u0004 כלומר, בלשון הקודש ובכתב עברי.","\u0003רבן שמעון בן גמליאל אומר: אף בספרים לא התירו שיכתבו\u0004 בשפה אחרת פרט ללשון הקודש \u0003אלא יוונית\u0004 בלבד, וספרי תורה שנכתבו בלשון אחרת אין בהם קדושת ספרי תורה.","ומעירים: \u0003הא\u0004 \u0005[הרי]\u0006 לענין \u0003לתופרן בגידין,\u0004 שכאשר תופרים ומחברים את יריעות הקלף, בין ספרים ובין תפילין, צריכים לתפור אותם בגידי בהמה ולא בחומר אחר, ולענין זה הם שוים, וכן \u0003ולטמא את הידים\u0004 לפי הגזירה שכתבי הקודש מטמאים את ידי הנוגעים בהם, \u0003זה וזה שוין.\u0004","שנינו במשנה שה\u0003ספרים נכתבים בכל לשון. ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005],\u0006 ממה ששנינו: \u0003מקרא\u0004 (ספר תורה) \u0003שכתבו תרגום,\u0004 או \u0003תרגום\u0004 (דבר הכתוב בתורה בארמית) \u0003שכתבו מקרא\u0004 (בלשון הקודש), או ספר שכתוב ב\u0003כתב עברי\u0004 עתיק ולא בכתב אשורי־מרובע — \u0003אינו מטמא את הידים,\u0004 שאין בו קדושת כתבי הקודש \u0003עד שיכתבנו בכתב אשורית, על הספר\u0004 (על הקלף הגלול), \u0003בדיו.\u0004 הרי שספר הכתוב בלשון שאינה לשון הקודש או בשינוי אחר אינו מקודש, והרי סתירה למה שאמרנו שהספרים נכתבים בכל לשון?","\u0003אמר רבא: לא קשיא\u0004 \u0005[אינו קשה];\u0006"],["\u0003כאן\u0004 שהתיר בכל לשון, הרי זה כשכתב אכן בלשון אחרת, אולם \u0003בגופן\u0004 באותיות הכתיבה \u0003שלנו,\u0004 באותיות עבריות, \u0003כאן\u0004 שאסרו מדובר שלא רק כתב בלשונם אלא אף \u0003בגופן שלהן,\u0004 ששינה את האותיות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: במאי אוקימתא לההיא\u0004 \u0005[במה העמדת,\u0006 הסברת, \u0005את ההיא]?\u0006 \u0003בגופן שלהן,\u0004 אם כן \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 \u0003מקרא שכתבו תרגום ותרגום שכתבו מקרא\u0004 אינו עוד ספר קודש? \u0003אפילו מקרא שכתבו מקרא ותרגום שכתבו תרגום נמי\u0004 \u0005[גם כן]\u0006 פסול, אם כתב בכתב אחר. \u0003דהא קתני\u0004 \u0005[שהרי שנה\u0006 שם\u0005]:\u0006 \u0003עד שיכתבנו אשורית על ספר בדיו!\u0004","\u0003אלא\u0004 עלינו לחזור מן התירוץ הקודם, ולהסביר באופן אחר: \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 וכך יש לומר: \u0003הא\u0004 \u0005[זו\u0006 המשנה\u0005]\u0006 היא דעת \u0003רבנן\u0004 שהתירו לכתוב בכל לשון, \u0003והא\u0004 \u0005[וזו\u0006 הברייתא\u0005]\u0006 כדעת \u0003רבן שמעון בן גמליאל.\u0004","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 דעת הברייתא כשיטת \u0003רבן שמעון בן גמליאל הא איכא\u0004 \u0005[הרי יש]\u0006 \u0003יונית\u0004 שהוא מתיר, ולא רק אשורית, וכפי ששנינו במשנה! \u0003אלא\u0004 יש לומר \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003כאן\u0004 במשנה מדובר \u0003בספרים\u0004 שמותר לכותבם אף בלשון אחרת, אבל \u0003כאן\u0004 בברייתא שאסרה לשנות את הלשון ואת הכתב מדובר \u0003בתפלין ומזוזות.\u0004","ומקשים שוב: \u0003תפלין ומזוזות מאי טעמא\u0004 \u0005[מה טעם]\u0006 אסור לשנות בהם? \u0003משום דכתיב בהו\u0004 \u0005[שנאמר בהם]:\u0006 \u0003\"והיו\"\u0004 (דברים ו, ו) לומר: \u0003בהוייתן יהו\u0004 ולא ישנה אותם כלל, ואם כן, כשאנו מפרשים שמשנתנו מדברת בתפילין ומזוזות, הלא בתפילין ומזוזות \u0003מאי תרגום שכתבו מקרא איכא\u0004 \u0005[יש\u0006 בהם\u0005]?\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 ב\u0003תורה איכא\u0004 \u0005[יש\u0006 בה\u0005]\u0006 תרגום שכתוב \u0003\"יגר שהדותא\"\u0004 (בראשית לא, מז) ואם שינה וכתב זאת בעברית ולא בארמית — פסול, \u0003אלא הכא\u0004 \u0005[כאן]\u0006 בתפילין ומזוזות \u0003מאי\u0004 \u0005[מה]\u0006 \u0003תרגום איכא\u0004 \u0005[יש]\u0006 במקור שיכול לכתוב אותו כמקרא?","\u0003אלא\u0004 יש לדחות אף פירוש זה, ולומר \u0003לא קשיא\u0004 \u0005[אינו קשה];\u0006 \u0003כאן\u0004 במשנה המתירה, מדובר \u0003במגילה, כאן\u0004 בברייתא האוסרת מדובר \u0003בספרים\u0004 אחרים, וגם על כך מקשים: \u0003מגילה מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההיתר, משום \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה: \"ככתבם וכלשונם\"\u0004 (אסתר ח, ט) ולא בשינוי. ואם כך, \u0003מאי\u0004 \u0005[מה]\u0006 \u0003תרגום שכתבו מקרא איכא\u0004 \u0005[יש]\u0006 במגילה? שהרי לכאורה היא כתובה כולה לשון הקודש!","\u0003אמר רב פפא:\u0004 נאמר \u0003\"ונשמע פתגם המלך\"\u0004 (אסתר א, כ), ו\"פתגם\" הוא בעצם מלה ארמית. \u0003רב נחמן בר יצחק אמר,\u0004 נאמר: \u0003\"וכל הנשים יתנו יקר לבעליהן\"\u0004 (אסתר א, כ) — \"יקר\" היא מלה ארמית, שמשמעה כבוד.","\u0003רב אשי אמר\u0004 הסבר אחר: \u0003כי תניא\u0004 \u0005[כאשר שנויה\u0006 הברייתא\u0005]\u0006 \u0003ההיא,\u0004 הרי זה \u0003בשאר\u0004 ה\u0003ספרים,\u0004 בנביאים וכתובים, ולא בספר תורה, \u0003ו\u0004שיטת \u0003ר' יהודה היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003תפלין ומזוזות אין נכתבין אלא אשורית, ורבותינו\u0004 (רבן שמעון בן גמליאל) \u0003התירו\u0004 שייכתבו אף \u0003יונית.\u0004 ותוהים: כיצד התירו?","\u0003והכתיב\u0004 \u0005[והרי נאמר\u0006 בהם\u0005]\u0006 \u0003\"והיו\"\u0004 ולמדנו מזה שבהווייתם יהיו בלא שום שינוי! \u0003אלא אימא\u0004 \u0005[אמור\u0006 כך\u0005]:\u0006 \u0003ספרים נכתבים בכל לשון, ורבותינו התירו יונית.\u0004 ותוהים שוב על הסגנון: \u0003התירו?! מכלל\u0004 \u0005[מכאן]\u0006 שה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003אסר\u0004 — והרי דווקא הוא התיר בכל לשון!","\u0003אלא אימא\u0004 \u0005[אמור]\u0006 בלשון זו: \u0003רבותינו לא התירו שיכתבו אלא יונית. ותניא\u0004 \u0005[ושנינו]\u0006 \u0003אמר ר' יהודה: אף כשהתירו רבותינו יונית — לא התירו אלא בספר תורה\u0004 ולא בשאר ספרים,","\u0003ומשום מעשה\u0004 שהיה ב\u0003תלמי המלך\u0004 שכיוון שהיה סיוע ניסי בדבר אנו רואים בכך הסכמה משמים. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מעשה בתלמי המלך\u0004 מלך מצרים \u0003שכינס שבעים ושנים זקנים\u0004 מחכמי ישראל \u0003והכניסן בשבעים ושנים בתים\u0004 נפרדים \u0003ולא גילה להם\u0004 תחילה \u0003על מה כינסן,\u0004 שלא יטלו עצה ביניהם קודם. \u0003ונכנס אצל כל אחד ואחד\u0004 מהם, \u0003ואמר להם: כתבו לי,\u0004 כלומר, תרגמו לי \u0003תורת משה רבכם. נתן הקדוש ברוך הוא בלב כל אחד ואחד עצה\u0004 ותבונה \u0003והסכימו כולן לדעת אחת\u0004 ולא רק שתירגמו כראוי, אלא גם שינו אותם דברים עצמם מסיבות שונות.","למשל: \u0003וכתבו לו \"אלהים ברא בראשית\"\u0004 ולא ככתוב \"בראשית ברא אלהים\" (בראשית א, א), וזאת כדי שלא יטעו ויאמרו ששתי רשויות הם; הראשון ששמו \"בראשית\", ברא את השני. ובמקום הכתוב \"נעשה אדם בצלמנו כדמותנו\" (בראשית א, כו), שאפשר היה לטעות וללמוד מכאן שיש ריבוי רשויות ושיש לה' דמות הגוף — כתבו לו \u0003\"אעשה אדם בצלם ובדמות\";\u0004 ובמקום \"ויכל אלהים ביום השביעי מלאכתו\" (בראשית ב, ב), שהיה מקום לטעות ולפרש שמקצת המלאכה נגמרה בשבת עצמה, כתבו","\u0003\"ויכל ביום הששי וישבות ביום השביעי\".\u0004 וכן כתבו \u0003\"זכר ונקבה בראו\", ולא כתבו\u0004 כמו שכתוב \u0003\"\u0004זכר ונקבה \u0003בראם\"\u0004 (בראשית ה, ב), וזאת כדי למנוע סתירה בין כתוב לכתוב, שפעם נאמר שנברא יחיד ופעם נאמר שנבראו שנים.","ובמקום \"הבה נרדה ונבלה שם שפתם\" (בראשית יא, ז), שיש חשש של הבנה שיש ריבוי רשויות, כתבו לו בלשון יחיד \u0003\"הבה ארדה ואבלה שם שפתם\".\u0004 ובמקום הכתוב \u0003\"\u0004ותצחק שרה בקרבה\u0003\"\u0004 (בראשית יח, יב) שינו וכתבו \u0003\"ותצחק שרה בקרוביה\",\u0004 כדי לפתור על ידי כך את השאלה, שהרי גם אברהם צחק, ומדוע לא גער ה' בו, ולכן פירשו שהיא צחקה בפומבי בין קרוביה.","וכן את הכתוב \"כי באפם הרגו איש וברצונם עקרו שור\" (בראשית מט, ו), תיקנו לכתוב \u0003\"כי באפם הרגו שור וברצונם עקרו אבוס\",\u0004 שלא יאמרו שאבותינו היו רוצחי נפשות. ואת הפסוק \"ויקח משה את אשתו ואת בניו וירכיבם על החמור\" (שמות ד, כ) שינו, כדי שלא יהיה זילזול במשה שלא מצא לו אלא חמור, ולכן תירגמו: \u0003\"ויקח משה את אשתו ואת בניו וירכבם על נושא בני אדם\",\u0004 כלומר, על בהמת משא, ולא פירשו חמור.","וכן את הפסוק: \"ומושב בני ישראל אשר ישבו במצרים שלושים שנה וארבע מאות שנה\" (שמות יב, מ) שלפי החשבון לא הגיע מספר השנים המדוייק של ישיבת בני ישראל בארץ מצרים לארבע מאות ושלושים שנה, והמספר הזה כולל את כל השנים מיום שנגזרה הגזירה בברית בין הבתרים עד יום צאתם משם, ולכן שינו וכתבו \u0003\"ומושב בני ישראל אשר ישבו במצרים ובשאר ארצות ארבע מאות שנה\".\u0004 ואת הפסוק: \"וישלח את נערי בני ישראל ויעלו עולות\" (שמות כד, ה), שיש מקום לתמיהה מדוע נשלחו הנערים דווקא, שינו ללשון המשתמעת לכמה פנים: \u0003\"וישלח את זאטוטי בני ישראל\".\u0004 ועל פי אותו תרגום עצמו שינו גם את הפסוק הבא \"ואל אצילי בני ישראל לא שלח ידו\" (שמות כד, יא) וכתבו \u0003\"ואל זאטוטי בני ישראל לא שלח ידו\".\u0004"],["וכן מה שאמר משה: \"לא חמור אחד מהם נשאתי\" (במדבר טז, טו), תרגמו בלשון כללית יותר: \u0003\"לא חמד\u0004 (דבר יקר, נחמד) \u0003אחד מהם נשאתי\",\u0004 שלא יראה כאילו היה מדובר רק בחמור; ובפסוק המדבר על פולחן השמש והירח, שנאמר: \"אשר חלק ה' אלהיך אותם לכל העמים\" (דברים ד, יט), הוסיפו \u0003\"אשר חלק ה' אלהיך אתם להאיר לכל העמים\"\u0004 כי אחרת אפשר להבין כי לגוים ניתנה רשות לעבוד עבודה זרה, והדבר אינו כן.","וכן הכתוב \u0003\"וילך ויעבד אלהים אחרים\u0004 וישתחו להם ולשמש או לירח או לכל צבא השמים אשר לא ציויתי\u0003\"\u0004 (דברים יז, ג), שהיה אפשר להבין ממנו שכביכול לא ציוה ה' את קיומם והם שבראו את עצמם, ולכן הוסיפו מלה בסוף הפסוק, כך שהוא מסתיים במילים \u0003\"אשר לא צויתי לעובדם\".\u0004","וכן שינו \u0003וכתבו לו: \"את צעירת הרגלים\" ולא כתבו לו \"ואת הארנבת\"\u0004 (ויקרא יא, ו) \u0003מפני שאשתו של תלמי ארנבת שמה, שלא יאמר שחקו בי היהודים והטילו שם אשתי בתורה,\u0004 ולכן שינו וכינוה במילים אחרות.","שנינו במשנה \u0003\"רבן שמעון בן גמליאל אומר: אף בספרים לא התירו שיכתבו אלא יונית\". אמר ר' אבהו אמר ר' יוחנן: הלכה כרבן שמעון בן גמליאל. ואמר ר' יוחנן: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבן שמעון בן גמליאל —\u0004 יש לכך רמז במקרא, ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"יפת אלהים ליפת וישכן באהלי שם\"\u0004 (בראשית ט, כז), לומר: \u0003דבריו של יפת יהיו באהלי שם,\u0004 ללמד שאף לשון יוון שהוא אחד מבני יפת תשמש כלשון של קדושה.","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שהכוונה היא ללשון \u0003גומר ומגוג\u0004 שאף הם מבני יפת (\"בני יפת גומר ומגוג ויוון ותובל ומשך ותירס\". בראשית י,ב) ומדוע דווקא יוונית, ואולי שפה אחרת משפות יפת? \u0003אמר ר' חייא בר אבא: היינו טעמא\u0004 \u0005[זה הטעם],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"יפת אלהים ליפת\"\u0004 מלשון יופי, לומר \u0003יפיותו של יפת תהיה באהלי שם,\u0004 ולשון יוון היא היפה בכל לשונות בני יפת.","\u0003אין\u0004 הבדל \u0003בין כהן משוח בשמן המשחה\u0004 כפי שהיו הכהנים הגדולים ברוב ימי בית הראשון, לכהן גדול שהוא \u0003מרובה בגדים\u0004 כל כך, שיש לו שמונה בגדים אבל לא שמן המשחה, כמו שהיו הכהנים הגדולים בימי בית שני \u0003אלא פר הבא על כל המצות,\u0004 שהוא קרבן שמביא הכהן הגדול לאחר שהורה היתר בדבר האסור שזדונו בכרת ועשה כהוראתו, וקרבן זה אינו בא אלא על ידי כהן גדול משוח.","ועוד: \u0003אין בין כהן\u0004 גדול ה\u0003משמש\u0004 עכשיו בכהונה גדולה \u0003לכהן\u0004 גדול \u0003שעבר\u0004 מכהונתו (כגון כהן גדול שאירע בו פסול ומינו כהן אחר כממלא מקומו, ולאחר שחלפה הסיבה המעכבת וחזר הראשון לעבודתו, העבירו את ממלא מקומו מתפקידו והריהו נחשב מאז כ\"כהן שעבר\") \u0003אלא פר יום הכפורים,\u0004 שכהן שעבר אינו מביא, \u0003ו\u0004כן קרבן \u0003עשירית האיפה,\u0004 שרק כהן גדול המשמש בכהונה מביאו בכל יום.","שנינו במשנה שאין הבדל בין כהן משוח לכהן מרובה בגדים, אלא בפר הבא על המצוות; ומכאן: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לענין פר יום הכפורים ו\u0004לענין חובת \u0003עשירית האיפה זה וזה שוין.\u0004","ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' מאיר\u0004 היא. \u0003דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003ר' מאיר\u0004 היא, \u0003הא תניא\u0004 \u0005[הרי שנינו\u0006 בברייתא\u0005]:\u0006 כהן גדול \u0003מרובה בגדים מביא פר הבא על כל המצות,\u0004 אלו \u0003דברי ר' מאיר, וחכמים אומרים: אינו מביא.\u0004","ושואלים: \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' מאיר\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב \"אם הכהן המשיח יחטא\" (ויקרא ד, ג) נאמר \u0003\"משיח\" אין לי אלא משוח\u0004 ממש \u0003בשמן המשחה, מרובה בגדים מנין\u0004 שהוא בכלל זה? \u0003תלמוד לומר: \"המשיח\",\u0004 שה־ה' הנוספת באה ללמדנו שלאו דווקא כהן שהוא משוח ממש אלא כל שהוא הכהן הגדול.","ושואלים: \u0003במאי אוקימנא\u0004 \u0005[במה העמדנו\u0006 את המשנה\u0005]\u0006 \u0003— ש\u0004\u0003לא כ\u0004שיטת \u0003ר' מאיר. אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של משנתנו\u0005]:\u0006 \u0003אין בין כהן משמש לכהן שעבר אלא פר יום הכפורים ועשירית האיפה\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לכל\u0004 שאר \u0003דבריהן\u0004 האחרים — \u0003זה וזה שוין,\u0004 ואם כן \u0003אתאן\u0004 \u0005[הגענו\u0006 שוב\u0005]\u0006 \u0003ל\u0004שיטת \u0003ר' מאיר, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אירע בו פסול\u0004 בכהן הגדול באחד הימים \u0003ומינו כהן אחר תחתיו,\u0004 הרי אחר שבטל הפסול מן הראשון \u0003ראשון חוזר לעבודתו,\u0004 אולם גם \u0003שני — כל מצות כהונה גדולה עליו,\u0004 אלו \u0003דברי ר' מאיר. ר' יוסי אומר: ראשון חוזר לעבודתו, שני אינו ראוי לא\u0004 להיות \u0003לכהן גדול ולא לכהן הדיוט.\u0004","\u0003ואמר ר' יוסי: מעשה\u0004 היה כגון זה \u0003בר' יוסף בן אולם מציפורי, שאירע בו פסול בכהן גדול ומינוהו תחתיו, ובא מעשה\u0004 זה \u0003לפני חכמים\u0004 לשאול מה יעשו בממלא המקום? \u0003ואמרו: ראשון חוזר לעבודתו, שני אינו ראוי לא לכהן גדול ולא לכהן הדיוט.\u0004","ומסבירים: אינו ראוי ל\u0003כהן גדול — משום איבה,\u0004 שאם יש שני כהנים גדולים בדרגה אחת עלולה להיות איבה ביניהם, ואינו משמש כ\u0003כהן הדיוט משום\u0004 ההלכה כי \u0003מעלין בקודש ולא מורידין,\u0004 ואם כן \u0003רישא\u0004 \u0005[ראש,\u0006 תחילת המשנה\u0005]\u0006 כשיטת \u0003רבנן, וסיפא\u0004 \u0005[וסופה]\u0006 כשיטת \u0003ר' מאיר!\u0004","\u0003אמר רב חסדא: אין\u0004 \u0005[כן]\u0006 אכן \u0003רישא רבנן\u0004 \u0005[ראשה\u0006 כשיטת \u0005חכמים]\u0006 \u0003וסיפא\u0004 \u0005[וסופה]\u0006 כשיטת \u0003ר' מאיר. רב יוסף אמר:\u0004 משנה זו כשיטת \u0003רבי היא, ונסיב לה אליבא דתנאי\u0004 \u0005[ולקח\u0006 וצירף \u0005אותה על פי\u0006 שיטות ה\u0005תנאים\u0006 השונות\u0005]\u0006 כלומר, יש כאן שיטה שלישית, של רבי, שקיבל את דעת ר' מאיר בענין כהן שעבר ואת דעת חכמים בענין מרובה בגדים.","\u0003אין בין במה גדולה\u0004 כגון הבמה שהיתה בנוב או בגבעון שבה היה לאחר חורבן משכן שילה המרכז הדתי \u0003לבמה קטנה\u0004 שבה היה מקריב כל יחיד, \u0003אלא פסחים,\u0004 שאין מקריבים קרבן פסח בבמה קטנה. \u0003זה הכלל: כל שהוא נידר ונידב,\u0004 כלומר, כל קרבן שתחילת חיובו היא בנדר או בנדבה — \u0003קרב בבמה\u0004 קטנה, \u0003וכל שאינו לא נידר ולא נידב\u0004 אלא הוא חובה (כגון פסח) — \u0003אינו קרב בבמה\u0004 קטנה.","ושואלים: ואין הבדל ביניהם אלא \u0003פסחים ותו לא\u0004 \u0005[ולא עוד]?\u0006 והרי מן ההמשך נלמד שיש הבדלים נוספים! ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 כל קרבן שהוא חובה וקבוע לו זמן מסויים \u0003כעין פסחים.\u0004","ומעירים: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא\u0006 המשנה\u0005] —\u0006 כשיטת \u0003ר' שמעון היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון אומר: אף צבור לא הקריבו\u0004 בבמה גדולה \u0003אלא פסחים וחובות שקבוע להם זמן,\u0004 כגון קרבנות הציבור הקבועים, \u0003אבל חובות שאין קבוע להם זמן,\u0004 כגון קרבנות שגגה של כל העדה כולה — \u0003הכא\u0004 \u0005[כאן]\u0006 בבמה קטנה \u0003והכא\u0004 \u0005[וכאן]\u0006 בבמה גדולה \u0003לא קרב\u0004 \u0005[מקריבים],\u0006 אלא בבית המקדש.","\u0003אין בין שילה\u0004 שבה היה המשכן במשך דורות רבים \u0003לירושלים\u0004 שבה נבנה המקדש, \u0003אלא שבשילה אוכלין קדשים קלים ומעשר שני בכל הרואה,\u0004 כלומר, בכל התחום שאפשר לראות את שילה, משום ששילה לא היתה עיר חומה, וכל מה שהיה בתחומה הוא בכלל העיר. \u0003ובירושלים\u0004 אוכלים רק \u0003לפנים מן החומה.\u0004","\u0003וכאן וכאן,\u0004 גם בשילה וגם בירושלים, \u0003קדשי קדשים נאכלין\u0004 רק \u0003לפנים מן הקלעים,\u0004 ובשילה היו קלעים אלה יריעות המשכן ובירושלים הם חומות העזרה. והבדל נוסף: \u0003קדושת שילה\u0004"],["\u0003יש אחריה היתר,\u0004 שלאחר שחרבה שילה הותר להקריב בבמות \u0003וקדושת ירושלים אין אחריה היתר,\u0004 שאף שחרב בית המקדש אסור להקריב בבמות בכל מקום.","\u0003אמר ר' יצחק: שמעתי שמקריבין בבית חוניו\u0004 שבמצרים \u0003בזמן הזה,\u0004 ומעירים: \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 ש\u0003בית חוניו לאו\u0004 \u0005[לא]\u0006 \u0003בית עבודה זרה היא\u0004 אלא מקדש לה' ממש, \u0003וקא סבר\u0004 \u0005[והוא סבור\u0006 גם כן\u0005]\u0006 ש\u0003קדושה ראשונה\u0004 שנתקדשה ירושלים \u0003קידשה לשעתה\u0004 בלבד \u0003ולא קידשה לעתיד לבוא,\u0004 ולכן לאחר שחרב המקדש בירושלים, אין בה עוד קדושה עד שאסור להקריב בכל מקום אחר. ומשום כך בית חוניו הוא מקום כשר להקרבה.","והמקור להלכה זו \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי לא באתם עד עתה אל המנוחה ואל הנחלה\"\u0004 (דברים יב, ט), ודרשו: \u0003\"מנוחה\" — זו שילה, \"נחלה\" — זו ירושלים, מקיש\u0004 \u0005[משווה]\u0006 הכתוב \u0003נחלה למנוחה; מה מנוחה\u0004 שבשילה \u0003יש אחריה היתר\u0004 הקרבה בבמות, \u0003אף נחלה יש אחריה היתר\u0004 הקרבה בבמות.","ומספרים: \u0003אמרו ליה\u0004 \u0005[לו]\u0006 לרבי יצחק: \u0003אמרת\u0004 הלכה זו לגבי בית חוניו? \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003לא\u0004 אמרתי. \u0003אמר רבא\u0004 בלשון שבועה: \u0003האלהים! אמרה\u0004 רבי יצחק, \u0003וגמירנא לה מיניה\u0004 \u0005[ואני\u0006 עצמי \u0005למדתי אותה ממנו].\u0006","ושואלים: \u0003ומאי טעמא קא הדר ביה\u0004 \u0005[ומה טעם חזר בו]\u0006 והכחיש את העניין? \u0003משום קשיא\u0004 \u0005[קושיה]\u0006 שהקשה עליו \u0003רב מרי — דמותיב\u0004 \u0005[שהקשה]\u0006 \u0003רב מרי,\u0004 שהרי שנינו במשנתנו: \u0003קדושת שילה יש אחריה היתר, קדושת ירושלים — אין אחריה היתר. ועוד תנן\u0004 \u0005[שנינו]:\u0006 \u0003משבאו לירושלים נאסרו הבמות, ולא היה להם עוד היתר, והיא\u0004 ירושלים \u0003היתה\u0004 להם \u0003לנחלה\u0004 לעולם.","ומעירים: לגופו של דבר \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בעניין זה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' אליעזר: שמעתי שכשהיו בונין\u0004 את בית המקדש השני, כשבנו את ה\u0003היכל\u0004 היו \u0003עושין קלעים\u0004 מחיצות ארעיות \u0003להיכל, וקלעים לעזרה\u0004 עד שבנו אותם בנין אבן. \u0003אלא שבהיכל\u0004 היו הבנאים \u0003בונין\u0004 כשהם עומדים \u0003מבחוץ\u0004 ולא נכנסו פנימה, \u0003ובעזרה בונין\u0004 היו הבנאים עומדים בשעת הבניה אפילו \u0003מבפנים.\u0004","\u0003ואמר ר' יהושע: שמעתי שמקריבין\u0004 קרבנות על המזבח \u0003אף על פי שאין בית, ו\u0004כן \u0003אוכלין קדשי קדשים\u0004 במקום העזרה \u0003אף על פי שאין קלעים,\u0004 וכן אוכלים \u0003קדשים קלים ומעשר שני\u0004 בירושלים \u0003אף על פי שאין חומה\u0004 בפועל, \u0003מפני שקדושה ראשונה\u0004 שנתקדשה ירושלים \u0003קידשה לשעתה וקידשה לעתיד לבוא.\u0004 ולכן, אף שהחומות אינן קיימות, מכל מקום הקדושה לא בטלה. ומדייקים: מכיוון שר' יהושע אומר שקדושה ראשונה לא בטלה — \u0003מכלל\u0004 הדברים אתה למד כי \u0003ר' אליעזר סבר\u0004 ש\u0003לא קידשה לעתיד לבוא,\u0004 ונמצא אם כן שכבר נחלקו תנאים בדבר זה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: ממאי\u0004 \u0005[ממה]\u0006 מסיק אתה מסקנה זו? \u0003דלמא דכולי עלמא\u0004 \u0005[שמא לדעת הכל]\u0006 גם \u0003קדושה ראשונה קידשה לשעתה וקידשה לעתיד לבוא,\u0004 אלא \u0003ומר מאי דשמיע ליה קאמר ומר מאי דשמיע ליה קאמר\u0004 \u0005[וחכם\u0006 זה, \u0005מה ששמע\u0006 במסורת \u0005אמר, וחכם\u0006 זה, \u0005מה ששמע\u0006 במסורת \u0005אמר]\u0006 ואינם חולקים כלל זה על זה. \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 אם כן \u0003קלעים לר' אליעזר למה לי?\u0004 שהרי הקדושה במקומה גם ללא הקלעים, והתשובה היא — \u0003לצניעותא בעלמא\u0004 \u0005[לצניעות בלבד]\u0006 שאין זה נאה שהמקום המקודש יהיה גלוי לעין כל ולכן מסתירים אותו בקלעים.","\u0003אלא,\u0004 אם מחלוקת תנאים היא בנושא — \u0003כי הני תנאי\u0004 \u0005[כמו תנאים אלו],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' ישמעאל בר' יוסי: למה מנו חכמים\u0004 במסכת ערכין \u0003את אלו\u0004 העיירות שהן מוקפות חומה מימות יהושע בן נון, והלא הרבה יותר היו שם? והטעם — \u0003שכשעלו בני הגולה מצאו את אלו וקידשום, אבל הראשונות\u0004 המנויות בספר יהושע \u0003בטלו\u0004 מיחודן \u0003משבטלה\u0004 (חרבה ישוב) \u0003הארץ\u0004 כשיצאו לגולה. \u0003אלמא קסבר: קדושה ראשונה קידשה לשעתה ולא קידשה לעתיד לבוא.\u0004","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ש\u0003אמר ר' ישמעאל בר' יוסי\u0004 עצמו: \u0003וכי אלו בלבד היו\u0004 ערים מוקפות חומה שנימנו שם במשנה? \u0003והלא כבר נאמר: \"ששים עיר כל חבל ארגב\"\u0004 (דברים ג, ד) \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 על אלו: \u0003\"כל אלה ערים בצרת חומה גבהה\u0004 דלתים ובריח\u0003\"\u0004 (דברים ג, ה), משמע שהיו הרבה מאוד ערים מוקפות חומה. \u0003אלא למה מנו חכמים\u0004 דווקא \u0003את אלו? שכשעלו בני הגולה מצאו\u0004 את \u0003אלו וקידשום.\u0004","ותוהים: \u0003קידשום?!\u0004 אם קדושתם קיימת, מפני מה קידשום?"],["\u0003השתא הא אמרי לא צריכא לקדושי\u0004 \u0005[עכשיו הרי אמרנו\u0006 בסוף דבריו \u0005שאינן צריכות לקידוש]!\u0006 \u0003אלא\u0004 כך צריך לומר: \u0003מצאו את אלו ומנאום,\u0004 וממשיך:","\u0003ולא אלו בלבד\u0004 מקודשות \u0003אלא כל שתעלה לך מסורת בידך מאבותיך שמוקפת חומה מימות יהושע בן נון — כל המצות הללו נוהגין בה, מפני שקדושה ראשונה קידשה לשעתה וקידשה לעתיד לבא.\u0004 ואם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר' ישמעאל\u0004 על דברי \u0003ר' ישמעאל\u0004 עצמו.","ומשיבים: \u0003תרי תנאי אליבא\u0004 \u0005[שני תנאים על פי\u0006 שיטתו\u0005]\u0006 של \u0003ר' ישמעאל בר' יוסי. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 היתה טעות במסורת אחת, כי \u0003הא\u0004 \u0005[זו]\u0006 \u0003ר' אלעזר בר יוסי אמרה, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' אלעזר בר' יוסי אמר,\u0004 נאמר: \u0003\"אשר לוא חמה\"\u0004 (ויקרא כה, ל) ומפני שיש בפסוק זה כתיב וקרי, גם ב־ו' וגם ב־א', אנחנו למדים ש\u0003אף על פי שאין לו עכשיו והיה לו קודם לכן,\u0004 משמע שרבי אלעזר ברבי יוסי הוא הסבור שקדושה ראשונה לא בטלה.","ושוב חוזרים אנו לנושא המרכזי של המסכת, ענייני מגילת אסתר, ומכאן — דפים אחדים העוסקים כולם בדברי אגדה ובדרשות חכמים למגילה וכן בפירוש הכתובים לגבי מעשה הנס וכל הקשור בזה. נאמר: \u0003\"ויהי בימי אחשורוש\"\u0004 (אסתר א, א), \u0003אמר ר' לוי ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יונתן: דבר זה מסורת בידינו מאנשי כנסת הגדולה,\u0004 ש\u0003כל מקום שנאמר\u0004 בו הביטוי \u0003\"ויהי\" אינו אלא לשון צער,\u0004 כאילו נאמר: וי הי.","וראיה לדבר מן הכתובים: \u0003\"ויהי בימי אחשורוש\"\u0004 — \u0003הוה\u0004 \u0005[היה]\u0006 \u0003המן. \"ויהי בימי שפט השפטים\"\u0004 (רות א, א) — \u0003הוה\u0004 \u0005[היה]\u0006 \u0003רעב. \"ויהי כי החל האדם לרב\"\u0004 (בראשית ו, א) — ונאמר מיד לאחר מכן: \u0003\"וירא ה' כי רבה רעת האדם\"\u0004 (בראשית ו, ה).","נאמר: \u0003\"ויהי בנסעם מקדם\"\u0004 (בראשית יא, ב), ושם נאמר: \u0003\"הבה נבנה לנו עיר\"\u0004 (בראשית יא, ד), שהוא חטא מגדל בבל. נאמר: \u0003\"ויהי בימי אמרפל\"\u0004 (בראשית יד, א), והרי נאמר בו: \u0003\"עשו מלחמה\"\u0004 (בראשית יד, ב). נאמר: \u0003\"ויהי בהיות יהושע ביריחו\"\u0004 (יהושע ה, יג), הרי נאמר שם שראה את המלאך \u0003\"וחרבו שלופה בידו\"\u0004 כאזהרה. נאמר: \u0003\"ויהי ה' את יהושע\"\u0004 (יהושע ו, כז), ונאמר מיד אחר כך: \u0003\"וימעלו בני ישראל\"\u0004 (יהושע ז, א). נאמר: \u0003\"ויהי איש אחד מן הרמתים\"\u0004 (שמואל א' א, א) ונאמר לאחר מכן: \u0003\"כי את חנה אהב וה' סגר רחמה\"\u0004 (שמואל א' א, ו).","נאמר: \u0003\"ויהי כי זקן שמואל\"\u0004 (שמואל א' ח, א), ונאמר מיד: \u0003\"ולא הלכו בניו בדרכו\"\u0004 (שמואל א' ח, ג). נאמר: \u0003\"ויהי דוד לכל דרכו משכיל וה' עמו\"\u0004 (שמואל א' יח, יד), ונאמר בסמוך לו: \u0003\"ויהי שאול עוין את דוד\"\u0004 (שמואל א' יח, ט). נאמר: \u0003\"ויהי כי ישב המלך בביתו\"\u0004 (שמואל ב' ז, א) ורצה לבנות את המקדש, נאמר לו: \u0003\"רק אתה לא תבנה הבית\"\u0004 (דברי הימים ב' ו, ט).","ומקשים על כך: \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ויהי ביום השמיני\"\u0004 (ויקרא ט, א) שהיה יום חנוכת המשכן, \u0003ותניא\u0004 \u0005[ושנינו\u0006 בברייתא\u0005]\u0006 על פסוק זה: \u0003אותו היום היתה שמחה לפני הקדוש ברוך הוא כיום שנבראו בו שמים וארץ,\u0004 וראיה לדבר, מעין גזירה שווה, \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"ויהי ביום השמיני\" וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 ביום בריאת שמים וארץ \u0005:\u0006 \u0003\"ויהי\u0004 ערב ויהי \u0003בקר יום אחד\"\u0004 (בראשית א, ה). הרי שהביטוי \"ויהי\" אינו דווקא לשון של צער!","ומשיבים: פסוק זה איננו סותר את הכלל, שכן באותו יום שמדובר בו \u0003הא\u0004 \u0005[הרי]\u0006 אירע אף בו אסון, שכן \u0003שכיב\u0004 \u0005[מתו]\u0006 בו \u0003נדב ואביהוא.\u0004","ומקשים מפסוק אחר: \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ויהי בשמונים שנה וארבע מאות שנה\"\u0004 (מלכים א' ו, א) ובפסוק זה מסופר כי נבנה בית המקדש! וכן \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ויהי כאשר ראה יעקב את רחל\"\u0004 (בראשית כט, י)! ועוד, שהרי נאמר: \u0003\"ויהי ערב ויהי בקר יום אחד\"\u0004 (בראשית א, ה)! \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 יום \u0003שני\u0004 של הבריאה שנאמר אף בו לשון \"ויהי\"! \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 יום \u0003שלישי! והאיכא טובא\u0004 \u0005[והרי יש הרבה\u0006 פסוקים שכתוב בהם \"ויהי\" ואינם לשון צער\u0005],\u0006 ואם כן, כלל זה לכאורה איננו נכון!","אלא \u0003אמר רב אשי: כל\u0004 מקום שנאמר בו \u0003\"ויהי\"\u0004 בלבד, \u0003איכא הכי ואיכא הכי\u0004 \u0005[יש כך ויש כך]\u0006 — יש של שמחה ויש של צער, אולם כל מקום שנאמר בו הלשון \u0003\"ויהי בימי\" אינו\u0004 אלא \u0003לשון של צער.\u0004","ומפרטים: \u0003חמשה\u0004 פסוקים שנאמר בהם הלשון \u0003\"ויהי בימי\" הוו\u0004 \u0005[הם]\u0006 במקרא: — \u0003\"ויהי בימי אחשורוש\", \"ויהי בימי שפט השפטים\", \"ויהי בימי אמרפל\", \"ויהי בימי אחז\", \"ויהי בימי יהויקים\",\u0004 ויש סיום של צער בכל המקרים הללו.","אגב דברי ר' לוי שהביא דברי מסורת קדומים, מביאים דבר נוסף ש\u0003אמר ר' לוי: דבר זה מסורת בידינו מאבותינו: אמוץ\u0004 אביו של ישעיהו \u0003ואמציה\u0004 מלך יהודה — \u0003אחים הוו\u0004 \u0005[היו],\u0006 ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בזה? כלומר, מה יש ללמוד מזה, למה חשוב לנו הדבר?","ומשיבים: \u0003כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: כל כלה שהיא צנועה\u0004 כשהיא \u0003בבית חמיה — זוכה ויוצאין ממנה מלכים ונביאים. מנלן\u0004 \u0005[מנין לנו\u0006 הדבר\u0005]?\u0006 \u0003מתמר, דכתיב\u0004 \u0005[שנאמר\u0006 בה\u0005]:\u0006 \u0003\"ויראה יהודה ויחשבה לזונה כי כסתה פניה\"\u0004 (בראשית לח, טו), ולכאורה הפסוק תמוה; וכי \u0003משום\u0004 ש\u0003כסתה פניה ויחשבה לזונה?\u0004 הלא להיפך: דרך הזונה שמגלה פניה!","\u0003אלא\u0004 הכוונה היא \u0003משום\u0004 ש\u0003כסתה פניה בבית חמיה, ולא הוה ידע לה\u0004 \u0005[הכיר אותה]\u0006 בביתו, לכן יכול היה לבוא אליה, \u0003ו\u0004בסופו של דבר \u0003זכתה ויצאו ממנה מלכים ונביאים. מלכים —\u0004 יודעים אנו \u0003מדוד,\u0004 שהיה מבני פרץ, \u0003ונביאים\u0004 שלא נזכרו במפורש, אנחנו למדים ממה ש\u0003אמר ר' לוי: מסורת בידינו מאבותינו: אמוץ ואמציה אחים היו, וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"חזון ישעיהו בן אמוץ\"\u0004 (ישעיהו א, א).","\u0003ו\u0004עוד \u0003אמר ר' לוי: דבר זה מסורת בידינו מאבותינו: מקום ארון אינו מן המדה,\u0004 כלומר, ארון הברית במקדש אינו נכנס בגדר של מידה, ובשל כך איננו ממעט מן השטח של בית קודש הקדשים.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנוייה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003ארון שעשה משה יש לו\u0004 מקום פנוי \u0003עשר אמות לכל רוח\u0004 (צד) \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בתיאור בית המקדש של שלמה: \u0003\"ולפני הדביר עשרים אמה ארך\"\u0004 (מלכים א' ו, כ), וכיון ששטח בית קודש הקדשים (הדביר) היה עשרים על עשרים אמה, כמשמעות הכתוב, ועם כל זה היו עשר אמות פנויים מכל צידי הארון, הרי שהארון עצמו לא תפס מקום כלל \u0003וכתיב\u0004 \u0005[ו\u0006כן \u0005נאמר]:\u0006 \u0003\"כנף הכרוב האחד עשר אמות וכנף הכרוב האחד עשר אמות\"\u0004 (מלכים א' ו, כד), הרי שכנפי הכרובים ממלאים את השטח כולו, ואם כן ה\u0003ארון גופיה\u0004 \u0005[עצמו]\u0006 \u0003היכא הוה קאי\u0004 \u0005[היכן היה עומד]?\u0006 \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 ש\u0003בנס היה עומד\u0004 הארון ולא היה נכנס כלל בשיעור של מקום.","מכאן ואילך מביאים שורה ארוכה של פתיחות למגילת אסתר. שהיה נהוג שלפני שהתחיל החכם לדרוש באגדה בנושא מסויים היה פותח בפסוק ממקום אחר, ודורש אותו לעניינו. \u0003ר' יונתן פתח לה פיתחא\u0004 \u0005[פתח]\u0006 \u0003להאי פרשתא מהכא\u0004 \u0005[לפרשה זו\u0006 של אסתר \u0005מכאן],\u0006 נאמר: \u0003\"וקמתי עליהם\u0004 נאום ה' צבאות \u0003והכרתי לבבל שם ושאר ונין ונכד נאם ה'\"\u0004 (ישעיה יד, כב) ודרש: \u0003\"שם\" — זה הכתב\u0004 שלהם שכלה מן העולם, \u0003\"שאר\" — זה לשון\u0004 של בבל העתיקה, \u0003\"נין\" — זה מלכות, \"ונכד\" — זו ושתי\u0004 שלפי המסורת היתה נכדתו של נבוכדנצר, ובמגילה מסופר איך נכרתה גם היא.","\u0003ר' שמואל בר נחמני פתח לה פיתחא\u0004 \u0005[פתח]\u0006 \u0003להאי פרשתא מהכא\u0004 \u0005[לפרשה זו מכאן],\u0006 נאמר: \u0003\"תחת הנעצוץ יעלה ברוש ותחת הסרפד יעלה הדס\u0004 והיה לה' לשם לאות עולם לא יכרת\u0003\"\u0004 (ישעיה נה, יג),","וכך פירש: \u0003\"תחת הנעצוץ\" — תחת המן הרשע.\u0004 ומדוע נקרא שמו \"נעצוץ\"? \u0003שעשה עצמו עבודה זרה,\u0004 שכן ציוה שיכרעו וישתחוו לו, וראייה שעניין עבודה זרה הוא, ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ובכל הנעצוצים ובכל הנהללים\"\u0004 (ישעיה ז, יט).","\u0003\"יעלה ברוש\" — זה מרדכי.\u0004 ולמה הוא מכונה \"ברוש\"? משום שהוא \u0003נקרא\u0004 ברמז \u0003ראש לכל הבשמים\u0004 (ברוש — בראש), \u0003שנאמר: \"ואתה קח לך בשמים ראש מר דרור\"\u0004 (שמות ל, כג) \u0003ומתרגמינן\u0004 \u0005[ואנו מתרגמים]:\u0006 \"מר דרור\" — \u0003מרי דכי,\u0004 שמרומז כאן השם מרדכי, וכיון שמרדכי הוא בשמים ראש, לכן הוא נקרא ברוש.","והמשך הכתוב \u0003\"\u0004ו\u0003תחת הסרפד\" — תחת ושתי הרשעה.\u0004 ומדוע נקראת \"סרפד\"? משום שהיתה \u0003בת בנו של נבוכדנצר הרשע, ששרף רפידת בית ה'\u0004 (סרפד — שרף רפד), \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"רפידתו זהב\"\u0004 (שיר השירים ג, י).","\u0003\"יעלה הדס\" — זו אסתר הצדקת שנקראת הדסה, שנאמר: \"ויהי אמן את הדסה\u0004 היא אסתר\u0003\"\u0004 (אסתר ב, ז). \u0003\"והיה לה' לשם\" — זו מקרא מגילה. \"לאות עולם לא יכרת\" — אלו ימי פורים.\u0004","\u0003ר' יהושע בן לוי פתח לה פיתחא\u0004 \u0005[פתח]\u0006 \u0003להאי פרשתא מהכא\u0004 \u0005[לפרשה זו מכאן],\u0006 נאמר: \u0003\"והיה כאשר שש ה' עליכם להיטיב אתכם\u0004 ולהרבות אתכם \u0003כן ישיש... להרע אתכם\"\u0004 (דברים כח, סג), ושואלים לגופו של ענין:","\u0003ומי חדי\u0004 \u0005[והאם שמח]\u0006 \u0003הקדוש ברוך הוא במפלתן של רשעים? והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"בצאת לפני החלוץ ואמרים הודו לה' כי לעולם חסדו\"\u0004 (דברי הימים ב' כ, כא), \u0003ואמר ר' יוחנן: מפני מה לא נאמר\u0004 לשון \u0003\"כי טוב\" בהודאה זו?\u0004 שהרי בדרך כלל נוסח הכתוב הוא \"הודו לה' כי טוב כי לעולם חסדו\" — \u0003לפי שאין הקדוש ברוך הוא שמח במפלתן של רשעים,\u0004 ומכיון שנאמרה שירה זו לאחר הניצחון במלחמה, אף שהיתה בה מפלת רשעים, מכל מקום אין מזכירים שם ה' לטובה.","\u0003ואמר ר' יוחנן\u0004 כיוצא בזה: \u0003מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"ולא קרב זה אל זה כל הלילה\"\u0004 (שמות יד, כ) — הכוונה היא ש\u0003בקשו מלאכי השרת לומר שירה,\u0004 כי המלאכים אומרים שירה זה לזה, (כאמור \"וקרא זה אל זה ואמר\"), מיד \u0003אמר הקדוש ברוך הוא: מעשי ידי\u0004 (המצרים) \u0003טובעין בים, ואתם אומרים שירה?\u0004 הרי שאפילו במפלתם של רשעים אין הקדוש ברוך הוא שש!","\u0003אמר ר' אלעזר,\u0004 כך צריך להבין: \u0003הוא\u0004 עצמו אכן \u0003אינו שש, אבל\u0004 את \u0003אחרים\u0004 הוא \u0003משיש\u0004 (גורם לאחרים שישמחו). ומעירים: \u0003ודיקא נמי\u0004 \u0005[ומדוייק גם כן]\u0006 בלשון הכתוב, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"כן ישיש\"\u0004 בבנין הפעיל — שהוא משיש אחרים, \u0003ולא כתיב\u0004 \u0005[ולא נאמר]\u0006 לשון \u0003\"ישוש\",\u0004 וזאת מפני שהוא עצמו אכן אינו שש. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","\u0003ר' אבא בר כהנא פתח לה פיתחא\u0004 \u0005[פתח]\u0006 \u0003להאי פרשתא מהכא\u0004 \u0005[לפרשה זו מכאן],\u0006 מה שנאמר: \u0003\"לאדם שטוב לפניו נתן חכמה ודעת ושמחה\"\u0004 (קהלת ב, כו) — \u0003זה מרדכי הצדיק, \"ולחוטא נתן ענין לאסף ולכנוס\"\u0004 (קהלת ב, כו) — \u0003זה המן, \"לתת לטוב לפני האלהים\"\u0004 (קהלת ב, כו) — \u0003זה מרדכי ואסתר, דכתיב\u0004 \u0005[שנאמר]\u0006 במגילה: \u0003\"ותשם אסתר את מרדכי על בית המן\"\u0004 (אסתר ח, ב).","\u0003רבה בר עופרן פתח לה פיתחא\u0004 \u0005[פתח]\u0006 \u0003להאי פרשתא מהכא\u0004 \u0005[לפרשה זו מכאן],\u0006 נאמר: \u0003\"ושמתי כסאי בעילם והאבדתי משם מלך ושרים\"\u0004 (ירמיהו מט, לח), \u0003\"מלך\" — זו ושתי, \"ושרים\" — זה המן ועשרת בניו.\u0004","\u0003רב דימי בר יצחק פתח לה פיתחא\u0004 \u0005[פתח]\u0006 \u0003להאי פרשתא מהכא\u0004 \u0005[לפרשה זו מכאן],\u0006"],["\u0003נאמר: \"כי עבדים אנחנו ובעבדתנו לא עזבנו אלהינו ויט עלינו חסד לפני מלכי פרס\"\u0004 (עזרא ט, ט), ו\u0003אימתי\u0004 היה הדבר — \u0003בזמן המן.\u0004","\u0003ר' חנינא בר פפא פתח לה פתחא\u0004 \u0005[פתח]\u0006 \u0003להא פרשתא מהכא\u0004 \u0005[לפרשה זו מכאן]:\u0006 \u0003\"הרכבת אנוש לראשנו באנו באש ובמים\"\u0004 (תהלים סו, יב); \u0003\"באש\" — בימי נבוכדנצר הרשע\u0004 שהטיל את הצדיקים לכבשן. \u0003\"ובמים\" — בימי פרעה\u0004 שגזר להשליך כל הבן למים. \u0003\"ותוציאנו לרויה\" — בימי המן.\u0004","\u0003ר' יוחנן פתח לה פתחא\u0004 \u0005[פתח]\u0006 \u0003להא פרשתא מהכא\u0004 \u0005[לפרשה זו מכאן],\u0006 מפסוק זה: \u0003\"זכר חסדו ואמונתו לבית ישראל ראו כל אפסי ארץ את ישועת אלהינו\"\u0004 (תהלים צח, ג), \u0003אימתי ראו כל אפסי ארץ את ישועת אלהינו — בימי מרדכי ואסתר\u0004 שנודע הדבר לכל העמים.","\u0003ריש לקיש פתח לה פתחא\u0004 \u0005[פתח]\u0006 \u0003להא פרשתא מהכא\u0004 \u0005[לפרשה זו מכאן],\u0006 מפסוק זה: \u0003\"ארי נהם ודב שוקק מושל רשע על עם דל\"\u0004 (משלי כח, טו); \u0003\"ארי נהם\" — זה נבוכדנצר הרשע, דכתיב ביה\u0004 \u0005[שנאמר בו]:\u0006 \u0003\"עלה אריה מסבכו\"\u0004 (ירמיה ד, ז). \u0003\"דב שוקק\" — זה אחשורוש, דכתיב ביה\u0004 \u0005[שנאמר בו]:\u0006 \u0003\"וארו חיוה אחרי תנינה דמיה לדב\"\u0004 \u0005[והנה חיה אחרת שניה דומה לדוב]\u0006 (דניאל ז, ה), \u0003ותני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף: אלו פרסיים,\u0004 ומדוע דימה אותם דניאל לדוב? \u0003שאוכלין ושותין\u0004 הרבה \u0003כדוב, ומסורבלין בשר\u0004 (שמנים) \u0003כדוב, ומגדלין שער כדוב, ואין להם מנוחה כדוב,\u0004 שדרכו לנוע ממקום למקום.","\u0003\"מושל רשע\" — זה המן. \"על עם דל\" — אלו ישראל,\u0004 ומדוע קוראים להם \"עם דל\"? \u0003שהם דלים מן המצות.\u0004","\u0003ר' אלעזר פתח לה פתחא\u0004 \u0005[פתח]\u0006 \u0003להא פרשתא מהכא\u0004 \u0005[לפרשה זו מכאן]:\u0006 \u0003\"בעצלתים ימך המקרה ובשפלות ידים ידלף הבית\"\u0004 (קהלת י, יח); \u0003בשביל עצלות\u0004 (\"עצלתיים\") \u0003שהיה להם לישראל, שלא עסקו בתורה, נעשה שונאו של הקדוש ברוך הוא\u0004 (בלשון נקיה, והכוונה: הקדוש ברוך הוא) \u0003מך, ואין\u0004 פירוש \u0003\"מך\" אלא עני, שנאמר: \"ואם מך הוא מערכך\"\u0004 (ויקרא כז, ח), \u0003ואין \"מקרה\" אלא\u0004 כינוי עבור \u0003הקדוש ברוך הוא, שנאמר: \"המקרה במים עליותיו\"\u0004 (תהלים קד, ג), וכביכול אין בו יכולת לעזור להם.","\u0003רב נחמן בר יצחק פתח לה פתחא\u0004 \u0005[פתח]\u0006 \u0003להא פרשתא מהכא\u0004 \u0005[לפרשה זו מכאן]:\u0006 \u0003\"שיר המעלות\u0004 לדוד \u0003לולי ה' שהיה לנו יאמר נא ישראל. לולי ה' שהיה לנו בקום עלינו אדם\"\u0004 (תהלים קכד, ב), ומדייק: \u0003\"אדם\" ולא מלך.\u0004 ומתי היה זה — בזמן המן.","\u0003רבא פתח לה פתחא\u0004 \u0005[פתח]\u0006 \u0003להא פרשתא מהכא\u0004 \u0005[לפרשה זו מכאן]:\u0006 \u0003\"ברבות צדיקים ישמח העם ובמשל רשע יאנח עם\"\u0004 (משלי כט, ב); \u0003\"ברבות צדיקים ישמח העם\" — זה מרדכי ואסתר, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והעיר שושן צהלה ושמחה\"\u0004 (אסתר ח, טו). \u0003\"ובמשל רשע יאנח העם\" — זה המן, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והעיר שושן נבוכה\"\u0004 (אסתר ג, טו).","\u0003רב מתנה אמר\u0004 פתיחה \u0003מהכא\u0004 \u0005[מכאן]:\u0006 \u0003\"כי מי גוי גדול אשר לו אלהים קרבים אליו\"\u0004 (דברים ד, ז), כפי שראו זאת בניסים הגדולים שאירעו להם בימי מרדכי ואסתר. \u0003רב אשי אמר מהכא\u0004 \u0005[מכאן]:\u0006 \u0003\"או הנסה אלהים\u0004 לבוא לקחת לו גוי מקרב גוי\u0003\"\u0004 (דברים ד, לד).","ושוב לענין פירוש המגילה, נאמר: \u0003\"ויהי בימי אחשורוש\"\u0004 (אסתר א, א), \u0003אמר רב:\u0004 על זה אפשר לומר \u0003ויי והי, הדא דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \u0003\"והתמכרתם שם לאיביך לעבדים ולשפחות\u0004 ואין קונה\u0003\"\u0004 (דברים כח, סח).","\u0003ושמואל אמר\u0004 פתח לפרשה מכאן: \u0003\"\u0004ואף גם זאת בהיותם בארץ אויביהם \u0003לא מאסתים ולא געלתים לכלתם\"\u0004 (ויקרא כו, מד), וכך הוא מפרש: \u0003\"לא מאסתים\" — בימי יוונים. \"ולא געלתים\" — בימי אספסיינוס. \"לכלתם\" — בימי המן. \"להפר בריתי אתם\" — בימי פרסיים. \"כי אני ה' אלהיהם\" — בימי גוג ומגוג.\u0004","\u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]:\u0006 \u0003\"לא מאסתים\" — בימי כשדים, שהעמדתי להם דניאל חנניה מישאל ועזריה\u0004 שיתפללו על ישראל, \u0003\"ולא געלתים\" — בימי יוונים, שהעמדתי להם שמעון הצדיק, וחשמונאי ובניו, ומתתיה כהן גדול. \"לכלתם\" — בימי המן, שהעמדתי להם\u0004 צדיקים כ\u0003מרדכי ואסתר. \"להפר בריתי אתם\" בימי רומיים, שהעמדתי להם\u0004 חכמים \u0003של בית רבי\u0004 ושאר \u0003חכמי דורות. \"כי אני ה' אלהיהם\" — לעתיד לבוא, ש\u0004אז \u0003אין כל אומה ולשון יכולה\u0004 עוד \u0003לשלוט בהם.\u0004","\u0003ר' לוי אמר\u0004 פתח לפרשה \u0003מהכא\u0004 \u0005[מכאן]:\u0006 \u0003\"ואם לא תורישו את ישבי הארץ\u0004 מפניכם, והיה אשר תותירו מהם לשיכים בעיניכם\u0003\"\u0004 (במדבר לג, נה), וכיון שלא הרגו את כל בני עמון נשאר המן.","ו\u0003ר' חייא אמר מהכא\u0004 \u0005[מכאן],\u0006 מהמשכו של הכתוב הקודם: \u0003\"והיה כאשר דמיתי לעשות להם אעשה לכם\"\u0004 (במדבר לג, נו).","וממשיכים במדרש המגילה: \u0003\"אחשורוש\", אמר רב\u0004 יש לדרוש את השם הזה: \u0003אחיו של ראש ובן גילו\u0004 (בן מזלו, הדומה לו) \u0003של ראש.\u0004 והוא מסביר: \u0003אחיו של ראש — אחיו של נבוכדנצר הרשע שנקרא \"ראש\", שנאמר: \"אנת הוא רישא די דהבא\"\u0004 \u0005[אתה הוא ראש הזהב]\u0006 (דניאל ב, לח), \u0003בן גילו\u0004 (בן מזלו, דומה לו) \u0003של ראש\u0004 משום \u0003שהוא\u0004 נבוכדנצר \u0003הרג\u0004 את ישראל, \u0003הוא ביקש להרוג, הוא החריב\u0004 את המקדש — \u0003הוא בקש להחריב\u0004 את היסוד שיסד זרובבל בבית המקדש, \u0003שנאמר: \"ובמלכות אחשורוש בתחלת מלכותו כתבו שטנה על ישבי יהודה וירושלים\"\u0004 (עזרא ד, ו), וגזרו להפסיק את בניין המקדש.","\u0003ושמואל אמר:\u0004 \"אחשורוש\" יש לדרוש מלשון שחור, \u0003שהושחרו פניהם של ישראל בימיו כשולי\u0004 (כתחתית) \u0003קדרה\u0004 שהיא שחורה ביותר. \u0003ור' יוחנן אמר\u0004 דרשה אחרת: \u0003כל שזוכרו אמר \"אח\u0004 (אוי) \u0003לראשו\". ור' חנינא אמר,\u0004 פירוש \"אחשורוש\" הוא: \u0003שהכל נעשו רשין\u0004 (עניים) \u0003בימיו, שנאמר: \"וישם המלך אחשורוש מס\"\u0004 (אסתר י, א).","וממשיכים \u0003\"הוא אחשורוש\"\u0004 (אסתר א, א) שנאמר שם, כוונתו: \u0003הוא\u0004 שהיה \u0003ברשעו מתחילתו ועד סופו.\u0004 וכן בכל מקום שנאמר \"הוא\" באופן זה, כך משמעו, וכגון: \u0003\"הוא עשו\"\u0004 (בראשית לו, מג) — \u0003הוא ברשעו מתחילתו ועד סופו, \"הוא דתן ואבירם\"\u0004 (במדבר כו, ט) — \u0003הן ברשען מתחילתן ועד סופן, \"הוא המלך אחז\"\u0004 (דברי הימים ב' כח, כב) — \u0003הוא ברשעו מתחילתו ועד סופו.\u0004","וכן בכל מקום שנאמר בו \"הוא\", הרי זה בא לציין המשכיות, כל מקום ועניינו, וכגון מה שנאמר: \u0003\"אברם הוא אברהם\"\u0004 (דברי הימים א' א, כז), שהכוונה היא: \u0003הוא בצדקו מתחילתו ועד סופו,\u0004 וכן: \u0003\"הוא אהרן ומשה\"\u0004 (שמות ו, כו) — \u0003הן בצדקן מתחילתן ועד סופן.\u0004 וכן מה שנאמר בדוד \u0003\"ודוד הוא הקטן\"\u0004 (שמואל א' יז, יד) — לומר ש\u0003הוא בקטנותו מתחילתו ועד סופו, כשם שבקטנותו\u0004 שהיה הדיוט \u0003הקטין עצמו אצל מי שגדול ממנו בתורה, כך במלכותו הקטין עצמו\u0004 גם אז \u0003אצל מי שגדול ממנו בחכמה.\u0004","על מה שנאמר \u0003\"המלך\"\u0004 (אסתר א, א), \u0003אמר רב:\u0004 הכוונה היא \u0003שמלך מעצמו\u0004 ולא ירש את המלוכה. \u0003אמרי לה\u0004 \u0005[\u0006יש ש\u0005אומרים אותה,\u0006 זאת\u0005]\u0006 \u0003לשבח ואמרי לה\u0004 \u0005[ו\u0006יש ש\u0005אומרים אותה,\u0006 זאת\u0005]\u0006 כביטוי של \u0003גנאי. אמרי לה\u0004 \u0005[\u0006יש ש\u0005אומרים אותה]\u0006 \u0003לשבח\u0004 — \u0003דלא הוה איניש דחשיב למלכא כוותיה\u0004 \u0005[שלא היה אדם שראוי ל\u0006היות \u0005מלך כמותו],\u0006 \u0003ואמרי לה\u0004 \u0005[ו\u0006יש ש\u0005אומרים אותה]\u0006 \u0003לגנאי — דלא הוה חזי למלכותא וממונא יתירא הוא דיהב וקם\u0004 \u0005[שלא היה ראוי למלכות\u0006 אלא \u0005ממון הרבה הוא שנתן ועמד,\u0006 נעשה מלך\u0005].\u0006","נאמר \u0003\"מהדו ועד כוש\"\u0004 ונחלקו בזה \u0003רב ושמואל; חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: הודו\u0004 היא מדינה \u0003בסוף העולם וכוש בסוף\u0004 האחר של \u0003העולם, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: הודו וכוש גבי הדדי הוו קיימי\u0004 \u0005[זו ליד זו היו עומדות],\u0006 והכוונה היא: ש\u0003כשם שמלך על הודו ו\u0004על \u0003כוש, כך מלך מסוף העולם ועד סופו.\u0004","\u0003כיוצא בדבר\u0004 זה \u0003אתה אומר\u0004 בכתוב המדבר בשלמה: \u0003\"כי הוא רדה בכל עבר הנהר מתפסח ועד עזה\"\u0004 (מלכים א' ה, ד), ואף על זה נחלקו \u0003רב ושמואל; חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: תפסח בסוף העולם ועזה בסוף העולם, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: תפסח ועזה בהדי הדדי הוו קיימי\u0004 \u0005[זו ליד זו הן עומדות],\u0006 ובא הכתוב לומר: \u0003כשם שמלך על תפסח ועל עזה, כך מלך על כל העולם כולו.\u0004","ושוב לפירוש המגילה, נאמר: \u0003\"שבע ועשרים ומאה מדינה\"\u0004 (אסתר א, א), \u0003אמר רב חסדא,\u0004 יש להבין את הכתוב כך: \u0003בתחילה מלך על שבע\u0004 מדינות, \u0003ולבסוף מלך על עשרים, ולבסוף מלך על מאה.\u0004 ושואלים: \u0003אלא מעתה,\u0004 הכתוב הדומה לו \u0003\"ושני חיי עמרם שבע ושלשים ומאת שנה\"\u0004 (שמות ו, כ), \u0003מאי דרשת ביה\u0004 \u0005[מה אתה דורש בו],\u0006 כיוצא בזה? ומשיבים: \u0003שאני הכא דקרא יתירא\u0004 \u0005[שונה כאן\u0006 במגילת אסתר, \u0005שפסוק מיותר\u0006 הוא\u0005],\u0006 \u0003מכדי כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"מהדו ועד כוש\"\u0004 (אסתר א, א), ואם כן \u0003\"שבע ועשרים ומאה מדינה\" למה לי\u0004 לפרט? אלא \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003לדרשה\u0004 שלא על כולם מלך בבת אחת.","אגב הדברים על מלכות אחשורוש \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלשה\u0004 אנשים \u0003מלכו בכיפה,\u0004 כלומר, על כל העולם, \u0003ואלו הן: אחאב ואחשורוש ונבוכדנצר.\u0004 ומפרטים: \u0003אחאב, דכתיב\u0004 \u0005[שנאמר]\u0006 בדברי עובדיהו עבד אחאב לאליהו: \u0003\"חי ה' אלהיך אם יש גוי וממלכה אשר לא שלח אדני שם לבקשך\u0004 ואמרו אין והשביע את הממלכה ואת הגוי כי לא ימצאכה\u0003\"\u0004 (מלכים א' יח, י) \u0003ואי\u0004 \u0005[ואילו]\u0006 \u0003לא דהוה מליך עלייהו\u0004 \u0005[שהיה מולך עליהם]\u0006 \u0003היכי מצי משבע להו\u0004 \u0005[איך היה יכול להשביע אותם]?\u0006 משמע שהיה מולך בכיפה.","\u0003נבוכדנצר דכתיב\u0004 \u0005[שנאמר בו]:\u0006 \u0003\"והיה הגוי והממלכה\u0004 אשר לא יעבדו אותו את נבוכנאצר מלך בבל ואת \u0003אשר לא יתן את צוארו בעל מלך בבל\"\u0004 (ירמיהו כז, ח). \u0003אחשורוש הא דאמרן\u0004 \u0005[זו שאמרנו].\u0006"],["\u0003(סימן\u0004 לשמות המוזכרים להלן: \u0003שסד\"ך — ש\u0004למה \u0003ס\u0004נחריב \u0003ד\u0004רייוש \u0003כ\u0004ורש\u0003).\u0004 ושואלים: \u0003ותו ליכא\u0004 \u0005[ועוד אין]\u0006 מלכים שמלכו בכל העולם? \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 \u0003שלמה\u0004 המלך! ומשיבים: \u0003לא סליק מלכותיה\u0004 \u0005[סיים\u0006 את \u0005מלכותו]\u0006 אלא גלה ממנה.","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 ששלמה היה קודם \u0003מלך ו\u0004בסופו היה \u0003הדיוט\u0004 ולא חזר למלוכה, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003מלך והדיוט ומלך\u0004 — שחזר למלכותו, אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 ולמה לא נמנה? ומשיבים: \u0003שלמה מילתא אחריתי הוה ביה\u0004 \u0005[דבר אחר היה בו],\u0006 שאי אפשר להשוותו לאחרים — לפי \u0003שמלך על העליונים\u0004 (השדים) \u0003ועל התחתונים, שנאמר: \"וישב שלמה על כסא ה'\u0004 למלך\u0003\"\u0004 (דברי הימים א' כט, כג), לומר שמלך גם בעולמות העליונים, ואינו דומה לאחרים.","ושואלים עוד: \u0003והא הוה\u0004 \u0005[והרי היה]\u0006 \u0003סנחריב\u0004 שמלך על העולם כולו, \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"מי בכל אלהי הארצות האלה אשר הצילו את ארצם מידי\"\u0004 (ישעיהו לו, כ)! ומשיבים: \u0003הא איכא\u0004 \u0005[הרי ישנה]\u0006 \u0003ירושלים\u0004 ש\u0003לא כבשה.\u0004","ושואלים: \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 את \u0003דריוש, דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"דריוש מלכא כתב לכל עממיא אמיא ולשניא די דירין בכל ארעא שלמכון ישגא\"\u0004 \u0005[דריוש המלך כתב לכל העמים האומות והלשונות הדרים בכל הארץ: שלומכם ירבה]\u0006 (דניאל ו, כו)! ומשיבים: \u0003הא איכא\u0004 \u0005[הרי יש]\u0006 \u0003שבע\u0004 מדינות ש\u0003לא מלך עלייהו\u0004 \u0005[עליהן],\u0006 שנאמר: \u0003\"שפר קדם דריוש והקים על מלכותא לאחשדרפניא מאה ועשרין\"\u0004 \u0005[הוטב בעיני דריוש והקים על מלכותו אחשדרפנים מאה ועשרים]\u0006 (דניאל ו, ב), משמע שלא מלך על כל העולם, שהרי לאחשורוש בנו היו שבע מדינות יתירות.","ומקשים: \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 את \u0003כורש, דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"כה אמר כרש מלך פרס כל ממלכות הארץ נתן לי ה'\"\u0004 (עזרא א, ב)! ומשיבים: מכאן אין ראיה כי \u0003התם אשתבוחי הוא דקא משתבח בנפשיה\u0004 \u0005[שם שבח הוא שמשתבח בעצמו]\u0006 ולא כן היה באמת.","נאמר: \u0003\"בימים ההם כשבת המלך\u0004 אחשורוש על כסא מלכותו\u0003\"\u0004 (אסתר א, ב), \u0003וכתיב בתריה\u0004 \u0005[ונאמר אחריו]\u0006 \u0003\"בשנת שלש למלכו\"\u0004 (אסתר א, ג) ולכאורה יש בכך סתירה! \u0003אמר רבא: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כשבת\" —\u0004 לא מיד כשעלה למלוכה, אלא \u0003לאחר שנתיישבה דעתו\u0004 ונרגע מן הדאגה. ומה היתה דאגתו? \u0003אמר: בלשצר\u0004 מלך בבל \u0003חשב וטעה\u0004 לגבי גאולת ישראל, אולם \u0003אנא חשיבנא\u0004 \u0005[אני אחשב]\u0006 \u0003ולא טעינא\u0004 \u0005[אטעה].\u0006","ומסבירים: \u0003מאי היא\u0004 \u0005[מה הוא]\u0006 הדבר — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי לפי מלאת לבבל שבעים שנה אפקוד אתכם\"\u0004 (ירמיהו כט, י), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בפסוק אחר בשינוי: \u0003\"\u0004מספר השנים אשר היה דבר ה' אל ירמיה הנביא \u0003למלאות לחרבות ירושלים שבעים שנה\"\u0004 (דניאל ט, ב). \u0003חשוב\u0004 \u0005[\u0006ו\u0005חשב]\u0006 בלשצר כך: \u0003ארבעין\u0004 \u0005[ארבעים]\u0006 \u0003וחמש\u0004 שנה של \u0003נבוכדנצר, ועשרים ותלת\u0004 \u0005[ושלוש]\u0006 של \u0003אויל מרודך, ותרתי דידיה\u0004 \u0005[ושתיים שלו],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003שבעים,\u0004 וכיוון שכך, היה בטוח שלא תתקיים הנבואה, ואמר: \u0003אפיק מאני דבי מקדשא\u0004 \u0005[אוציא את כלי בית המקדש]\u0006 \u0003ואשתמש בהו\u0004 \u0005[בהם].\u0006","ושואלים: \u0003ונבוכדנצר, מנלן דארבעין\u0004 \u0005[שארבעים]\u0006 \u0003וחמש שנין\u0004 \u0005[שנים]\u0006 \u0003מלך?\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003גלו בשבע, גלו בשמונה, גלו בשמונה עשרה, גלו בתשע עשרה.\u0004","ומבארים: \u0003גלו בשבע לכיבוש יהויקים\u0004 לאחר שניצח נבוכדנצר את יהויקים ואז היתה \u0003גלות יהויכין, שהיא\u0004 שנת \u0003שמונה לנבוכדנצר. גלו\u0004 פעם אחרת בשנת \u0003שמונה עשרה לכיבוש יהויקים\u0004 היא \u0003גלות צדקיהו שהיא\u0004 שנת \u0003תשע עשרה לנבוכדנצר,\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003שנה ראשונה\u0004 של מלכותו \u0003כיבש\u0004 נבוכדנצר את \u0003נינוה, שניה כיבש יהויקים. וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויהי בשלשים ושבע שנה לגלות יהויכן מלך יהודה בשנים עשר חדש בעשרים וחמשה לחדש נשא אויל מרדך מלך בבל בשנת מלכתו את ראש יהויכין מלך יהודה ויצא אתו מבית הכלוא\"\u0004 (ירמיהו נב, לא) ומעתה נחשב: כיוון שעשה זאת בשנת מלכותו, מיד כשעלה לשלטון, הרי","\u0003תמני\u0004 \u0005[שמונה]\u0006 שנים של נבוכדנצר לפני שהגלה את יהויכין \u0003ותלתין\u0004 \u0005[ושלושים]\u0006 \u0003ושבע\u0004 שנים שהיה בכלא — \u0003הרי ארבעים וחמש\u0004 של \u0003נבוכדנצר. ועשרין ותלת\u0004 \u0005[ועשרים ושלוש]\u0006 שנים שמלך \u0003אויל מרודך\u0004 — דבר זה נלמד מ\u0003גמרא\u0004 \u0005[\u0006מן \u0005המסורת]\u0006 \u0003ותרתי דידיה\u0004 \u0005[ושתיים שלו]\u0006 של בלשצר — \u0003הא שבעין\u0004 \u0005[הרי שבעים].\u0006 \u0003אמר: השתא\u0004 \u0005[עכשיו]\u0006 \u0003ודאי תו לא מיפרקי, אפיק מאני דבי מקדשא\u0004 \u0005[שוב אינם נגאלים, אוציא\u0006 איפוא את \u0005כלי בית המקדש]\u0006 \u0003ואשתמש בהו\u0004 \u0005[בהם].\u0006","\u0003היינו דקאמר ליה\u0004 \u0005[\u0006ו\u0005זהו שאמר לו]\u0006 \u0003דניאל: \"ועל מרי שמיא\u0004 \u0005[אדון השמים]\u0006 \u0003התרוממת ולמאניא די ביתיה היתיו קדמך\u0004 \u0005[ואת כלי ביתו הביאו לפניך]\u0006\u0003\"\u0004 (דניאל ה, כג) \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"בה בליליא קטיל בלשאצר מלכא כשדאי\"\u0004 \u0005[בו בלילה נהרג בלשאצר מלך הכשדים]\u0006 (דניאל ה, ל). זה היה חשבונו המוטעה של בלשאצר, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 אחר מפלת בלשצר: \u0003\"ודריוש מדאה קבל מלכותא כבר שנין שתין ותרתין\"\u0004 \u0005[ודריוש המדי קיבל את המלוכה כבן שישים ושתיים שנה]\u0006 (דניאל ו, א)","\u0003אמר\u0004 אחשורוש: \u0003איהו מיטעא טעי, אנא חשיבנא ולא טעינא\u0004 \u0005[הוא,\u0006 בלשאצר, \u0005טעה, אני אחשב ולא אטעה].\u0006 \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"למלכות בבל\"? \"לבבל\" כתיב\u0004 \u0005[נאמר],\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לבבל\"?\u0004 הכוונה היא \u0003לגלות בבל, כמה\u0004 שנים \u0003בצירן\u0004 \u0005[חסרות]\u0006 — \u0003תמני\u0004 \u0005[שמונה]\u0006 שנים, \u0003חשיב ועייל חילופייהו\u0004 \u0005[חישב והכניס במקומן],\u0006 \u0003חדא\u0004 \u0005[אחת]\u0006 של \u0003בלשאצר וחמש\u0004 של \u0003דריוש וכורש, ותרתי דידיה\u0004 \u0005[ושתים שלו] —\u0006 \u0003הא שבעין\u0004 \u0005[הרי שבעים].\u0006 \u0003כיון דחזי דמלו שבעין\u0004 \u0005[שראה שמלאו שבעים]\u0006 \u0003ולא איפרוק\u0004 \u0005[נפדו,\u0006 נגאלו\u0005] —\u0006 \u0003אמר: השתא\u0004 \u0005[עכשיו]\u0006 \u0003ודאי תו לא מיפרקי\u0004 \u0005[שוב לא יגאלו],\u0006 \u0003אפיק מאני דבי מקדשא\u0004 \u0005[אוציא כלי בית המקדש]\u0006 \u0003ואשתמש בהו\u0004 \u0005[בהם].\u0006 ומה היה לו — שכעונש על כך \u0003בא שטן וריקד ביניהן\u0004 והתבלבלה שמחתו עד ש\u0003הרג את ושתי.\u0004","ושואלים: \u0003והא שפיר חשיב\u0004 \u0005[והרי יפה חשב]\u0006 ומדוע אירע כך? ומשיבים: \u0003איהו נמי מיטעא טעי\u0004 \u0005[הוא גם כן טעה]\u0006 בדבר, \u0003דאיבעי ליה למימני\u0004 \u0005[שהיה לו למנות]\u0006 \u0003מחרבות ירושלים\u0004 שנחרבה עם גלות צדקיהו ולא מזמן הגלות הראשונה של יהויכין.","ושואלים: \u0003סוף סוף כמה\u0004 שנים \u0003בצירן\u0004 \u0005[חסרות]\u0006 לכך? — \u0003חדיסר\u0004 \u0005[אחת עשרה],\u0006 \u0003איהו\u0004 \u0005[הוא]\u0006 אחשורוש \u0003כמה\u0004 שנים \u0003מלך? — ארביסר\u0004 \u0005[ארבע עשרה],\u0006 \u0003בארביסר דידיה איבעי ליה למיבני\u0004 \u0005[ב\u0006שנת ה\u0005ארבע עשרה שלו היה צריך לבנות]\u0006 את \u0003בית המקדש,\u0004 ואם כן \u0003אלמה כתיב\u0004 \u0005[מדוע נאמר]:\u0006 \u0003\"באדין בטלת עבידת בית אלהא די בירושלם\u0004 והות בטלא עד שנת תרתין \u0005[אז בטלה עבודת בית האלהים אשר בירושלים והיתה בטלה עד שנת שתים]\u0006 למלכות דריוש מלך פרס\u0003\"\u0004 (עזרא ד, כד), הרי לא נבנה המקדש כל זמנו של אחשורוש? \u0003אמר רבא: שנים מקוטעות הוו\u0004 \u0005[היו],\u0006 השנים הללו של המלכים לא היו שנים שלימות, אלא נכנסות זו בתוך זו, ומשום כך להשלמת חשבון שבעים שנה יש צורך להוסיף עוד למעלה משנה, ואכן אז נסתיים בנין הבית."],["\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 בריייתא \u0005גם כן כך]:\u0006 \u0003ועוד שנה אחרת לבבל\u0004 להשלים שבעים שנה \u0003ועמד דריוש והשלימה.\u0004 ואחריו בא כורש.","\u0003אמר רבא: אף דניאל טעה בהאי חושבנא\u0004 \u0005[בחשבון זה],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בשנה אחת למלכו אני דניאל בינתי בספרים\u0004 מספר השנים אשר היה דבר ה' אל ירמיה הנביא למלאות לחרבות ירושלים שבעים שנה\u0003\"\u0004 (דניאל ט, ב), \u0003מדקאמר\u0004 \u0005[ממה שאמר]\u0006 \u0003\"בינתי\" — מכלל\u0004 הדברים אתה למד ש\u0003טעה\u0004 קודם.","ומעירים: \u0003מכל מקום קשו קראי אהדדי\u0004 \u0005[קשים הפסוקים זה על זה],\u0006 שהרי באחד \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"מלאת לבבל\"\u0004 (ירמיהו כט, י), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 באחר: \u0003\"לחרבות ירושלים\"\u0004 (דניאל ט, ב)!","\u0003אמר רבא:\u0004 שבעים שנה \"למלאות לבבל\" היה — \u0003לפקידה בעלמא\u0004 \u0005[בלבד],\u0006 לא לבניין בית המקדש אלא לתחילת הגאולה. \u0003והיינו דכתיב\u0004 \u0005[והוא שנאמר]:\u0006 \u0003\"כה אמר כרש מלך פרס: כל ממלכות הארץ נתן לי ה' אלהי השמים והוא פקד עלי לבנות לו בית בירושל ם\"\u0004 (עזרא א, ג) דבר זה היה בשנת שבעים לבבל.","ואגב הזכרת פסוק זה מביאים מה ש\u0003דרש רב נחמן בר רב חסדא: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"כה אמר ה' למשיחו לכורש אשר החזקתי בימינו\"\u0004 (ישעיהו מה, א), \u0003וכי כורש משיח\u0004 (משוח בשמן המשחה) \u0003היה? אלא אמר לו הקדוש ברוך הוא למשיח: קובל אני לך\u0004 (לפניך) \u0003על כורש,\u0004 וצריך להבין את הפסוק כך: \"כה אמר ה' למשיחו\" ומה אמר לו למשיח — הרי אני מספר לך על כורש, ש\u0003אני אמרתי: הוא יבנה את ביתי ויקבץ גליותי\u0004 ממש, והוא לא עשה כן, אלא \u0003והוא אמר: \"מי בכם מכל עמו ויעל\u0004 לירושלים\u0003\"\u0004 (עזרא א, ג) שנתן רשות לעלות ולא עשה יותר מזה.","ושוב חוזרים לפירוש המגילה, נאמר בה: \u0003\"חיל פרס ומדי הפרתמים\"\u0004 (אסתר א, ג), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"למלכי מדי ופרס\"\u0004 (אסתר י, ב), מדוע בפסוק אחד נסמכו הפרתמים (שהם השרים) למדי, כאילו בידי המדיים היו תפקידי השרים, ואילו בפסוק האחר נסמכה המלוכה למדי? \u0003אמר רבא:\u0004 התפקידים הללו אכן לא היו קבועים בידי עם מסויים, אלא \u0003אתנויי אתנו בהדדי\u0004 \u0005[התנו\u0006 שני העמים, הפרסי והמדי, \u0005זה עם זה]:\u0006 \u0003אי מינן מלכי\u0004 \u0005[אם מאיתנו\u0006 יהיו \u0005המלכים] —\u0006 \u0003מינייכו איפרכי\u0004 \u0005[\u0006יהיו \u0005מכם השרים]\u0006 \u0003ואי מינייכו מלכי\u0004 \u0005[ואם מכם\u0006 יהיו \u0005המלכים]\u0006 — \u0003מינן איפרכי\u0004 \u0005[מאיתנו\u0006 יהיו \u0005השרים].\u0006","נאמר במגילה: \u0003\"בהראתו את עשר כבוד מלכותו\u0004 ואת יקר תפארת גדולתו\u0003\"\u0004 (אסתר א, ד), \u0003אמר ר' יוסי בר חנינא: מלמד שלבש\u0004 אחשורוש \u0003בגדי כהונה,\u0004 והראיה לכך: \u0003כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"יקר תפארת גדולתו\" וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בבגדי כהונה: \u0003\"לכבוד ולתפארת\"\u0004 (שמות כח, ב), הרי שבגדי כהונה הם \"תפארת\" ללובשיהם.","נאמר במגילה: \u0003\"ובמלואת הימים האלה\u0004 עשה המלך לכל העם הנמצאים בשושן הבירה משתה\u0003\"\u0004 (אסתר א, ה), \u0003רב ושמואל\u0004 נחלקו בדבר: \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 עיתוי המשתה שערך אחשורוש לבני שושן הבירה, מורה על כך ש\u0003מלך פיקח היה, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 דווקא מדבר זה עצמו נראה ש\u0003מלך טיפש היה. מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי דבר זה מורה על כך ש\u0003מלך פיקח היה,\u0004 סבור הוא ש\u0003שפיר עבד דקריב רחיקא ברישא\u0004 \u0005[טוב עשה שקירב את הרחוקים\u0006 ממנו \u0005תחילה],\u0006 \u0003דבני מאתיה כל אימת דבעי מפייס להו\u0004 \u0005[שבני עירו כל זמן שירצה יפייס אותם]\u0006 ולכן צריך לכבד ולפייס תחילה את הרחוקים, \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 ש\u0003טיפש היה —\u0004 סבור הוא \u0003דאיבעי ליה לקרובי בני מאתיה ברישא\u0004 \u0005[שצריך היה לקרב את בני עירו תחילה]\u0006 \u0003דאי מרדו ביה הנך, הני הוו קיימי בהדיה\u0004 \u0005[שאם ימרדו בו אלה\u0006 הרחוקים, הרי \u0005אלה\u0006 הקרובים \u0005יעמדו עמו]\u0006 ואם יהיה להיפך, הרי יאבד בינתיים.","\u0003שאלו תלמידיו של ר' שמעון בר יוחאי: מפני מה נתחייבו שונאיהן של ישראל\u0004 (בלשון נקיה, כלומר: ישראל) \u0003שבאותו הדור כליה\u0004 עד שנגזרה עליהם גזירה זו? \u0003אמר להם: אמרו אתם. אמרו לו: מפני שנהנו מסעודתו של אותו רשע\u0004 אחשורוש, ואכלו בה דברים אסורים. אמר להם: \u0003אם כן\u0004 צריך היה להיות העונש שאלה \u0003שבשושן\u0004 שהשתתפו בסעודה — \u0003יהרגו,\u0004 אבל אלה \u0003שבכל העולם כולו\u0004 שלא השתתפו בה \u0003אל יהרגו! אמרו לו: אמור אתה! אמר להם: מפני שהשתחוו לצלם\u0004 שעשה נבוכדנצר, שמסופר שבני כל העולם השתחוו לו, חוץ מחנניה מישאל ועזריה.","\u0003אמרו לו:\u0004 אם כן, שעבדו עבודה זרה \u0003וכי משוא פנים יש בדבר\u0004 שבכל זאת בסופו של דבר נעשה להם נס וניצלו? \u0003אמר להם: הם לא עשו\u0004 עבודה זרה \u0003אלא לפנים\u0004 (למראית העין) עשו כדבר המלך והשתחוו — \u0003אף הקדוש ברוך הוא לא עשה עמהן אלא לפנים,\u0004 שהרי לא היה זה אלא איום בלבד ובסופו של דבר בטלה הגזירה. \u0003והיינו דכתיב\u0004 \u0005[וזהו שנאמר]:\u0006 \u0003\"כי לא ענה מלבו\"\u0004 (איכה ג, לג) אלא למראית העין.","ועוד נאמר במגילה: \u0003\"בחצר גנת ביתן המלך\"\u0004 (אסתר א, ה), \u0003רב ושמואל\u0004 נחלקו בדבר, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 שהיו במקומות שונים, שמי שהיה לפי מעלתו \u0003ראוי לחצר\u0004 — הביאו אותו \u0003לחצר,\u0004 ו\u0003הראוי לגינה\u0004 — הביאו אותו \u0003לגינה, הראוי לביתן — לביתן. וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: הושיבן בחצר ולא החזיקתן,\u0004 שהיו מרובים ולא הספיק המקום, ולכן הושיבם \u0003בגינה ו\u0004אף זו \u0003לא החזיקתן, עד שהכניסן לביתן והחזיקתן.\u0004 ואילו \u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]\u0006 כדי להסביר: \u0003הושיבן בחצר ופתח להם שני פתחים, אחד לגינה ואחד לביתן\u0004 וכך מתקיים הפסוק במלואו.","נאמר במגילה: \u0003\"חור כרפס ותכלת\"\u0004 (אסתר ג, ו). ושאלו: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"חור\"? רב אמר:\u0004 אריג העשוי \u0003חרי חרי\u0004 \u0005[חורים חורים]\u0006 כמין תחרה, \u0003ושמואל אמר: מילת לבנה\u0004 \u0005[צמר לבן נקי]\u0006 \u0003הציע להם,\u0004 ו\"חור\" מלשון חיוור — לבן. \u0003\"כרפס\" — אמר ר' יוסי בר חנינא:\u0004 פירוש הביטוי הוא \u0003כרים של פסים.\u0004","נאמר: \u0003\"על גלילי כסף ועמודי שש מטות זהב וכסף\"\u0004 (אסתר ג, ו), \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר: הראוי לכסף\u0004 ישב על מיטת \u0003כסף, הראוי לזהב — לזהב. אמר לו ר' נחמיה:\u0004 אין עושים כן, ש\u0003אם כן אתה מטיל קנאה בסעודה\u0004 שמקנאים אלה באלה, \u0003אלא, הם\u0004 המיטות עצמן היו \u0003של כסף, ורגליהן של זהב\u0004 ונתקיים בהן \"מיטות זהב וכסף\" ביחד.","נאמר שם: \u0003\"בהט ושש\"\u0004 (אסתר ג, ו). \u0003אמר רב אסי:\u0004 \"בהט\" — נדרש כמו בחט, אלו \u0003אבנים שמתחוטטות על בעליהן,\u0004 אבנים יקרות שגורמות לבעליהן שיחטטו ויחפשו אחריהן, וישלמו תמורתן הון רב. \u0003וכן הוא אומר\u0004 כיוצא בו על גדולת ישראל לעתיד, שיהיו בעיני העמים כ\u0003\"אבני נזר מתנוססות על אדמתו\"\u0004 (זכריה ט, טז), ומשמעות הביטוי \"מתנוססות\" הוא מלשון נסיונות, לומר, שאבנים יקרות אינם נמצאות אלא על ידי נסיונות ומאמצים רבים.","\u0003\"ודר וסחרת\"\u0004 (אסתר א, ו), \u0003רב אמר:\u0004 \"דר\" פירושו: \u0003דרי דרי\u0004 \u0005[שורות שורות]\u0006 מסביב, וכן פירוש \"סוחרת\", מלשון סחור־סחור. \u0003ושמואל אמר: אבן טובה יש בכרכי הים ו\"דרה\" שמה,\u0004 ו\u0003הושיבה באמצע סעודה ומאירה\u0004 היתה \u0003להם כצהרים.\u0004 (ו\"סוחרת\" מלשון סהר = צהר). \u0003דבי\u0004 \u0005[\u0006חכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה],\u0006 שכוונת הדבר \u0003שקרא דרור לכל בעלי סחורה\u0004 שהניח להם מן המיסים (\"דר וסוחרת\").","נאמר: \u0003\"והשקות בכלי זהב וכלים מכלים שונים\"\u0004 (אסתר א, ז), ושואלים: מדוע נקט בלשון \"שונים\" — \u0003\"משונים\" מיבעי ליה\u0004 \u0005[צריך\u0006 היה \u0005לו\u0006 לומר\u0005]!\u0006 \u0003אמר רבא: יצתה\u0004 (יצאה) \u0003בת קול ואמרה להם: ראשונים,\u0004 כלומר: בלשצר ואנשיו, \u0003כלו מפני\u0004 שהשתמשו ב\u0003כלים\u0004 אלה, כלי המקדש, \u0003ואתם שונים\u0004 (חוזרים ומשתמשים) \u0003בהם?\u0004 נאמר: \u0003\"ויין מלכות רב\"\u0004 (אסתר א, ז), \u0003אמר רב: מלמד שכל אחד ואחד\u0004 מאורחי המשתה \u0003השקהו\u0004 אחשורוש \u0003יין שגדול\u0004 (רב) \u0003הימנו בשנים,\u0004 כלומר יין ישן ביותר.","נאמר: \u0003\"והשתיה כדת אין אנס\"\u0004 (אסתר א, ח) ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כדת\"? אמר ר' חנן משום\u0004 (בשם) \u0003ר' מאיר: כדת של תורה\u0004 היתה השתיה כאן, \u0003מה דת של תורה,\u0004 בדיני הקרבנות — \u0003אכילה\u0004 של המזבח \u0003מרובה משתיה\u0004 שנסכי היין מבחינת הכמות מעטים הרבה מן הקרבן והמנחה — \u0003אף סעודתו של אותו רשע\u0004 היתה בה \u0003אכילה מרובה משתיה.\u0004","נאמר: \u0003\"אין אנס\" אמר ר' אלעזר: מלמד שכל אחד ואחד השקהו מיין מדינתו\u0004 שירגיש עצמו כאילו הוא במדינתו שלו. נאמר: \u0003\"לעשות כרצון איש ואיש\"\u0004 (אסתר א, ח), \u0003אמר רבא:\u0004 הכוונה היא \u0003לעשות כרצון מרדכי והמן,\u0004 ששניהם היו שרי המשקים באותו משתה וחלוקת היין התבצעה על פיהם. ומדוע מפרשים כך? \u0003מרדכי\u0004 נקרא \"איש\" \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"איש יהודי\u0004 היה בשושן הבירה ושמו מרדכי בן יאיר\u0003\"\u0004 (אסתר ב, ה), ו\u0003המן\u0004 אף הוא נקרא \"איש\", שכן נאמר: \u0003\"איש צר ואויב\u0004 המן הרע הזה\u0003\"\u0004 (אסתר ז, ו).","נאמר: \u0003\"גם ושתי המלכה עשתה משתה נשים בית המלכות\u0004 אשר למלך אחשורוש\u0003\"\u0004 (אסתר א, ט) ושואלים: מדוע עשתה משתה בבית המלכות שהוא לכאורה מקום הגברים? הרי \u0003\"בית הנשים\" מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 להיות, ששם היתה צריכה לעשות את המשתה! \u0003אמר רבא: שניהן לדבר עבירה נתכוונו\u0004 כלומר, גם אחשורוש רצה לנאוף עם נשים וגם היא רצתה לנאוף עם גברים, \u0003היינו דאמרי אינשי\u0004 \u0005[הוא שאומרים אנשים\u0006 בפתגם מקובל\u0005]:\u0006 \u0003איהו בקרי ואתתיה\u0004"],["\u0003בבוציני\u0004 \u0005[הוא בדלעות ואשתו בקישואים],\u0006 כלומר, הבעל והאשה עושים דברים זה בדומה לזה, ואף כאן שניהם התכוונו לעבירה.","נאמר: \u0003\"ביום השביעי כטוב לב המלך ביין\"\u0004 (אסתר א, י), ותוהים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003עד השתא\u0004 \u0005[עכשיו]\u0006 \u0003לא טב לביה בחמרא\u0004 \u0005[\u0006היה \u0005טוב ליבו ביין],\u0006 והוצרך לשבעה ימים לשם כך? \u0003אמר רבא: יום השביעי\u0004 יום \u0003שבת היה,\u0004 ובו ניכר ההבדל בין ישראל לעמים. שביום השבת, כ\u0003שישראל אוכלין ושותין, מתחילין\u0004 אז לעסוק \u0003בדברי תורה ובדברי תשבחות\u0004 לה', \u0003אבל אומות העולם\u0004 כ\u0003שאוכלין ושותים, אין מתחילין אלא בדברי תיפלות\u0004 (ניאוף).","\u0003וכן בסעודתו של אותו רשע\u0004 כשהתחילו לדבר היו \u0003הללו אומרים: מדיות\u0004 הן ה\u0003נאות\u0004 שבנשים, \u0003והללו אומרים: פרסיות נאות, אמר להם אחשורוש: כלי שאני משתמש בו\u0004 (כלומר, אשתי) \u0003אינו לא מדיי ולא פרסי אלא כשדיי,\u0004 וכי \u0003רצונכם לראותה? אמרו לו: אין\u0004 \u0005[כן]\u0006 \u0003ובלבד שתהא ערומה,\u0004 משום שאנו רוצים לראות אותה בלא קישוטים נוספים.","מעירים: מדוע נענשה בבזיון זה — \u0003שבמדה ש\u0004בה \u0003אדם מודד בה מודדין לו, מלמד שהיתה ושתי הרשעה מביאה בנות ישראל ומפשיטתן ערומות ועושה בהן מלאכה בשבת,\u0004 וכנגד זה נגזר עליה שתבוא בשבת כשהיא ערומה. ומעירים: \u0003והיינו דכתיב\u0004 \u0005[והוא שנאמר]:\u0006 \u0003\"אחר הדברים האלה כשך חמת המלך אחשורוש זכר את ושתי ואת אשר עשתה ואת אשר נגזר עליה\"\u0004 (אסתר ב, א), כלומר, \u0003כשם שעשתה\u0004 בבנות ישראל — \u0003כך נגזר עליה.\u0004","נאמר: \u0003\"ותמאן המלכה ושתי\"\u0004 (אסתר א, יב), ושואלים: \u0003מכדי פריצתא הואי\u0004 \u0005[הלא פרוצה היתה]\u0006 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003שניהן לדבר עבירה נתכוונו,\u0004 ואם כן \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אתאי\u0004 \u0005[באה]?\u0006 \u0003אמר ר' יוסי בר חנינא: מלמד שפרחה בה צרעת\u0004 ולכן התביישה לבוא. \u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]:\u0006 \u0003בא\u0004 המלאך \u0003גבריאל ועשה לה זנב,\u0004 ולכן התביישה לבוא.","נאמר: \u0003\"ויקצף המלך מאד\u0004 וחמתו בערה בו\u0003\"\u0004 (אסתר א, יב), ושואלים: \u0003אמאי דלקה ביה כולי האי\u0004 \u0005[מדוע בערה בו\u0006 חמתו \u0005כל כך]\u0006 רק משום שלא רצתה לבוא? \u0003אמר רבא: שלחה ליה\u0004 \u0005[לו]\u0006 על ידי שליח: אתה \u0003בר אהורייריה דאבא\u0004 \u0005[בן סייסו\u0006 של \u0005אבי,\u0006 בלשצר\u0005],\u0006 \u0003אבא לקבל אלפא חמרא שתי, ולא רוי\u0004 \u0005[אבי,\u0006 \u0005כנגד אלף\u0006 אנשים \u0005יין שתה, ולא השתכר]\u0006 \u0003וההוא גברא אשתטי בחמריה\u0004 \u0005[ואדם זה\u0006, אתה אחשורוש, \u0005משתטה ביינו],\u0006 ומשום חוצפה זו \u0003מיד \"וחמתו בערה בו\"\u0004 (אסתר א, יב).","נאמר: \u0003\"ויאמר המלך לחכמים\u0004 יודעי העיתים\u0003\"\u0004 (אסתר א, יד) ושואלים: \u0003מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003חכמים\u0004 אלה? ומשיבים: \"חכמים\" אלה הם \u0003רבנן\u0004 (חכמי ישראל)\u0005,\u0006 ומדוע קוראים להם \u0003\"ידעי העתים\" —\u0004 משום \u0003שיודעין לעבר שנים ולקבוע חדשים. אמר\u0004 אחשורוש \u0003להו\u0004 \u0005[להם,\u0006 לחכמים\u0005]:\u0006 \u0003דיינוה לי\u0004 \u0005[שיפטוה עבורי]\u0006 \u0003אמרו\u0004 החכמים בלבם: \u0003היכי נעביד\u0004 \u0005[כיצד נעשה]?\u0006 \u0003נימא ליה\u0004 \u0005[\u0006אם \u0005נאמר לו]:\u0006 \u0003קטלה\u0004 \u0005[הרוג אותה],\u0006 \u0003למחר פסיק ליה חמריה ובעי לה מינן\u0004 \u0005[יפסוק ממנו יינו\u0006 ויבוא \u0005ויתבע אותה מאיתנו].\u0006 \u0003נימא ליה\u0004 \u0005[\u0006אם \u0005נאמר לו]:\u0006 \u0003שבקה\u0004 \u0005[הנח לה], —\u0006 \u0003קא מזלזלה במלכותא\u0004 \u0005[\u0006הרי \u0005היא מזלזלת במלכות]\u0006 ואי אפשר לעשות כן, ולכן החליטו שלא לדון בדבר, ו\u0003אמרו לו\u0004 כך: \u0003מיום שחרב בית המקדש וגלינו מארצנו, ניטלה עצה\u0004 ותבונה \u0003ממנו ואין אנו יודעין לדון דיני נפשות\u0004 שהם קשים ביותר, \u0003זיל לגבי\u0004 \u0005[לך אל]\u0006 בני \u0003עמון ומואב דיתבי בדוכתייהו כחמרא דיתיב על דורדייה\u0004 \u0005[ש\u0006הם \u0005יושבים\u0006 קבועים \u0005במקומותיהם כיין היושב על שמריו]\u0006 והם מיושבים בדעתם.","\u0003וטעמא\u0004 \u0005[וטעם]\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 מן הכתוב, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שאנן מואב מנעוריו ושקט הוא אל שמריו ולא הורק מכלי אל כלי ובגולה לא הלך על כן עמד טעמו בו וריחו לא נמר\"\u0004 (ירמיה מח, יא) \u0003מיד\u0004 עשה כן, \u0003\"והקרב אליו כרשנא שתר אדמתא תרשיש\"\u0004 וכו' (אסתר א, יד),","\u0003אמר ר' לוי: כל פסוק זה על שום\u0004 (ירמיה מח, יא) ה\u0003קרבנות נאמר,\u0004 כלומר, שהוא מרמז על עניין עבודת הקרבנות, וכיצד?","\u0003\"כרשנא\" — אמרו מלאכי השרת לפני הקדוש ברוך הוא: רבונו של עולם, כלום הקריבו לפניך\u0004 הגוים \u0003כרים\u0004 (כבשים) \u0003בני שנה כדרך שהקריבו\u0004 בני \u0003ישראל לפניך? \"שתר\" — כלום הקריבו לפניך שתי תורין? \"אדמתא\" — כלום בנו לפניך מזבח אדמה? \"תרשיש\" — כלום שימשו לפניך בבגדי כהונה דכתיב בהו\u0004 \u0005[שנאמר בהם]:\u0006 \u0003\"תרשיש ושהם וישפה\"\u0004 (שמות כח, כ). \u0003\"מרס\" — כלום מירסו\u0004 (בחשו) \u0003בדם\u0004 הקרבנות \u0003לפניך? \"מרסנא\" — כלום מירסו במנחות לפניך? \"ממוכן\" — כלום הכינו שלחן לפניך?\u0004 כלומר באו להזכיר שצריך לגאול את ישראל.","נאמר: \u0003\"ויאמר ממוכן\"\u0004 (אסתר א, טז) \u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003ממוכן זה המן, ולמה נקרא שמו ממוכן — שמוכן\u0004 היה \u0003לפורענות\u0004 על ישראל. \u0003אמר רב כהנא: מכאן שההדיוט קופץ בראש\u0004 ומדבר ראשון, שהרי ממוכן נמנה האחרון בין השרים, ובכל זאת הוא ענה ראשון.","אחר התייעצות זו שלח המלך אגרות, בהן נאמר: \u0003\"להיות כל איש שרר בביתו\u0004 ומדבר כלשון עמו\u0003\"\u0004 (אסתר א, כב), \u0003אמר רבא\u0004: \u0003אלמלא אגרות הראשונות\u0004 ששלח אחשורוש שאנשים לא קיבלו אותן ברצינות \u0003לא נשתייר משונאיהן של ישראל\u0004 (בלשון נקיה, כלומר מישראל) אפילו \u0003שריד ופליט;\u0004 אלא משום שהאיגרות הראשונות היו נושא של צחוק, אף באחרונות המתינו לראות מה יקרה. ומדוע?","\u0003אמרי\u0004 \u0005[אמרו]\u0006 מקבלי האגרות: \u0003מאי האי דשדיר לן\u0004 \u0005[מה\u0006 הוא \u0005זה ש\u0006הוא \u0005שולח לנו]\u0006 \u0003\"להיות כל איש שרר בביתו\"? פשיטא, אפילו קרחה בביתיה פרדשכא ליהוי\u0004 \u0005[פשוט\u0006 הוא, \u0005אפילו האורג\u0006 הבזוי, \u0005בביתו הוא שר]\u0006 וזה מקובל וידוע לכל, ולשם מה צריך המלך להודיע זאת?","נאמר: \u0003\"ויפקד המלך פקידים\"\u0004 (אסתר ב, ב), \u0003אמר רב: מאי דכתיב\u0004 \u0005[מהו\u0006 \u0005שנאמר]:\u0006 \u0003\"כל ערום יעשה בדעת וכסיל יפרש אולת\"\u0004 (משלי יג, טז) —","\u0003\"כל ערום יעשה בדעת\" — זה דוד\u0004 שגם הוא חיפש לעצמו אשה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמרו לו עבדיו יבקשו לאדני המלך נערה בתולה\"\u0004 (מלכים א' א, ב), וכיון שחיפש נערה אחת — \u0003כל מאן דהוה ליה ברתא, אייתה ניהליה\u0004 \u0005[כל מי שהיתה לו בת, הביא אותה אליו],\u0006 שרצה שתהיה אשת המלך, ולעומת זאת \u0003\"וכסיל יפרש אולת\" — זה אחשורוש, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויפקד המלך פקידים\"\u0004 לבקש נשים רבות, וממילא ידעו שכולן ייבעלו למלך ולבסוף רק אחת מהן תיבחר, ולכן \u0003כל מאן דהוה ליה ברתא איטמרה מיניה\u0004 \u0005[כל מי שהיתה לו בת החביא אותה ממנו].\u0006","נאמר: \u0003\"איש יהודי היה בשושן הבירה\u0004 ושמו מרדכי בן יאיר בן שמעי בן קיש \u0003איש ימיני\"\u0004 (אסתר ב, ה), ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר],\u0006 מה התכוון במנותו את ייחוסו, \u0003אי ליחוסא קאתי\u0004 \u0005[אם לייחסו\u0006 הוא \u0005בא]\u0006 שרוצה למנות את כל שושלת היוחסין — \u0003ליחסיה ואזיל\u0004 \u0005[שייחסנו וילך]\u0006 \u0003עד בנימין\u0004 ראש השבט! \u0003אלא מאי שנא הני\u0004 \u0005[מה שונים\u0006 שמות \u0005אלה]\u0006 שציין?","ומשיבים: \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003כולן על שמו נקראו,\u0004 שהוזכרו כל השמות הללו משום שהם משמשים ככינויים למרדכי: \u0003\"בן יאיר\"\u0004 הוא נקרא משום שהוא \u0003בן שהאיר עיניהם של\u0004 כל \u0003ישראל בתפלתו, \"בן שמעי\" — בן ששמע אל\u0004 (ה') את \u0003תפלתו\u0004 ונענה לו \u0003\"בן קיש\" — שהקיש\u0004 (דפק) \u0003על שערי רחמים ונפתחו לו.\u0004","ועוד שואלים: \u0003קרי ליה\u0004 \u0005[קורא לו]\u0006 \u0003\"יהודי\" — אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003מ\u0004שבט \u0003יהודה קאתי\u0004 \u0005[\u0006הוא \u0005בא],\u0006 \u0003ו\u0004לעומת זאת בהמשך הפסוק \u0003קרי ליה\u0004 \u0005[קורא\u0006 הוא \u0005לו]\u0006 \u0003\"ימיני\" — אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003מ\u0004שבט \u0003בנימין קאתי\u0004 \u0005[\u0006הוא \u0005בא],\u0006 ואם כן סתירה יש בדבר! \u0003אמר רב נחמן: מרדכי מוכתר בנימוסו היה\u0004 שהיו לו תארי כבוד שונים, ואף \"יהודי\" — כינוי של כבוד הוא על שם שבט המלוכה יהודה.","\u0003אמר רבה בר בר חנה אמר ר' יהושע בן לוי: אביו מ\u0004שבט \u0003בנימין ואמו מ\u0004שבט \u0003יהודה\u0004 ולכן היה גם \"איש ימיני\" — מבנימין וגם \"יהודי\" — מיהודה. \u0003ורבנן אמרי\u0004 \u0005[וחכמים אומרים]\u0006 שבעניין זה \u0003משפחות מתגרות זו בזו: משפחת יהודה אומרת — אנא גרים דמתיליד\u0004 \u0005[אני שגרמתי שייוולד]\u0006 \u0003מרדכי,\u0004 ומדוע? \u0003דלא קטליה\u0004 \u0005[שלא הרגו]\u0006 \u0003דוד לשמעי בן גרא\u0004 ויכול היה מרדכי להיוולד מאוחר יותר מבני בניו. \u0003ומשפחת בנימין אמרה:\u0004 סוף סוף \u0003מינאי קאתי\u0004 \u0005[ממני,\u0006 ממשפחתי \u0005הוא בא].\u0006","\u0003רבא אמר: כנסת ישראל אמרה לאידך גיסא\u0004 \u0005[לצד אחר],\u0006 כלומר, לא בהתפארות אלא בתלונה: \u0003ראו מה עשה לי יהודי ומה שילם לי ימיני. מה עשה לי יהודי\u0004"],["\u0003דלא קטליה\u0004 \u0005[שלא הרגו]\u0006 \u0003דוד לשמעי\u0004 למרות שהיה חייב מיתה, ומה גרם — \u0003דאתיליד מיניה\u0004 \u0005[שנולד ממנו]\u0006 \u0003מרדכי דמקני ביה\u0004 \u0005[שקינא בו]\u0006 \u0003המן\u0004 ולולי זאת לא היתה הגזירה באה. \u0003ומה שילם לי ימיני — דלא קטליה\u0004 \u0005[שלא הרגו]\u0006 \u0003שאול\u0004 (משבט בנימין) \u0003לאגג, דאתיליד מיניה\u0004 \u0005[שנולד ממנו]\u0006 \u0003המן\u0004 שהיה \u0003מצער לישראל.\u0004","\u0003ר' יוחנן אמר\u0004 דבר אחר: \u0003לעולם\u0004 תפרש שמרדכי \u0003מבנימן קאתי\u0004 \u0005[הוא בא],\u0006 \u0003ואמאי קרי ליה\u0004 \u0005[ומדוע קורא לו]\u0006 \u0003\"יהודי\" — על שום\u0004 (אסתר ב, ה) \u0003שכפר בעבודה זרה,\u0004 ודורש \"יהודי\" כמו יחודי, \u0003שכל הכופר בעבודה זרה נקרא \"יהודי\", כדכתיב\u0004 \u0005[כפי שנאמר]:\u0006 \u0003\"איתי גברין יהודאין...\u0004 שדרך מישך ועבד נגו...\u0003\"\u0004 (דניאל ג, יב) \u0005[יש אנשים יהודים...\u0006 חנניה מישאל ועזריה\u0005]\u0006 ולא כולם היו משבט יהודה.","אגב דרשת \"יהודי\" מלשון יחוד מביאים: \u0003ר' שמעון בן פזי, כי הוה פתח\u0004 \u0005[כאשר היה פותח]\u0006 ללמד את ספר \u0003דברי הימים, אמר הכי\u0004 \u0005[\u0006היה \u0005אומר כך]:\u0006 \u0003כל דבריך,\u0004 אתה ספר דברי הימים — \u0003אחד הם, ואנו יודעין לדורשן.\u0004 כלומר, הדברים הכתובים שם אינם יכולים להיות מובנים תמיד כפשוטם. וכגון שמות האנשים המוזכרים, שאף שיש שם כמה וכמה שמות שונים, יש לומר שהכוונה לאדם אחד ועלינו לדרוש שאותו אדם נקרא בכמה וכמה שמות, כגון הפסוק: \u0003\"ואשתו היהדיה ילדה את ירד אבי גדור ואת חבר אבי שוכו ואת יקותיאל אבי זנוח ואלה בני בתיה בת פרעה אשר לקח מרד\"\u0004 (דברי הימים א' ד, יח).","\u0003אמאי קרי\u0004 \u0005[מדוע קורא]\u0006 \u0003לה\u0004 לבת פרעה \u0003\"\u0004אשתו \u0003היהדיה\" — על שום שכפרה בעבודה זרה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ותרד בת פרעה לרחוץ על היאור\"\u0004 (שמות ב, ה), \u0003ואמר ר' יוחנן: שירדה לרחוץ\u0004 ולהיטהר \u0003מגילולי\u0004 (אלילי) \u0003בית אביה.\u0004","ושואלים: אם הכוונה היא למשה, איך אפשר לומר שהיא \u0003ילדה\u0004 את משה? \u0003והא רבויי רביתיה\u0004 \u0005[הרי\u0006 היא רק \u0005גידלה אותו]?\u0006 אלא \u0003לומר לך: שכל המגדל יתום\u0004 או \u0003יתומה בתוך ביתו — מעלה עליו\u0004 (מחשיב לו) \u0003הכתוב כאילו ילדו.\u0004","\u0003\"ירד\" — זה משה, ולמה נקרא שמו \"ירד\" — שירד להם לישראל מן בימיו.\u0004 נקרא \u0003\"גדור\"\u0004 — על שם \u0003שגדר פרצותיהן של ישראל. \"חבר\" — שחיבר את ישראל לאביהן שבשמים. \"סוכו\" — שנעשה להם לישראל כסוכה\u0004 ומגן. \u0003\"יקותיאל\" — שקוו ישראל לאל בימיו. \"זנוח\" — שהזניח\u0004 (השכיח) \u0003עונותיהן של ישראל.\u0004","ועוד נאמר שם שלוש פעמים \u0003\"אבי\" \"אבי\" \"אבי\"\u0004 (\"ובני אשת הודיה אחות נחם אבי קעילה הגרמי... ער אבי לכה ולעדה אבי מרשה...\". דברי הימים א' ד, יט-כא), הרי זה בא ללמד שמשה היה אב בשלושה דברים: \u0003אב\u0004 לכל ישראל \u0003בתורה, אב בחכמה, אב בנביאות.\u0004","נאמר: \u0003\"ואלה בני בתיה אשר לקח מרד\"\u0004 (דברי הימים א' ד, יח) \u0003וכי מרד שמו? והלא כלב שמו,\u0004 אלא \u0003אמר הקדוש ברוך הוא: יבא כלב שמרד בעצת מרגלים\u0004 ועל כן הוא מכונה \"מרד\", \u0003וישא את בת פרעה\u0004 שאף היא מורדת \u0003שמרדה בגלולי בית אביה.\u0004","ושוב לענין המגילה, נאמר במרדכי: \u0003\"אשר הגלה מירושלים\"\u0004 (אסתר ב, ו), \u0003אמר רבא:\u0004 יש לפרש \u0003שגלה מעצמו,\u0004 שידע שיצטרכו לו שם, וגלה מעצמו לטפל בענייני כלל ישראל.","נאמר: \u0003\"ויהי אמן את הדסה\"\u0004 (אסתר ב, ז), \u0003קרי\u0004 \u0005[קורא]\u0006 \u0003לה \"הדסה\" וקרי\u0004 \u0005[וקורא לה]\u0006 \u0003לה \"אסתר\",\u0004 ומה אם כן שמה הנכון? \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' מאיר אומר: אסתר שמה\u0004 האמיתי, \u0003ולמה נקרא שמה הדסה —\u0004 כינוי הוא, \u0003על שם הצדיקים שנקראו \"הדסים\". וכן הוא אומר: \"והוא עמד בין ההדסים\"\u0004 (זכריה א, ח).","\u0003ר' יהודה אומר: הדסה שמה\u0004 האמיתי, \u0003ולמה נקרא שמה אסתר? על שם שהיתה מסתרת דבריה, שנאמר: \"אין אסתר מגדת את עמה\"\u0004 (אסתר ב, כ),","\u0003ר' נחמיה אומר: הדסה שמה\u0004 האמיתי, \u0003ולמה נקראת אסתר —\u0004 שם לועזי הוא, \u0003שהיו אומות העולם קורין אותה על שום\u0004 יופיה \u0003אסתהר\u0004 = כוכב נוגה. \u0003בן עזאי אומר: אסתר, לא ארוכה\u0004 (גבוהה) \u0003ולא קצרה\u0004 (נמוכה) \u0003היתה, אלא בינונית כהדסה,\u0004 כמו עץ ההדס, ולכן נקראת הדסה. ו\u0003ר' יהושע בן קרחה אמר:\u0004 למה נקראה הדסה — משום ש\u0003אסתר ירקרוקת\u0004 (חיוורת) \u0003היתה\u0004 כהדס, אלא ש\u0003חוט של חסד משוך עליה\u0004 והוא שגרם שתיחשב יפה כל כך.","נאמר \u0003\"כי אין לה אב ואם\"\u0004 (אסתר ב, ז), החזרה \u0003\"ובמות אביה ואמה\"\u0004 (אסתר ב, ז) \u0003למה לי? אמר רב אחא:\u0004 הכוונה היא שכש \u0003עיברתה\u0004 אמה — \u0003מת אביה,\u0004 כש\u0003ילדתה מתה אמה\u0004 ואפילו יום אחד לא היה לה אב ואם.","נאמר: \u0003\"ובמות אביה ואמה לקחה מרדכי לו לבת\"\u0004 (אסתר ב, ז), \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 \u0003משום\u0004 (בשם) \u0003ר' מאיר: אל תקרי \"לבת\" אלא לבית.\u0004 כלומר, בסופו של דבר לקח אותה לו לאשה. \u0003וכן הוא אומר: \"ולרש אין כל כי אם כבשה אחת קטנה אשר קנה ויחיה ותגדל עמו ועם בניו יחדו מפתו תאכל ומכסו תשתה ובחיקו תשכב ותהי לו כבת\"\u0004 (שמואל ב' יב, ג), \u0003משום\u0004 ש\u0003בחיקו תשכב הוות ליה\u0004 \u0005[היתה לו]\u0006 \u0003לבת? אלא\u0004 הכוונה — \"בת\" בלשון נקיה, ועניינו כ\u0003בית —\u0004 כאשה, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 \"לבת\" משמעו \u0003לבית.\u0004","נאמר: \u0003\"ואת שבע הנערות\u0004 הראויות לתת לה מבית המלך\u0003\"\u0004 (אסתר ב, ט), \u0003אמר רבא: שהיתה\u0004 משתמשת בהן בכך שהיתה \u0003מונה בהן ימי שבת,\u0004 שנתנה לכל נערה להיות עמה רק יום אחד בשבוע, ולפי זה היתה יודעת מתי חל יום השבת. נאמר: \u0003\"וישנה ואת נערותיה\u0004 לטוב \u0003\"\u0004\u0003אמר רב: שהאכילה מאכל יהודי\u0004 והוא השינוי לטוב.","\u0003ושמואל אמר:\u0004 שעשה לה טוב לפי דעתו \u0003שהאכילה קדלי דחזירי\u0004 \u0005[עורפי חזירים].\u0006","\u0003ור' יוחנן אמר:\u0004 נתן לה \u0003זרעונים\u0004 שהם מאכל כשר, \u0003וכן הוא אומר\u0004 בדניאל וחבריו שעשו להם טובה: \u0003\"ויהי המלצר נושא את פת־בגם\u0004 ויין משתיהם \u0003ונתן להם זרעונים\"\u0004 (דניאל א, טז).","נאמר: \u0003\"ששה חדשים בשמן המר\"\u0004 (אסתר ב, יב), ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"שמן המור\"? ר' חייא בר אבא אמר:\u0004 הוא שמן הבושם הנקרא \u0003סטכת, רב הונא אמר:\u0004 זה הוא \u0003שמן\u0004 שמוציאים מפרי \u0003זית שלא הביא\u0004 (גדל) \u0003שליש\u0004 ומשמש לתמרוקים. ובדומה לזה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' יהודה אומר: אנפקינון\u0004 הוא \u0003שמן זית שלא הביא שליש, ולמה סכין אותו\u0004 — מפני שהוא \u0003משיר את השיער ומעדן את הבשר.\u0004","נאמר: \u0003\"בערב היא באה ובבקר היא שבה\"\u0004 (אסתר ב, יד), \u0003אמר ר' יוחנן: מגנותו של אותו רשע\u0004 שהיה מרבה נשים כל כך \u0003למדנו\u0004 בדרך אגב גם \u0003שבחו — שלא היה משמש מטתו ביום\u0004 אלא בדרך צניעות, בלילה.","נאמר: \u0003\"ותהי אסתר נשאת חן\u0004 בעיני כל רואיה\u0003\"\u0004 (אסתר ב, טו), \u0003אמר ר' אלעזר: מלמד שלכל אחד ואחד נדמתה לו כאומתו,\u0004 ומשום כך נשאה חן מלפני כולם. נאמר: \u0003\"ותלקח אסתר אל המלך אחשורוש אל בית מלכותו בחדש העשירי הוא חדש טבת\"\u0004 (אסתר ב, טז), ואומרים שמשמים היה הדבר, משום שהוא חודש קר ולכן הוא \u0003ירח\u0004 (חודש) \u0003שנהנה גוף מן הגוף.\u0004","נאמר: \u0003\"ויאהב המלך את אסתר מכל הנשים ותשא חן וחסד לפניו מכל הבתולות\"\u0004 (אסתר ב, יד) \u0003אמר רב:\u0004 כוונתו, שאם \u0003ביקש לטעום\u0004 בה \u0003טעם בתולה — טעם, טעם\u0004 אשה \u0003בעולה — טעם,\u0004 ולכן אהב אותה מכולן.","נאמר: \u0003\"ויעש המלך משתה גדול\u0004 לכל שריו ועבדיו את משתה אסתר\u0003\"\u0004 (אסתר ב, יח) ומסבירים: \u0003עבד משתיא ולא גליא לה\u0004 \u0005[עשה משתה\u0006 גדול לכבודה \u0005ולא גילתה לו]\u0006 את מוצאה, \u0003דלי כרגא ולא גליא ליה\u0004 \u0005[הפחית מן המסים\u0006 בשמה \u0005ולא גילתה לו],\u0006 \u0003שדר פרדישני ולא גליא ליה\u0004 \u0005[שלח מתנות לשרים\u0006 בשמה \u0005ולא גילתה לו].\u0006","נאמר: \u0003\"ובהקבץ בתולות שנית\"\u0004 (אסתר ב, יט), למה עשה כן? \u0003אזיל שקל\u0004 \u0005[הלך\u0006 ו\u0005נטל]\u0006 \u0003עצה ממרדכי\u0004 מה לעשות כדי שתגלה לו אסתר, \u0003אמר\u0004 לו מרדכי: כלל הוא \u0003אין אשה מתקנאה אלא בירך חבירתה,\u0004 כלומר, אין אשה מקנאה אלא באשה אחרת, ולכן קח לך עוד נשים, \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003לא גליא ליה\u0004 \u0005[גילתה לו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אין אסתר מגדת מולדתה\"\u0004 (אסתר ב, כ).","\u0003אמר ר' אלעזר: מאי דכתיב\u0004 \u0005[מהו\u0006 \u0005שנאמר]:\u0006"],["\u0003\"לא יגרע מצדיק עיניו\u0004 ואת מלכים לכיסא ויושיבם לנצח ויגבהו\u0003\"\u0004 (איוב לו, ז), לומר: \u0003בשכר צניעות שהיתה בה ברחל זכתה ויצא ממנה שאול\u0004 שהיה צנוע, \u0003ובשכר צניעות שהיה בו בשאול זכה ויצאה ממנו אסתר.\u0004","ומסבירים: \u0003ומאי\u0004 \u0005[ומה]\u0006 \u0003צניעות היתה בה ברחל? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויגד יעקב לרחל כי אחי אביה הוא\"\u0004 (בראשית כט, יב), ושואלים: \u0003וכי אחי אביה הוא? והלא בן אחות אביה הוא?\u0004","\u0003אלא\u0004 כך צריך לומר, שכשראה אותה \u0003אמר לה: מינסבא\u0004 \u0005[\u0006האם \u0005תינשאי]\u0006 \u0003לי? אמרה ליה\u0004 \u0005[לו]\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003מיהו\u0004 \u0005[אבל],\u0006 \u0003אבא רמאה\u0004 \u0005[רמאי]\u0006 \u0003הוא ולא יכלת ליה\u0004 \u0005[תוכל לו],\u0006 לכך \u0003אמר לה\u0004 שאחי אביה הוא, כלומר: \u0003אחיו אנא\u0004 \u0005[אני]\u0006 \u0003ברמאות. אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003ומי שרי לצדיקי לסגויי ברמיותא\u0004 \u0005[והאם מותר לצדיקים ללכת ברמאות]?\u0006 \u0003אמר לה: אין\u0004 \u0005[כן],\u0006 שנאמר: \u0003\"עם נבר תתבר ועם עקש תתפל\"\u0004 (שמואל ב' כב, כז), כלומר, שעם כל אדם יש לנהוג כראוי לו.","\u0003אמר לה\u0004 יעקב: \u0003ומאי רמיותא\u0004 \u0005[ומה הרמאות]\u0006 שיש בידו לעשות? \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אית לי אחתא דקשישא מינאי ולא מנסיב לי מקמה\u0004 \u0005[יש לי אחות שגדולה ממני ולא ישיא אותי לפניה]\u0006 ויתן אותה לך במקומי. \u0003מסר לה סימנים\u0004 שתתן לו כשיהיו יחד, שידע שהיא — היא,","\u0003כי מטא ליליא\u0004 \u0005[כשהגיע ליל\u0006 הנישואין\u0005]\u0006 \u0003אמרה\u0004 רחל בלבה: \u0003השתא מיכספא אחתאי\u0004 \u0005[עכשיו תתבייש אחותי],\u0006 שיבקש ממנה יעקב הסימנים ולא תדע. \u0003מסרתינהו ניהלה\u0004 \u0005[מסרה אותם לה].\u0006 \u0003והיינו דכתיב\u0004 \u0005[והוא שנאמר]:\u0006 \u0003\"ויהי בבקר והנה היא לאה\"\u0004 (בראשית כט, כה), ולכאורה \u0003מכלל\u0004 הדברים לומד אתה ש\u0003עד השתא\u0004 \u0005[עכשיו]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003לאה היא? אלא: מתוך סימנים שמסרה רחל ללאה לא הוה ידע עד השתא\u0004 \u0005[לא היה יודע עד עכשיו]\u0006 שהיא לאה. \u0003לפיכך זכתה ויצא ממנה שאול.\u0004","\u0003ומה צניעות היתה בשאול? דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ואת דבר המלוכה לא הגיד לו אשר אמר שמואל\"\u0004 (שמואל א' י, טז), ומשום כך \u0003זכה ויצאת ממנו אסתר.\u0004 כיוצא בדבר \u0003אמר ר' אלעזר: כשהקדוש ברוך הוא פוסק גדולה לאדם — פוסק לבניו ולבני בניו עד סוף כל הדורות, שנאמר: \"\u0004לא יגרע מצדיק עיניו ואת מלכים לכסא \u0003וישיבם לנצח ויגבהו\"\u0004 (איוב לו, ז). \u0003ואם הגיס דעתו\u0004 (התגאה) בכך — \u0003הקדוש ברוך הוא משפילו, שנאמר:\u0004 בפסוק הבא: \u0003\"ואם אסורים בזקים\u0004 ילכדון בחבלי עני \u0003\"\u0004. (איוב לו, ח).","נאמר: \u0003\"ואת מאמר מרדכי אסתר עשה\"\u0004 (אסתר ב, כ), \u0003אמר ר' ירמיה: שהיתה\u0004 ממשיכה ו\u0003מראה דם נדה לחכמים\u0004 לשאול אם טהורה היא. נאמר: \u0003\"כאשר היתה באמנה אתו\"\u0004 (אסתר ב, כ), \u0003אמר רבה בר לימא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: שהיתה עומדת מחיקו של אחשורוש וטובלת ויושבת בחיקו של מרדכי.\u0004","נאמר \u0003\"בימים ההם ומרדכי יושב בשער המלך קצף בגתן ותרש\"\u0004 (אסתר ב, כא), \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: הקציף הקדוש ברוך הוא אדון על עבדיו\u0004 כדי \u0003לעשות רצון צדיק. ומנו\u0004 \u0005[ומי הוא\u0006 זה\u0005]?\u0006 \u0003יוסף,\u0004 שקצף פרעה על שריו והכניסם לבית הסוהר, ואמר שר המשקים \u0003\"ושם אתנו נער עברי\u0004 עבד לשר הטבחים ונספר לו ויפתר לנו את חלומותינו איש כחלומו פתר\u0003\"\u0004 (בראשית מא, יב),","וכן הקציף \u0003עבדים על אדוניהם לעשות נס לצדיק\u0004 אחר, \u0003ומנו\u0004 \u0005[ומי הוא]?\u0006 \u0003מרדכי, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויודע הדבר למרדכי\"\u0004 (אסתר ב, כב)","ומספרים כיצד נודע לו? \u0003אמר ר' יוחנן: בגתן ותרש שני טרסיים\u0004 (בני העם הטרסי) \u0003הוו\u0004 \u0005[היו]\u0006 \u0003והיו מספרין\u0004 (מדברים) ביניהם \u0003בלשון טורסי, ואומרים: מיום שבאת זו\u0004 אסתר \u0003לא ראינו שינה בעינינו\u0004 שהיה עם אסתר כל הלילה ומטריד אותם בבקשות לסיפוק תאוותיו, ולכך \u0003בא ונטיל ארס בספל\u0004 שהוא שותה \u0003כדי שימות. והן לא היו יודעין כי מרדכי מיושבי לשכת הגזית היה, והיה יודע בשבעים לשון.\u0004","\u0003אמר לו\u0004 האחד לחבירו: \u0003הלא אין משמרתי ומשמרתך שוה\u0004 ואיך נוכל לסדר את הדבר בינינו? \u0003אמר לו: אני אשמור משמרתי ומשמרתך. והיינו דכתיב\u0004 \u0005[והוא שנאמר]:\u0006 \u0003\"ויבקש הדבר וימצא\"\u0004 (אסתר ב, כג), ומה נמצא — \u0003שלא נמצאו במשמרתן.\u0004","נאמר: \u0003\"אחר הדברים האלה\"\u0004 (אסתר ג, א), ושואלים: \u0003אחר מאי\u0004 \u0005[מה]?\u0006 מה הקשר בין הדברים? \u0003אמר רבא: אחר שברא הקדוש ברוך הוא רפואה למכה,\u0004 שהרי תחילת הדבר שבסופו הביא לנס היה כבר קודם לכן וקרה עוד לפני הגזירה עצמה.","ש\u0003אמר ריש לקיש: אין הקדוש ברוך הוא מכה את ישראל אלא אם כן בורא להם רפואה תחילה, שנאמר: \"כרפאי לישראל ונגלה עון אפרים\"\u0004 (הושע ז, א) \u0003אבל\u0004 ביחס ל\u0003אומות העולם אינו כן — מכה אותן ואחר כך בורא להם רפואה, שנאמר: \"ונגף ה' את מצרים נגף ורפוא\"\u0004 (ישעיה יט, כב).","נאמר: \u0003\"ויבז בעיניו לשלח יד במרדכי לבדו\u0004 כי הגידו לו את עם מרדכי ויבקש המן להשמיד את כל היהודים\u0003\"\u0004 (אסתר ג, ו), \u0003אמר רבא: בתחילה\u0004 רצה שתפגע הגזירה \u0003במרדכי לבדו, ולבסוף בעם מרדכי, ומנו\u0004 \u0005[ומי הוא] —\u0006 \u0003רבנן\u0004 \u0005[חכמים]\u0006 שהם עמו המיוחד של מרדכי, \u0003ולבסוף בכל היהודים.\u0004","\u0003\"הפיל פור הוא הגורל\"\u0004 (אסתר ג, ז), \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003כיון שנפל פור בחדש אדר שמח שמחה גדולה,\u0004 שראה בכך סימן טוב לקיום תוכניתו. \u0003אמר: נפל לי פור בירח\u0004 (בחודש) \u0003שמת בו משה\u0004 והוא איפוא זמן פורענות לישראל, \u0003ולא היה יודע ש\u0004אמנם \u0003בשבעה באדר מת\u0004 משה, אבל גם \u0003בשבעה באדר נולד\u0004 ויש בו גם שמחה לישראל.","אמר המן לאחשורוש: \u0003\"ישנו עם אחד\"\u0004 (אסתר ג, ח), \u0003אמר רבא: ליכא דידע לישנא בישא\u0004 \u0005[אין\u0006 מי \u0005שיודע\u0006 לומר \u0005לשון הרע]\u0006 \u0003כהמן, אמר ליה\u0004 \u0005[לו]\u0006 לאחשורוש: \u0003תא ניכלינהו\u0004 \u0005[בוא נכלה אותם]\u0006 את היהודים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אחשורוש: \u0003מסתפינא מאלהיו דלא ליעביד בי כדעבד מקמאי\u0004 \u0005[מתיירא אני מאלהיהם שלא יעשה בי כמו שעשה בראשונים]\u0006 שעמדו כנגדם. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ישנו מן המצות\u0004 (צורת ביטוי שונה למלה ל\"ישנו\"), כלומר; שחדלו לקיים מצוות.","\u0003אמר ליה\u0004 אחשורוש: \u0003אית בהו רבנן\u0004 \u0005[יש בהם חכמים]\u0006 המקיימים מצוות. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עם אחד הן,\u0004 כלומר, כולם שוים, וכולם אינם מקיימים.","\u0003שמא תאמר קרחה אני עושה במלכותך —\u0004 שאם נשמיד עם שלם יהיה שטח שומם בתוך המלכות — הרי \u0003מפוזרין הם בין העמים,\u0004 והשמדתם לא תביא לידי שממה במקומות בהם הם נמצאים; \u0003שמא תאמר: אית\u0004 \u0005[יש]\u0006 \u0003הנאה מינייהו\u0004 \u0005[מהם];\u0006 עם זה הוא \u0003\"מפורד\"\u0004 (אסתר ג, ח) \u0003— כפרידה זו\u0004 שהיא עקרה \u0003שאינה עושה פירות, ושמא תאמר איכא מדינתא מינייהו\u0004 \u0005[יש מדינה מהם],\u0006 שיש עיר שלמה מהם — דע לך שהם מפוזרים \u0003\"בכל מדינות מלכותך\"\u0004 (אסתר ג, ח), ואין מקום מושבם אחד.","\u0003\"ודתיהם שנות מכל עם\"\u0004 (אסתר ג, ח) \u0003— דלא אכלי מינן ולא נסבי מינן ולא מנסבי לן\u0004 \u0005[שאינם אוכלים משלנו, אינם נושאים\u0006 נשים \u0005משלנו ואינם משיאים לנו].\u0006 \u0003\"ואת דתי המלך אינם עשים\"\u0004 (אסתר ג, ח) \u0003— דמפקי לכולא שתא ב־שה\"י פה\"י\u0004 \u0005[שמוציאים את כל השנה\u0006 בבטלה, שבכל פעם הם אומרים \u0005שבת היום\u0006 (שה\"י), \u0005פסח היום\u0006 (פה\"י)\u0005].\u0006 \u0003\"ולמלך אין שוה להניחם\"\u0004 (אסתר ג, ח) \u0003— דאכלו ושתו ומבזו ליה\u0004 \u0005[ש\u0006הם \u0005אוכלים ושותים ומבזים אותה]\u0006 את ה\u0003מלכות.\u0004 וראיה לדבר — \u0003אפילו נופל זבוב בכוסו של אחד מהם,\u0004 מה הוא עושה? \u0003זורקו\u0004 את הזבוב \u0003ושותהו\u0004 את הכוס, \u0003ואם אדוני המלך נוגע בכוסו של אחד מהם חובטו בקרקע\u0004 את כל הכוס, \u0003ואינו שותהו\u0004 (שהרי יין שנגע בו גוי אסור בשתייה).","נאמר: \u0003\"אם על המלך טוב יכתב לאבדם ועשרת אלפים ככר כסף\u0004 אשקול על ידי עושי המלאכה להביא אל גנזי המלך\u0003\"\u0004 (אסתר ג, ט), \u0003אמר ריש לקיש: גלוי וידוע\u0004 היה מראש \u0003לפני מי שאמר והיה העולם שעתיד המן לשקול שקלים על ישראל, לפיכך הקדים שקליהן\u0004 של ישראל שנותנים למקדש \u0003לשקליו.\u0004","\u0003והיינו דתנן\u0004 \u0005[והוא ששנינו\u0006 במשנה\u0005]:\u0006 \u0003באחד באדר משמיעין\u0004 (מודיעים) בית דין \u0003על השקלים\u0004 שיביאו שקלים לבית המקדש לצורך קרבנות ציבור \u0003ועל הכלאים\u0004 שיש לבערם מן השדות עם תחילת הצמיחה. ויוצא שישראל נותנים שקלים באחד באדר, לפני שמגיע זמן הפורים.","\u0003\"ויאמר המלך להמן הכסף נתון לך והעם לעשות בו כטוב בעיניך\"\u0004 (אסתר ג, יא), \u0003אמר ר' אבא:\u0004"]]};
